#include<string>
#include<vector>
std::vector<int> z_algorithm(const std::string& S) {
  std::vector<int> Z(S.size(), S.size());
  for(int i = 1, L = 0, R = 0; i < S.size(); ++i) {
    if(i > R) {
      L = R = i;
      while(R < S.size() && S[R - L] == S[R]) ++R;
      Z[i] = R-- - L;
    } else {
      if(Z[i - L] < R - i + 1) Z[i] = Z[i - L];
      else {
        L = i;
        while(R < S.size() && S[R - L] == S[R]) ++R;
        Z[i] = R-- - L;
      }
    }
  }
  return Z;
}

#include<bits/stdc++.h>
using namespace std;

int update(const auto& S, const auto& CS, const auto& Z, int j, int best) {
  if(CS.empty()) return 1;
  if(best == -1) {
    // CS <=> CS[0...j] + S
    if(j == CS.size()) return 1;                       // CS[0...j] + S = CS + S
    auto z = Z[S.size() + j];
    if(z == S.size() && j + z == CS.size()) return 1;  // CS = CS[0...j] + S
    if(z >= S.size()) return 0;                        // CS > CS[0...j] + S
    if(j + z >= CS.size()) return -1;                  // CS < CS[0...j] + S
    if(CS[j + z] < S[z]) return -1;                    // CS < CS[0...j] + S
    return 1;                                          // CS > CS[0...j] + S
  } else {
    // CS[0...best] + S <=> CS[0...j] + S
    if(j == best) return 0;
    if(j < best) {
      auto z = Z[S.size() + j];
      // CS[0...best] と CS[0...j] + S との比較
      if(j + z < best) {
        if(z >= S.size())    return 0;
        if(CS[j + z] < S[z]) return -1;
        else                 return 1;
      }
      // CS[0...best] + S の S 上の要素と, CS[0...j] + S の S の上の要素とを比較
      if(j + z < best + S.size()) {
        auto d = best - j;
        z = Z[d];
        if(d + z >= S.size()) return 0;
        if(S[z] < S[d + z])   return -1;
        else                  return 1;
      }
      // CS[0...best] + S = CS[0...j] + S
      return 1;
    } else {
      auto z = Z[S.size() + best];
      // CS[0...best] + S と CS[0...j] との比較
      if(best + z < j) {
        if(z >= S.size())       return 0;
        if(S[z] < CS[best + z]) return -1;
        else                    return 1;
      }
      // CS[0...best] + S の S 上の要素と, CS[0...j] + S の S の上の要素とを比較
      if(best + z < j + S.size()) {
        auto d = j - best;
        z = Z[d];
        if(d + z >= S.size()) return 0;
        if(S[d + z] < S[d])   return -1;
        else                  return 1;
      }
      // CS[0...best] + S = CS[0...j] + S
      return 1;
    }
  }
}

int main() {
  int N, K;
  cin >> N >> K;
  vector<string> S(N);
  for(auto& i: S) cin >> i;

  vector<vector<bool>> reach(N + 1, vector<bool>(K + 1));
  reach[N][0] = true;
  for(int i = N - 1; 0 <= i; --i) {
    reach[i] = reach[i + 1];
    for(int j = K; S[i].size() <= j; --j) reach[i][j] = reach[i][j] | reach[i][j - S[i].size()];
  }

  vector<string> CS(N + 1);
  vector<vector<bool>> dp(N + 1, vector<bool>(K + 1));
  dp[0][0] = true;
  for(int i = 0; i < N; ++i) {
//     cout<<"CS: "<<CS[i]<<endl;
//     cout<<"dp:";for(auto k:dp[i])cout<<" "<<k;cout<<endl;
//     cout<<"nx:";for(auto k:reach[i+1])cout<<" "<<k;cout<<endl;
    auto Z = z_algorithm(S[i] + CS[i]);
    int best = -1;
    for(int j = 0; j <= K - S[i].size(); ++j) {
      if(!dp[i][j]) continue;
      if(!reach[i + 1][K - j - S[i].size()]) continue;
      if(0 >= update(S[i], CS[i], Z, j, best)) continue;
      best = j;
    }
    CS[i + 1] = CS[i];
    if(best != -1) {
      auto s = CS[i].substr(0, best) + S[i];
      if(s + "~" < CS[i + 1] + "~") CS[i + 1] = s;
    }

    int dif = 0;
    while(dif < min(CS[i].size(), CS[i + 1].size()) && CS[i][dif] == CS[i + 1][dif]) ++dif;
    if(dif == min(CS[i].size(), CS[i + 1].size())) dif = 1 + max(CS[i].size(), CS[i + 1].size());
    for(int j = 0; j <= K; ++j) {
      if(!dp[i][j]) continue;
      if(best == -1) {
        if(!reach[i + 1][K - j]) continue;
        dp[i + 1][j] = true;
      } else {
        if(j < dif || 0 <= update(S[i], CS[i], Z, j, best)) if(reach[i + 1][K - j]) dp[i + 1][j] = true;
        if(K < j + S[i].size()) continue;
        if(!reach[i + 1][K - j - S[i].size()]) continue;
        if(0 > update(S[i], CS[i], Z, j, best)) continue;
        dp[i + 1][j + S[i].size()] = true;
      }
    }
  }

  cout << CS[N] << endl;
}

