bool dp(int id, int sisa){
	if(sisa < 0) return 0;
	if(sisa == 0) return 1;
	if(id>n) return 0;
	if(vis[id][sisa]) return memo[id][sisa];
	vis[id][sisa] = 1;
	bool ret = 0;
