	return memo[id][sisa] = ret;
}

string hsl = "";

int z_tab[20005];

void gen_z_algo(int id){
	string tmp = li[id] + '$' + hsl;
	int l = 0;
	int r = 0;
	int pan = tmp.size();
//	cout << "Z TABLE FOR " << tmp << endl;
	for(int i=1;i<pan;i++){
		if(r < i){ // kalau diluar prefix terpanjang
			l = r = i;
			while(r < pan && tmp[r-l] == tmp[r]) r++;
			z_tab[i] = r-l; r--;
		} else {
			int k = i-l;
			if(z_tab[k] < r-i+1){
				z_tab[i] = z_tab[k];
			} else { // brute force
				l = i;
				while(r < pan && tmp[r-l] == tmp[r]) r++;
				z_tab[i] = r-l; r--;
			}
		}
//		cout << z_tab[i] << " ";
	}
//	cout << endl;
	return;
}

