	REP(i,n){
		scanf("%s",strBuf+off);
		len[i]=strlen(strBuf+off);
		Zalgo(strBuf+off,len[i],zBuf+off);
		off+=len[i]+1;
	}
	dp[n][0]=true;
	for(int i=n-1;i>=0;i--)
		REP(j,k+1)
			dp[i][j]=dp[i+1][j]|(j<len[i]?false:dp[i+1][j-len[i]]);
	can[0]=true;
	int s=0,*lcp=lcpBuf+k,*z=zBuf;
	char *cur=curBuf+k,*str=strBuf;
