						mn=j;
					else if(str[p+z[p]]>str[z[p]])
						mn=j;
				}
			}
		}
		if(mn>=0){
			FOR(j,mn+1,s+1)
				can[j]=false;
			REP(j,len[i])
				cur[j+mn]=str[j];
