					qr[now^1][++cntn]=make_pair(id,num+1);
			}
			else{
				for(int j=id+1;j<=n;j++)
					if(k+1>=val[j]&&dp[j+1][k+1-val[j]]==1){
						if(s[j][0]==minc)
							qr[now^1][++cntn]=make_pair(j,1);
					}
			}
		}
		now^=1;
		cnt=cntn;
	}
}

