const ll H=23232;
const ll MOD=1e9+9;
int n,k;
ll Pow[10005];
string S[2005],s[2005];
ll HashS[10005];
ll Hash[10005];
int len[2005];
int Len;
int path[10005];// which string occupies the position
bool term[10005];//termination
bitset<10005> can[2005];
inline void printAns(int l){
	if (l==0) return;
	printAns(l-len[path[l]]);
	cout<<S[path[l]];
}
int main(){
	ios::sync_with_stdio(false);
	Pow[0]=1;
	for (int i=1;i<10005;++i) Pow[i]=Pow[i-1]*H%MOD;
	cin>>n>>k;
	for (int i=1;i<=n;++i) cin>>S[i],len[i]=S[i].size(),s[i]="."+S[i];
	can[n][k]=1;
	for (int i=n;i>=1;--i) can[i-1]=can[i]|(can[i]>>len[i]);
	term[0]=1;Len=0;
	for (int i=1;i<=n;++i){
		if (len[i]>k) continue;
		for (int j=1;j<=len[i];++j) HashS[j]=(HashS[j-1]+s[i][j])*H%MOD;
		int bestPos=k+1,bestChar,bestInsert;
		vector<int> PossibleTerm;
		for (int j=0;j+len[i]<=k&&j<=Len;++j){
			if (!term[j]||!can[i][j+len[i]]) continue;
			if (j>=bestPos) break;
			if (j==Len){// last chance: directly add this string
				if (bestPos>Len+1||bestPos==Len+1&&bestChar>=s[i][1]) bestPos=j+1,bestChar=s[i][1],bestInsert=j;
				break;
			}
			int L=j,R=j+len[i];//L:must same;  R:must diff
			if (R<=Len&&Hash[R]==(Hash[j]*Pow[len[i]]+HashS[len[i]])%MOD){//completely the same, but possible termination
				PossibleTerm.pb(R);continue;
			} 
			while(L<R-1&&L<bestPos){
				int M=L+R>>1;
				if (M<=Len&&Hash[M]==(Hash[j]*Pow[M-j]+HashS[M-j])%MOD) L=M;
				else R=M;
			}
			if (R>bestPos) continue;
			if (R>Len){//the original is a prefix
				// you may add this string as answer won't get worse
				if (bestPos>R||bestPos==R&&bestChar>=s[i][R-j]) bestPos=R,bestChar=s[i][R-j],bestInsert=j;
				continue;
			}
			int oldchar,curchar=s[i][R-j];
			for (int ch='a';ch<='z';++ch) if (Hash[R]==(Hash[L]+ch)*H%MOD) oldchar=ch;
			if (curchar<oldchar) if (bestPos>R||bestPos==R&&bestChar>=curchar) bestPos=R,bestChar=curchar,bestInsert=j;
		}
		if (bestPos<=k){// valid update
			for (int p=bestInsert+1;p<=bestInsert+len[i];++p) Hash[p]=(Hash[p-1]+s[i][p-bestInsert])*H%MOD;
			for (int p=bestInsert+1;p<=k;++p) term[p]=path[p]=0;
			term[Len=bestInsert+len[i]]=1;
			path[Len]=i;
		}
		for (int j=0;j<PossibleTerm.size();++j) term[PossibleTerm[j]]=1,path[PossibleTerm[j]]=i;
	}
	printAns(k);
	cout<<endl;
	return 0; 
}

