#include<string>
#include<vector>
std::vector<int> z_algorithm(const std::string& S) {
  std::vector<int> Z(S.size());
  for(int i = 1, L = 0, R = 0; i < S.size(); ++i) {
    if(i > R) {
      L = R = i;
      while(R < S.size() && S[R - L] == S[R]) ++R;
      Z[i] = R-- - L;
    } else {
      if(Z[i - L] < R - i + 1) Z[i] = Z[i - L];
      else {
        L = i;
        while(R < S.size() && S[R - L] == S[R]) ++R;
        Z[i] = R-- - L;
      }
    }
  }
  return Z;
}

#include<bits/stdc++.h>
using namespace std;

int main() {
  int N, K;
  cin >> N >> K;
  vector<string> S(N);
  for(auto& i: S) cin >> i;

  vector<vector<bool>> reach(N + 1, vector<bool>(K + 1));
  reach[N][0] = true;
  for(int i = N - 1; 0 <= i; --i) {
    reach[i] = reach[i + 1];
    for(int j = K; S[i].size() <= j; --j) reach[i][j] = reach[i][j] | reach[i][j - S[i].size()];
  }

  vector<string> CS(N + 1);
  vector<vector<bool>> dp(N + 1, vector<bool>(K + 1));
  dp[0][0] = true;
  for(int i = 0; i < N; ++i) {
//     cout<<"CS: "<<CS[i]<<endl;
//     cout<<"dp:";for(auto k:dp[i])cout<<" "<<k;cout<<endl;
//     cout<<"nx:";for(auto k:reach[i+1])cout<<" "<<k;cout<<endl;
    CS[i + 1] = CS[i] + "~";
    bool update = false;
    for(int j = 0; j <= K - S[i].size(); ++j) {
      if(!dp[i][j]) continue;
      if(!reach[i + 1][K - j - S[i].size()]) continue;
      auto s = CS[i].substr(0, j) + S[i] + "~";
      if(CS[i + 1] <= s) continue;
      CS[i + 1] = s;
      update = true;
    }
    CS[i + 1].pop_back();

    auto Z = z_algorithm(S[i] + "~" + CS[i]);
    for(int j = 0; j <= K; ++j) {
      if(!dp[i][j]) continue;
      if(!update) {
        if(!reach[i + 1][K - j]) continue;
        dp[i + 1][j] = true;
      } else {
        auto z = Z[S[i].size() + 1 + j];
        // (CS[i] == CS[i+1]) || (CS[i][0..j] == CS[i+1][0..j]) || (CS[i][j+z] >= CS[i+1][j+z])
        if((z == S[i].size()) || (j <= z) || (CS[i][j + z] >= S[i][z])) dp[i + 1][j] = true;
        if(K < j + S[i].size()) continue;
        if(!reach[i + 1][K - j - S[i].size()]) continue;
        // CS[i][0..j]+S[i] と CS[i+1][0..j] を比較したい
        // ここで CS[i+1] == CS[i][0..p]+S[i] とおく
        auto p = CS[i + 1].size() - S[i].size();
        // CS[i] == CS[i+1]
        if(j == p) dp[i + 1][j + S[i].size()] = true;
        if(z == S[i].size()) dp[i + 1][j + S[i].size()] = true;
        // CS[i][0..j]+S[i]のS[i]の部分と、CS[i][0..p]の部分で比較
        if(j + z < p && CS[i][j + z] >= S[i][z]) dp[i + 1][j + S[i].size()] = true;
        if(j + z < p) continue;
        // CS[i][0..j]+S[i]のS[i]の部分と、CS[i][0..p]+S[i]のS[i]の部分で比較
        auto d = p - j;
        z = Z[d];
        if(z >= S[i].size() - d) dp[i + 1][j + S[i].size()] = true;
        if(S[i][z] >= S[i][z + d]) dp[i + 1][j + S[i].size()] = true;
      }
    }
  }

  cout << CS[N] << endl;
}

