string fin(ll x,ll k){
    if(k==0){
        return "";
    }
    string ans;
    ans+=(char)('z'+1);
    if(s[x].size()<=k && dp[x+1][k-s[x].size()]){
        ans=s[x]+fin(x+1,k-s[x].size());
    }
    if(dp[x+1][k]){
        ans=min(ans,fin(x+1,k));
    }
    return ans;
}
