bool cmp( int a, int b ){
	if ( s[a] == s[b] ) return a < b;
	return s[a] < s[b];
}

bool cmprank( int a, int b ){
	return ra[a] < ra[b];
}

int dfs( int pos, int sz ){
	if ( sz > k ) return false;
	if ( sz == k ) return true;
	if ( pos == n ) return false;
	int &ans = dp[pos][sz];
	if ( ans != -1 ) return ans;
	ans = dfs(pos+1,sz);
	if ( sz + s[pos].size() <= k ) ans = max( ans, dfs(pos+1, sz + s[pos].size()));
	return ans;
}

string getstr( int pos, int sz ){

	priority_queue < pair < string , pair < int , int > > , vector < pair < string , pair < int , int > > >, greater < pair < string , pair < int , int > > > > pq;
	pq.push(make_pair("", make_pair(pos,sz)));
	while ( !pq.empty() ){
		string cur = pq.top().first;
		pos = pq.top().second.first;
		sz = pq.top().second.second;
		pq.pop();
		if ( sz == k ) return cur;
		if ( pos >= n || vs[pos][sz] ) continue;
		vs[pos][sz] = true;

		int last = -1;
		for ( int i = 0; i < rmq[pos].size(); i++ ){
			int id = rmq[pos][i];
			if ( dfs(id+1, sz + s[id].size()) ){
				if ( last != -1 ){
					if ( s[last].size() >= s[id].size() ) continue;
					int len = s[last].size()-1;
					if ( Hash[last][len] != Hash[id][len] ) continue;
					last = id;
				} else {
					last = id;
				}

				string tmp = cur + s[id];
				if ( vs[id+1][sz+ s[id].size()] ) continue;
				pq.push(make_pair(tmp, make_pair(id+1, sz + s[id].size())));
			}
		}
	}

	assert(1==2);
}

