int n, k;
string str[2000];

int memo1[2000][10005];
int dp1(int now, int len){ // returns 1 if reach end, 0 otherwise
	if(now == n){
		return len == k;
	}

	int& ret = memo1[now][len];
	if(ret != -1)return ret;

	ret = dp1(now+1, len);
	if(len+str[now].size() <= k)ret |= dp1(now+1, len+str[now].size());
	return ret;
}

