		H0 = cur[mid];
		if(mid <= pos) H1 = cur[mid];
		else H1 = cur[pos] * fac[mid - pos] + Hash[mid - pos];
		if(H0 == H1) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	if(ans == R) {
        if(st.size() > now.size()) return st;
        else return now;
	}
	else {
		ch0 = now[ans]; ch1 = st[ans];
		if(ch0 > ch1) return st;
		else return now;
	}
}

