void write(int x, char c) {
	ans[x] = c;
	sans[x] = sans[x-1] + pii(c, c) * PW[x];
}

pii get_h1(int l, int r) {
	return (sans[r] - sans[l-1]) * PW[10005 - r];
}

vector <pii> In[2020];
pii get_h2(int x, int idx) {
	return In[x][idx] * PW[10005 - idx];
}

pair<string, int> X[2020];
int main() {
	PW[0] = pii(1, 1); for(int i=1;i<10010;i++) PW[i] = pii(PV, PV) * PW[i-1];
	scanf("%d%d", &N, &K);
	for(int i=1;i<=N;i++) {
		scanf("%s", buf);
		s[i] = (string)buf;
		X[i] = make_pair(s[i], i);
		pii now = pii(0, 0);
		for(int j=0;buf[j];j++) {
			now = now + pii(buf[j], buf[j]) * PW[j];
			In[i].pb(now);
		}
	}
	sort(X+1, X+1+N);

	for(int i=0;i<=K;i++) dp[i] = -1;
	dp[0] = N+1;
	for(int i=N;i;i--) {
		int x = szz(s[i]);
		for(int j=K;j>=x;j--) if(dp[j] == -1) {
			if(dp[j-x] != -1) dp[j] = i;
		}
	}
	for(int i=0;i<10010;i++) min_index[i] = N + 1, write(i, 'z' + 1);
	min_index[0] = 0;

	for(int L=0;L<=K;L++) {
		if(min_index[L] == N + 1) continue;
		int idx = min_index[L];
		for(int a=1;a<=N;a++) {
			int j = X[a].Se;
			if(j <= idx) continue;
			int lj = szz(X[a].Fi);
			if(L + lj > K || dp[K-L-lj] <= j) continue;

			int op = 0;
			int low = 0, high = lj - 1, fd = -1;
			while(low <= high) {
				int mid = (low + high) >> 1;
				if(get_h1(L+1, L+1+mid) != get_h2(j, mid)) fd = mid + 1, high = mid - 1;
				else low = mid + 1;
			}
			if(fd != -1) {
				op = (ans[L+fd] > X[a].Fi[fd-1]) ? 1 : -1;
			}
			if(op == -1) break;
			if(op == 0) {
				if(min_index[L+lj] > j) {
					min_index[L+lj] = j;
				}
			}
			else {
				for(int b=L+fd;b<=L+lj;b++) min_index[b] = N + 1, write(b, X[a].Fi[b-L-1]); // ans[b] = X[a].Fi[b-L-1];
				for(int b=L+lj+1;b<=K;b++) min_index[b] = N + 1, write(b, 'z'+ 1); // ans[b] = 'z' + 1;
				min_index[L+lj] = j;
			}
		}
	}
	for(int i=1;i<=K;i++) printf("%c", ans[i]); puts("");

	return 0;
}

