        z.cal();
        for(int j=0;j<l1;j++) z1[j] = z.z[j];
        for(int j=0;j<l2;j++) z2[j] = z.z[l1+1+j];

        int idx = 1e9;
        for(int j=0;j<=l2;j++){
            if(j+l1 <= k && vis[j] && ok[i+1][j+l1]){
                if(idx == 1e9){
                    if(j == l2) idx = j;
                    else{
                        int val = z2[j];
                        if(val <= l1){
