vector<int> get_z(string const& s) {
  int const n = (int) s.size();
  vector<int> z(n);
  for (int i = 1, l = 0, r = 0; i < n; ++i) {
    int k = max(0, min(z[i - l], r - i));
    while (i + k < n && s[k] == s[i + k]) ++k;
    if (i + k > r) {
      l = i;
      r = i + k;
    }
    z[i] = k;
  }
  return z;
}

int main() {
#ifdef GOLIKOV
  assert(freopen("in", "rt", stdin));
