  int n, k;
  cin >> n >> k;
  vector<string> a(n);
  for (auto& x : a) {
    cin >> x;
  }
  vector<vector<int>> can(n + 1, vector<int>(k + 1));
  can[n][0] = 1;
  for (int i = n - 1; i >= 0; --i) {
    int const cur = (int) a[i].size();
    for (int len = 0; len <= k; ++len) {
      can[i][len] = can[i + 1][len];
      if (len >= cur) {
        can[i][len] |= can[i + 1][len - cur];
      }
    }
  }

  char const END = 0;

  vector<int> alive(k + 1);
  int const DEAD = 0;
  int const PREF = 1;
  int const CONCAT = 2;
  alive[0] = PREF;
  string s;
  for (int i = 0; i < n; ++i) {
    auto const& t = a[i];
    int const len_t = (int) t.size();
    auto z_t = get_z(t);
    auto big = t;
    big.push_back('#');
    big += s;
    auto z_big = get_z(big);
    auto lcp_t = [&](int suff) {
      if (suff >= len_t) return 0;
      if (!suff) return len_t;
      return z_t[suff];
    };
    auto lcp_st = [&](int suff) {
      return z_big[len_t + 1 + suff];
    };

    auto get_char = [&](int pref, int take, int pos) -> char {
      if (pos < pref) {
        return s[pos];
      }
      if (!take) {
        return END;
      }
      pos -= pref;
      return pos < len_t ? t[pos] : END;
    };

    auto find_lcp = [&](int l1, int t1, int l2, int t2) {
      if (l1 > l2) {
        swap(l1, l2);
        swap(t1, t2);
      }
      if (!t1) {
        return l1;
      }
      auto lcp = lcp_st(l1);
      if (!t2 || lcp == len_t || lcp < l2 - l1) {
        return l1 + lcp;
      }
      return l1 + lcp + lcp_t(lcp);
    };

    auto new_alive = alive;
    for (int len = 0; len + len_t <= k; ++len) {
      if (!alive[len]) {
        continue;
      }
      if (!can[i + 1][k - len - len_t]) {
        continue;
      }
      if (!alive[len + len_t]) {
        new_alive[len + len_t] = CONCAT;
        continue;
      }
      auto lcp = find_lcp(len, 1, len + len_t, 0);
      if (get_char(len, 1, lcp) < get_char(len + len_t, 0, lcp)) {
        new_alive[len + len_t] = CONCAT;
      }
    }
    int last = -1;
    for (int len = k; len >= 0; --len) {
      auto t1 = new_alive[len];
      if (t1 == DEAD) {
        continue;
      }
      if (last < 0) {
        last = len;
        continue;
      }
      auto t2 = new_alive[last];
      auto has1 = t1 == CONCAT;
      auto has2 = t2 == CONCAT;
      auto pref1 = has1 ? len - len_t : len;
      auto pref2 = has2 ? last - len_t : last;
      auto lcp = find_lcp(pref1, has1, pref2, has2);
      if (lcp == len) {
        continue;
      }
      if (get_char(pref1, has1, lcp) < get_char(pref2, has2, lcp)) {
        last = len;
      } else {
        new_alive[len] = DEAD;
      }
    }
    for (int l = last + 1; l <= k; ++l) {
      alive[l] = DEAD;
    }
    if (new_alive[last] == CONCAT) {
      s.resize(last - len_t);
      s += t;
    }
    for (int l = last; l >= 0; --l) {
      if (new_alive[l] != DEAD) {
        alive[l] = PREF;
      }
    }
  }
  cout << s << '\n';

