void Zalgo(char* str,int s,int* lcp){
	fill(lcp,lcp+s+1,0);
	int p=0;
	FOR(i,1,s){
		if(i+lcp[i-p]<p+lcp[p])
			lcp[i]=lcp[i-p];
		else{
			lcp[i]=max(0,p+lcp[p]-i);
			while(i+lcp[i]<s&&str[lcp[i]]==str[i+lcp[i]])
				lcp[i]++;
			p=i;
		}
	}
	lcp[0]=s;
}

int main(){
	int n=read(),k=read(),off=0;
	REP(i,n){
		scanf("%s",strBuf+off);
		len[i]=strlen(strBuf+off);
		Zalgo(strBuf+off,len[i],zBuf+off);
		off+=len[i]+1;
	}
	dp[n][0]=true;
	for(int i=n-1;i>=0;i--)
		REP(j,k+1)
			dp[i][j]=dp[i+1][j]|(j<len[i]?false:dp[i+1][j-len[i]]);
	can[0]=true;
	int s=0,*lcp=lcpBuf+k,*z=zBuf;
	char *cur=curBuf+k,*str=strBuf;
	REP(i,n){
		REP(j,len[i])
			cur[j-len[i]]=str[j];
		Zalgo(cur-len[i],s+len[i],lcp-len[i]);
		int mn=-1;
		REP(j,s+1){
			if(!can[j]||j+len[i]>k||!dp[i+1][k-j-len[i]])
				continue;
			if(mn==-1){
				if(lcp[j]<len[i]){
					if(j+lcp[j]==s)
						mn=j;
					else if(cur[j+lcp[j]]>str[lcp[j]])
						mn=j;
				}
			}else{
				if(j-mn<len[i]&&lcp[mn]>=j-mn){
					int p=j-mn;
					if(p+z[p]==len[i])
						mn=j;
					else if(str[p+z[p]]>str[z[p]])
						mn=j;
				}
			}
		}
		if(mn>=0){
			bool w=true;
			REP(j,len[i]){
				w&=(cur[j+mn]==str[j]);
				can[j+mn+1]&=w;
				cur[j+mn]=str[j];
			}
			FOR(j,mn+len[i]+1,s+1)
				can[j]=false;
			s=mn+len[i];
			Zalgo(cur-len[i],s+len[i],lcp-len[i]);
		}
		for(int j=s;j>=0;j--)
			if(can[j]&&lcp[j]>=len[i])
				can[j+len[i]]=true;
		z+=len[i]+1;
		str+=len[i]+1;
	}
	printf("%s\n",cur);
}

