		can[i]=can[i+1]|(can[i+1]<<len[i+1]);
	}	
	for(int i=1;i<=k;i++)ans[0][i]=Max;
	for(int i=1;i<=k;i++)hash_ans[0][i]=hash_ans[0][i-1]*base+ans[0][i];
	start[0][1]=1;start[0][k+1]=1;
	for(int i=1;i<=n;i++){
		memcpy(ans[i],ans[i-1],sizeof ans[i]);
		memcpy(start[i],start[i-1],sizeof start[i-1]);
		for(int j=1;j<=k;j++){
			if(j+len[i]-1>k||!can[i][k-(j+len[i]-1)]||(!start[i-1][j]&&ans[i][j]!=Max))continue;
			if(j>1&&ans[i][j-1]==Max)break;
			int lcp=0;
			bool ok=true;
