	vector<vector<bool>> come(n + 1, vector<bool>(len + 1));
	go[n][len] = come[0][0] = 1;
	for(int i = n - 1; i >= 0; i--){
		go[i] = go[i + 1];
		for(int j = len; j >= s[i].size(); j--) if(go[i + 1][j]) go[i][j - s[i].size()] = 1;
