int n,a[N],b[N],pre[N],F[N],ans;
char s[N];

void init() {
	scanf("%d",&n);
	scanf("%s",s+1);
	for (int _=1;_<=n;_++) a[_] = s[_] - 'a' + 1;
	scanf("%s",s+1);
	for (int _=1;_<=n;_++) b[_] = s[_] - 'a' + 1;
	return ;
}

void solve() {
	for (int _=1;_<=n;_++) pre[_] = F[ a[_] ] , F[ a[_] ] = _;
	int cur = n , tmp = 0;
	for (int _=n;_>=1;_--) {
		while (F[b[_]] && (F[b[_]] > cur || F[b[_]] > _)) F[b[_]] = pre[ F[b[_]] ];
		if (!F[b[_]]) {ans = -1; break;}
		F[b[_]] < cur ? cur = F[b[_]] , tmp++ : 0;
		cur >= _ ? ans = max(ans , tmp) , tmp = 0 , cur = _-1: 0;
	}
	printf("%d\n",ans);
}

int main() {
	init();
	solve();
	return 0;
}

