inline void exkmp()
{
	ext[0]=tlen;
//	cout<<tlen<<endl;
	int k=0,p;
	while(k+1<tlen&& t[k+1]==t[k])++k;
	ext[1]=k;
	p=1;
	for(int i=2;i<tlen;++i){
		int len=ext[i-p];
		if(i+len<p+ext[p])ext[i]=len;
		else {
			int j=p+ext[p]-i;
			j=max(0,j);
			while(i+j<tlen && t[i+j]==t[j])++j;
			ext[i]=j;
			p=i;
		}
	}
