		tree[i] = tree[i << 1] | tree[i << 1 | 1];
	}
	state.set(0, 1);
	rep (i, 0, m - 1) {
		rep (j, 1, n) {
			if (state.test(sz[j])) state.set(sz[j + 1]);
		}
		rep (j, 1, n) {
			if (m - i - SZ(s[j]) < 0 || !can[j + 1][m - i - SZ(s[j])]) state.reset(sz[j]);
		}
		static char ch;
		ans += ch = query();
		(state &= tree[ch - 'a' + 32]) <<= 1;
	}
	cout << ans << endl;
