//前の文字列のうち,遷移可能なところで切って、文字列を置き換える
//その最小を求める
//O(s+K)で任意の0<=i<s.size()について、kとs[i]以降の何文字一致しているか を求めたい
//Z-algo
//suffix-Array from ei13333
//接尾辞配列。蟻本には O(Nlog2N)の実装が載っているが, 
//ここでは O(NlogN)の実装を扱う。
//SA-IS を使えば線形時間で構築できる。
struct SuffixArray{
	vector<int> SA;
	string s;
	void Build_SA(const string& str){
		s = str;
		SA.resize(s.size());
		iota(begin(SA), end(SA), 0);
		sort(begin(SA), end(SA), [&](const int& a, const int& b)
		{
			if(s[a] == s[b]) {return(a > b);}
			return (s[a] < s[b]);
		});
		vector< int > classes(s.size()), c(s.size()), cnt(s.size());
		for(int i = 0; i < s.size(); i++) {c[i] = s[i];}
		for(int len = 1; len < s.size(); len <<= 1) {
			for(int i = 0; i < s.size(); i++) {
				if(i > 0 && c[SA[i - 1]] == c[SA[i]] && SA[i - 1] + len < s.size() && c[SA[i - 1] + len / 2] == c[SA[i] + len / 2]) {
					classes[SA[i]] = classes[SA[i - 1]];
				} else {
					classes[SA[i]] = i;
				}
			}
			iota(begin(cnt), end(cnt), 0);
			copy(begin(SA), end(SA), begin(c));
			for(int i = 0; i < s.size(); i++) {
				int s1 = c[i] - len;
				if(s1 >= 0) SA[cnt[classes[s1]]++] = s1;
			}
			classes.swap(c);
		}
	}
	int operator[](int k) const{return (SA[k]);}
	int size() const{return (s.size());}
	bool lt_substr(string& t, int si = 0, int ti = 0)
	{
		int sn = s.size(), tn = t.size();
		while(si < sn && ti < tn) {
			if(s[si] < t[ti]) return (true);
			if(s[si] > t[ti]) return (false);
			++si, ++ti;
		}
		return (si >= sn && ti < tn);
	}
	int lower_bound(string& t)
	{
		int low = -1, high = SA.size();
		while(high - low > 1) {
			int mid = (low + high) >> 1;
			if(lt_substr(t, SA[mid])) low = mid;
			else high = mid;
		}
		return (high);
	}
	pair< int, int > lower_upper_bound(string& t)
	{
		int idx = lower_bound(t);
		int low = idx - 1, high = SA.size();
		t.back()++;
		while(high - low > 1) {
			int mid = (low + high) >> 1;
			if(lt_substr(t, SA[mid])) low = mid;
			else high = mid;
		}
		t.back()--;
		return (make_pair(idx, high));
	}
	void output()
	{
		for(int i = 0; i < size(); i++) {
			cout << i << ": " << s.substr(SA[i]) << endl;
		}
	}
};

vector<int>Zalgo(string S){
	vector<int>A(S.size());
	int c=0;
	for(int i = 1; i < S.size(); i++){
		if (i+A[i-c] < c+A[c]) {A[i] = A[i-c];}
		else {
			int j = max(0, c+A[c]-i);
			while(i+j<S.size()&&S[j]==S[i+j]){j++;}
			A[i]=j;c=i;
		}
	}
	A[0]=S.size();
	return A;
}
