const int MAXN = 2005;
const int MAXK = 10005;

int n, k;
string s[MAXN];
bool dp2[MAXN][MAXK];
bool opt[MAXN][MAXK]; // which prefix of opts[i] is optimal at this moment?
string opts[MAXN];
char buf[MAXK];

int main(){
	scanf("%d %d",&n,&k);
	for(int i=1; i<=n; i++){
		scanf("%s", buf);
		s[i] = buf;
	}
	dp2[n+1][k] = 1;
	for(int i=n; i; i--){
		memcpy(dp2[i], dp2[i+1], sizeof(dp2[i]));
		for(int j=0; j+s[i].size()<=k; j++){
			dp2[i][j] |= dp2[i+1][j+s[i].size()];
		}
	}
	opt[0][0] = 1;
	for(int i=1; i<=n; i++){
		vector<int> vect(k + 1);
		for(int j=0; j<=k; j++){
			int transitable = 0;
			if(dp2[i+1][j] && opt[i-1][j]) transitable |= 1;
			if(dp2[i+1][j] && j >= s[i].size() && opt[i-1][j - s[i].size()]) transitable |= 2;
			if(transitable == 3){
				if(opts[i-1].substr(j - s[i].size(), s[i].size()) <= s[i]) transitable = 1;
				else transitable = 2;
			}
			vect[j] = transitable;
		}
		int lst = 0;
		for(int j=0; j<=k; j++){
			if(vect[j] == 1){
				lst = j;
			}
		}
		string cnd1 = opts[i-1].substr(0, lst);
		string cnd2 ="";
		for(int j=k; j>=s[i].size(); j--){
			if(vect[j] == 2){
				string this_part = opts[i-1].substr(0, j - s[i].size()) + s[i];
				if(cnd2.empty() || cnd2.substr(0, this_part.size()) > this_part){
					cnd2 = this_part;
				}
			}
		}
		if(cnd1.size() > cnd2.size()) swap(cnd1, cnd2);
		opts[i] = min(cnd1, cnd2);
		if(cnd2.substr(0, cnd1.size()) == cnd1) opts[i] = cnd2;
		for(int j=0; j<=opts[i].size(); j++){
			if(vect[j] == 1){
				if(opts[i-1].substr(0, j) == opts[i].substr(0, j)) opt[i][j] = 1;
			}
			if(vect[j] == 2){
				if(opts[i-1].substr(0, j - s[i].size()) + s[i] == opts[i].substr(0, j)) opt[i][j] = 1;
			}
		}
	}
	puts(opts[n].c_str());
}

