//T[0~be]とT[0~j]+Sを比較
int cal(int i,int be,int j){
	if(be<=j) return 0;
	int ma=za[j+len[i]];ma=min(ma,min(be-j,len[i]));
	if(ma==min(be-j,len[i])) return 0;
	else if(s[i][ma]<t[i][j+ma]) return 1;
	return -1;
}

//T[0~be]+SとT[0~j]+Sを比較
int cal2(int i,int be,int j){
	if(be>j) return -cal2(i,j,be);
	if(be==j) return 0;
	int ma=za[len[i]+be];
	if(ma<j-be){
		if(s[ma]<t[ma]) return -1;return 1;
	}
	else{
		ma=za[j-be];
		if(ma>=len[i]-j+be) return 0;
		else if(t[ma]<t[ma+j-be]) return 1;return -1;
	}
}
