	rep(i,n){
		za=zalgo(s[i]+t[i]);
		int be=-1;
		rep(j,t[i].size()+1){
			if(j+len[i]>k || !dp[i+1][j+len[i]] || !d2[i][j]) continue;
			if(be<0){
				int x=cal(i,t[i].size(),j);
				if(x>0 || (x==0 && j+len[i]>t[i].size())) be=j;
			}
			else{
				int x=cal2(i,be,j);
				if(x>=0) be=j;
			}
		}
		rep(j,t[i].size()+1){
			if(!d2[i][j]) continue;
			if(dp[i+1][j]){
				if(be<0) d2[i+1][j]=true;
