			}
			else{
				if(cal2(i,be,j)>=0) d2[i+1][j+len[i]]=true;
			}
		}
		if(be<0) t[i+1]=t[i];
		else t[i+1]=t[i].substr(0,be)+s[i];
	}
	cout<<t[n]<<endl;
}

