			char c2 = j < next.size() ? next[j] : 0;
			diff |= c1 != c2 || !c1 || !c2;
		}
		assert(next.size() <= len);
		best = next;
	}
	assert(best.size() == len);
	cout << best << endl;

	return 0;
}

