using namespace std;

vector<int> Z(const string& str){
	int n = str.size();
	vector<int> ret(n);
	int L = 0, R = 0;
	for (int i = 1; i<n; i++){
		if (R<i){
			L = R = i;
			while (R<n&&str[R - L] == str[R]) R++;
			ret[i] = R - L; R--;
		}
		else{
			int k = i - L;
			if (ret[k] <= R - i + 1) ret[i] = ret[k];
			else{
				L = i;
				while (R<n&&str[R - L] == str[R]) R++;
				ret[i] = R - L; R--;
			}
		}
	}
	return ret;
}

const int NMAX = 2222;
const int KMAX = 11111;
bool ok[NMAX][KMAX];
string ans;
string in[NMAX];
bool dp[2][KMAX];

int main(){
	int N, K; cin >> N >> K;
	for (int i = 1; i <= N; i++) cin >> in[i];

	ok[N][K] = true;
	for (int i = N; i>1; i--) for (int j = 0; j <= K; j++) if (ok[i][j]){
		ok[i - 1][j] = true;
		if (j >= in[i].size()) ok[i - 1][j - in[i].size()] = true;
	}

	ans = "";
	dp[0][0] = true;
	for (int i = 1; i <= N; i++){
		for (int j = 0; j <= K; j++) dp[i % 2][j] = false;
		int S = in[i].size();
		int A = ans.size();
		vector<int> z = Z(in[i] + '$' + ans);
		vector<int> zi = Z(in[i] + '$' + in[i]);

		bool ext = false;
		int f = -1;
		for (int j = min(A, K - S); j >= 0; j--) if (dp[(i + 1) % 2][j]){
			if (!ext){
				if (!ok[i][j + S]) continue;
				if (j == A){
					ext = true;
					f = j;
					continue;
				}

				int t = z[S + 1 + j];
				if (t<S && j + t<A && ans[j + t]<in[i][t]) continue;
				ext = true;
				f = j;
			}
			else{
				if (!ok[i][j + S]) continue;
				if (j + S <= f){
					int t = z[S + 1 + j];
					if (t < S && in[i][t] < ans[j + t]) f = j;
				}
				else{
					int t = z[S + 1 + j];
					if (t < S && j + t < f && in[i][t] < ans[j + t]) f = j;
					else if (t >= f - j){
						int u = zi[S + 1 + f - j];
						if (u + f - j < S && in[i][u + f - j] < in[i][u]) f = j;
					}
				}
			}
		}

		if (!ext){
			int t = 0;
			for (int j = 0; j <= A; j++) if (dp[(i + 1) % 2][j] && ok[i][j])
				dp[i % 2][j] = true, t = j;
			ans = ans.substr(0, t);
		}
		else{
			string str = ans.substr(0, f) + in[i];
			int B = str.size();
			dp[i % 2][B] = true;
			for (int j = 0; j <= B; j++) if (dp[(i + 1) % 2][j]){
				if (j <= f && ok[i][j]) dp[i % 2][j] = true;
				if (j > f && j <= f + S && ok[i][j]){
					int t = z[S + 1 + f];
					if (t >= j - f) dp[i % 2][j] = true;
				}
				if (j + S <= f && ok[i][j + S]){
					int t = z[S + 1 + j];
					if (t == S) dp[i % 2][j + S] = true;
				}
				if (j + S > f && j < f && ok[i][j + S]){
					int t = z[S + 1 + j];
					if (t >= f - j){
						int u = zi[S = 1 + f - j];
						if (u + f == j + S) dp[i % 2][j + S] = true;
					}
				}
			}

			bool over = false;
			int overlen = -1;
			vector<int> zo = Z(str + '$' + ans);
			for (int j = B + 1; j <= A; j++) if (dp[(i + 1) % 2][j] && ok[i][j]){
				if (zo[B + 1 + B - S] == B){
					over = true;
					overlen = j;
					dp[i % 2][j] = true;
				}
			}

			if (over) ans = ans.substr(0, overlen);
			else ans = str;
		}
	}

	cout << ans;
}

