  for (int i = 0; i < n; ++i) {
    cin >> s[i];
  }
  vector<bitset<10001>> f(n + 1);
  f[n].set(k);
  vector<vector<pair<int, int>>> cand(2);
  for (int i = n - 1; i >= 0; --i) {
    int len = (int) s[i].size();
    f[i] = f[i + 1] | (f[i + 1] >> len);
