				else if (frm[rr] == 0)
				{
					int x = dat[s.size() + 1 + (j - s.size())];
					if (x < s.size())
					{
						if (s[x] < now[j - s.size() + x])rr = j, ks.clear(), ks.push_back(j);
					}
					else ks.push_back(j);
				}
				else
				{
					if (j <= rr - s.size())
					{
						int x = dat[s.size() + 1 + (j - s.size())];
						if (x < s.size())
						{
							if (s[x] < now[j - s.size() + x])rr = j, ks.clear(), ks.push_back(j);
						}
						else ks.push_back(j);
					}
					else
					{
						int x = dat[s.size() + 1 + (j - s.size())];
						if (x < rr - j)
						{
							if (s[x] < now[j - s.size() + x])rr = j, ks.clear(), ks.push_back(j);
						}
						else
						{
							int y = dat[rr - j];
							if (y < s.size() - (rr - j))
							{
								if (s[rr - j + y] < s[y])rr = j, ks.clear(), ks.push_back(j);
							}
							else ks.push_back(j);
						}
					}
				}
			}
		}
		//printf("--%d\n", rr);
		if (rr == -1)exit(0);
		for (int j = 0; j < ks.size(); j++)dp[i + 1][ks[j]] = true;
		string nn;
		if (frm[rr] == 0)
		{
			for (int i = 0; i < rr; i++)nn.push_back(now[i]);
			for (int i = rr; i < gen; i++)nn.push_back('z' + 1);
		}
		else
		{
			for (int i = 0; i < rr - s.size(); i++)nn.push_back(now[i]);
			for (int i = 0; i < s.size(); i++)nn.push_back(s[i]);
			for (int i = rr; i < gen; i++)nn.push_back('z' + 1);
		}
		now = nn;
	}
	cout << now << endl;
}

