void z_algo(int stp,string s1){
   z[1] = SZ(s1);
   int R = 0,mx = 0;
   fr(i,2,SZ(s1),1){
      z[i] = (i < R)?min(R-i,z[i-mx+1]):0;
      while(i+z[i] <= (int)SZ(s1) && s1[z[i]+1] == s1[z[i]+i])++z[i];
      if(i+z[i] > R)R = i+z[i],mx = i;
   }
   fr(i,stp+1,SZ(s1),1){
      exk[i-stp] = z[i];
   }
}

