static const auto NMAX = 2000;
static const auto MMAX = 10000;
static const auto LMAX = 1000000;

static int N, M;
static char B[LMAX + NMAX];
static char* S[NMAX];
static int L[NMAX];
static int R[NMAX];
static int O[NMAX];

static bool cmp(int a, int b) {
	static char A[LMAX + 1], B[LMAX + 1];
	sprintf(A, "%s%s", S[a], S[b]);
	sprintf(B, "%s%s", S[b], S[a]);
	return memcmp(A, B, L[a] + L[b]) < 0;
}

static void solve() {
	for(auto i = 0; i < N; i++) O[i] = i;
	std::stable_sort(O, O + N, cmp);
	for(auto i = 0; i < N; i++) R[O[i]] = i;

	static int DP[1 + NMAX][1 + MMAX];
	std::fill_n(DP[N], 1 + M, N);
	for(auto i = N - 1; i >= 0; i--) {
		for(auto j = 0; j <= M; j++) {
			DP[i][j] = DP[i + 1][j];
			if(j - L[i] >= 0 && R[i] < DP[i][j]) {
				if(j - L[i] == 0 || DP[i + 1][j - L[i]] != N) {
					DP[i][j] = R[i];
				}
			}
		}
	}

	auto i = 0, j = M;
	while(DP[i][j] != N) {
		auto k = O[DP[i][j]];
		fputs(S[k], stdout);
		j -= L[k];
		i = k + 1;
	}
	putchar('\n');
}

