        for(int j = 0; j <= a.size() && j + l <= K; j++)
            if(spl[j] && dp[i + 1][K - j - l])
            {
                int cmn = z[j + l];
                if(cmn >= l || j + cmn >= a.size())    continue;

                if(a[j + cmn] > s[i][cmn])
                {
                    if(pos > j + cmn)
                    {
                        pos = j + cmn;
                        st = j;
                        newch = s[i][cmn];
                    }
                    else if(pos == j + cmn && s[i][cmn] < newch)
                    {
                        st = j;
                        newch = s[i][cmn];
                    }
                    else if(pos == j + cmn && s[i][cmn] == newch)
                    {
                        int zz = z[j - st];
                        if(j - st + zz >= l || s[i][zz] < s[i][j - st + zz])
                            st = j;
                    }
                }
            }

        if(pos < a.size())
        {
            int newsz = st;
            for(int i = newsz + 1; i <= a.size(); i++)   spl[i] = 0;
            a.resize(newsz);
            a += s[i];
            spl[newsz + l] = 1;
        }
        else
        {
            for(int j = 0; j <= a.size() && j + l <= K; j++)
                if(spl[j] && dp[i + 1][K - j - l])
                {
                    int cmn = z[j + l];
                    if(j + cmn >= a.size())
                    {
                        if(st == -1)
                            st = j;
                        else
                        {
                            int zz = z[j - st];
                            if(j - st + zz >= l || s[i][zz] < s[i][j - st + zz])
                                st = j;
                        }
                    }
                }
            if(st != -1)
            {
                int newsz = st;
                a.resize(newsz);
                a += s[i];
                spl[newsz + l] = 1;
            }
        }

        zalgo(s[i] + a);
        for(int j = 0; j < a.size(); j++)
            if(spl[j] && z[j + l] >= l && dp[i + 1][K - j - l])
                spl[j + l] = 1;
    }

    printf("%s\n", a.c_str());
    return 0;
}

