typedef pair <int, int> ii;
ii mv[1000005];
int n, k, siz[N], dp[N][K], p[N], a[N], cnt;
string s[N], ans;

int main(){
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    cin >> n >> k;
    for (int i = 1; i <= n; i++) cin >> s[i], siz[i] = s[i].size();
    for (int i = 1; i <= n; i++) p[i] = i;
    sort(p+1, p+1+n, [](int x, int y){return ((s[x] < s[y]) || (s[x] == s[y] && x < y));});
    for (int i = 1; i <= n; i++) a[p[i]] = i;
    dp[n+1][0] = 1;
    for (int i = n; i >= 1; i--){
        for (int j = 0; j <= k; j++){
            dp[i][j] = dp[i+1][j];
            if (j >= siz[i]) dp[i][j] |= dp[i+1][j-siz[i]];
        }
    }
    for (int i = 1; i <= n; i++)
        if (k-siz[i] >= 0 && dp[i+1][k - siz[i]]) mv[++cnt] = ii(i, 0);

    for (int i = 1; i <= k; i++){
        char c = 'z'; int ncnt = 0;
        for (int j = 1; j <= cnt; j++){
            int str = mv[j].first, pos = mv[j].second;
            if (c > s[str][pos]) c = s[str][pos];
        }
        ans += c;
        int ck = n + 1;
        for (int j = 1; j <= cnt; j++){
            int str = mv[j].first, pos = mv[j].second;
            if (c != s[str][pos]) continue;
            if (pos == siz[str]-1) ck = min(ck, str+1);
            else mv[++ncnt] = ii (str, pos+1);
        }
        for (int j = ck; j <= n; j++) {
            if (k - i - siz[j] >= 0 && dp[j+1][k - i - siz[j]]) mv[++ncnt] = ii(j, 0);
        }
        cnt = ncnt;
        assert(cnt <= 2500);
    }
    cout << ans;
}

