using namespace std;

const int N=2e3+5,K=1e4+5,S=1e6+5,C=26;

#define bs bitset<S> 

int n,k,len[N],st[N];
bitset<K> f[N];
char s[N][K];

bs tr[C<<2],pos[C];

#define lk k<<1
#define rk k<<1|1
#define mid (l+r>>1)

inline void mdy(int pos,int val,int k=1,int l=0,int r=C-1){
  tr[k][val]=1;
  if(l==r)return;
  if(pos<=mid)mdy(pos,val,lk,l,mid);
  else mdy(pos,val,rk,mid+1,r);
}

bs state;

inline int qry(int k=1,int l=0,int r=C-1){
  if(l==r)return l;
  if((state&tr[lk]).none())return qry(rk,mid+1,r);
  return qry(lk,l,mid);
}

int main(){
  scanf("%d%d",&n,&k);
  for(int i=1;i<=n;i++)scanf("%s",s[i]+1),len[i]=strlen(s[i]+1);
  f[n+1][0]=1;
  for(int i=n;i;i--)for(int j=k;~j;j--)f[i][j]=f[i+1][j]|(j>=len[i]?f[i+1][j-len[i]]:0);
  for(int t=0,i=1;i<=n;i++){
    st[i]=t+1;
    for(int j=1;j<=len[i];j++){
      t++;
      mdy(s[i][j]-'a',t);
      pos[s[i][j]-'a'][t]=1;
    }
  }

  state[1]=1;
  st[n+1]=k+1;

  for(int i=1;i<=k;i++){
    for(int j=1;j<n;j++)if(state[st[j]])state[st[j+1]]=1;
    for(int j=1;j<=n;j++)if(k-i+1<len[j]||!f[j+1][k-i+1-len[j]])state[st[j]]=0;
    int x=qry();
    putchar(x+'a');
    (state&=pos[x])<<=1;
  }

  return 0;
}

