using namespace std;

using ll = long long;
using ii = pair<ll, ll>;
using si = pair<string, ll>;

const int MAX { 2010 };
const int MAXK { 10010 };

si ts[MAX];
string xs[MAX];

int st[MAX][MAXK], next_st[MAX][MAXK];

int dp(int idx, int size, int N, int K)
{
//cout << "--> dp(" << idx << ", " << size << ")" << endl;
    if (size < 0)
        return 0;

    if (size == 0)
        return 1;

    if (idx == N)
        return 0;

    if (st[idx][size] != -1)
        return st[idx][size];

//cout << "### dp(" << idx << ", " << size << "). Picking... ";
    int res = dp(idx + 1, size - xs[idx].size(), N, K);
//cout << "res = " << res << endl;

    if (res == 1)
        next_st[idx][size] = 1;
    else
    {
        res = dp(idx + 1, size, N, K);
        next_st[idx][size] = 0;
    }

    st[idx][size] = res;
    return res; 
}

int main()
{
    ios::sync_with_stdio(false);

    int N, K;
    cin >> N >> K;

    for (int n = 0; n < N; ++n)
    {
        cin >> xs[n];
        ts[n].first = xs[n];
        ts[n].second = n;
    }

    sort(ts, ts + N);

    string best = "";

    for (int k = 0; k < K; ++k)
        best += 'z';

    memset(st, -1, sizeof st);
    memset(next_st, -1, sizeof next_st);

    for (int n = 0; n < N and ts[n].first < best; ++n)
    {
//        memset(st, -1, sizeof st);
//        memset(next_st, -1, sizeof next_st);

//cout << "trying base = " << ts[n].first << "\n";
//cout << "N = " << N << ", K = " << K << ", idx = " << ts[n].second << ", size = " << K - ts[n].first.size() << endl;
        int res = dp(ts[n].second + 1, K - ts[n].first.size(), N, K);

        if (res == 0)
            continue;

        string ans = ts[n].first;
        int idx = ts[n].second + 1, size = K - ts[n].first.size(), pick;

        while ((pick = next_st[idx][size]) != -1)
        {
            if (pick)
            {
                ans += xs[idx];
                size -= xs[idx].size();
            }

            ++idx;
        }

        best = min(best, ans);
 //       cout << "ans = " << ans << endl;
    }

    cout << best << endl;

    return 0;
}

