      for(int j = 0;j <= siz; ++j){
         if(j+(int)str[i].size() > m)continue ;
         if(!cut[j] || !dp[i+1][m-j-str[i].size()])continue ;
         int lcp = z[str[i].size()+2+j];
         if(lcp == str[i].size()){
            cut[j+str[i].size()] = 1;
            continue ;
         }
         if(str[i][lcp-1] > minch[lcp])continue ;
         minch = minch.substr(0,j+1)+str[i]; flag = true; break;
      }
      if(!flag && siz+(int)str[i].size() <= m && dp[i+1][m-siz-str[i].size()] == 1)
         cut[siz] = 1,minch += str[i];
      siz = minch.size()-1;
   }
   cout << minch.substr(1) << endl;
   return 0;
}

