			int v = j - s[i].size(), siz = f[t0][v].size();
			int len = s[i].size(), Lsiz = 0, Lhash = 0;
			tmp = f[t0][v]; res = f[t0][j];
			f[t][j] = f[t0][j];
			if(f[t0][v].size() == 0 && v != 0) continue;
			//cerr << "[ok] || i = " << i << ", v = " << v << endl;
			if(tmp.size() > 0) Lsiz = tmp[siz - 1].s, Lhash = tmp[siz - 1].hash;
			tmp.push_back(Node(i, Lsiz + len, Lhash + Hash[i][len] * fac[Lsiz]));
			//cerr << "ok!" << endl;
			f[t][j] = checkit(tmp, res);
