		for(int j=0;j<=k;j++)
			dp[i][j] = dp[i+1][j];
		for(int j=(int)s[i].size();j<=k;j++)
			dp[i][j] |= dp[i+1][j-(int)s[i].size()];
	}

	string tem = "";

	m = 32;
	for(int i=1;i<=n;i++) {
		st[i] = (int)tem.size();
		state[st[i]] = true;
		for(char c : s[i]) {
			seg[c - 'a' + m][(int)tem.size()] = true;
			tem += c;
		}
	}
	for(int i=m-1;i;i--)
		seg[i] = seg[i<<1] | seg[i<<1|1];

	string ans = "";
	for(int i=1;i<=k;i++) {
		for(int j=1;j<=n;j++)
			if(i + (int)s[j].size() - 1 > k || !dp[j+1][k - (i + (int)s[j].size() - 1)])
