int z[10005];
void do_z(string s){
    ///z[i] = prefixul maxim care coincide cu [i, i + z[i] - 1]

    int L = s.size();
    z[0] = L;
    for(int i = 1, last = 1, right = 1; i < L ; ++i){
        z[i] = 0;
        if(i <= right) z[i] = min(right - i + 1, z[i - last]);

        while(s[z[i]] == s[i + z[i]]) ++z[i];
        if(i + z[i] - 1 > right) right = i + z[i] - 1, last = i;
    }
}

