int main() {
    scanf("%d%d",&n,&k);
    for (int i=1;i<=n;i++) scanf("%s",s[i]),len[i]=strlen(s[i]);
    dp[n+1][0]=1;
    for (int i=n;i>=1;i--) 
        dp[i]=dp[i+1]|(dp[i+1]<<len[i]);
    int cnt=0;
    for (int i=1;i<=n;i++) 
        if (dp[i+1][k-len[i]]) vis[0][++cnt]=make_pair(i,0);

    int ii=0;
    for (int i=0;i<k;i++) {
        char minc='z';
        for (int j=1;j<=cnt;j++) minc=min(minc,s[vis[ii][j].first][vis[ii][j].second]);
        ans[i]=minc;

        int minid=n+1,ncnt=0;
        for (int j=1;j<=cnt;j++) {
            int nid=vis[ii][j].first,nlen=vis[ii][j].second;
            if (s[nid][nlen]!=minc) continue;
            if (nlen+1==len[nid]) minid=min(minid,nid);
            else vis[ii^1][++ncnt]=make_pair(nid,nlen+1);
        }
        for (int j=minid+1;j<=n;j++) {
