bool smaller(const vector<int>& a, const vector<int>& b) {
  int offset_a = 0, offset_b = 0;
  for (int i = 0, j = 0; i < a.size() && j < b.size(); ) {
    auto u = a[i], v = b[j];
    for (; offset_a < len[u] && offset_b < len[v]; ++offset_a, ++offset_b) {
      if (s[u][offset_a] < s[v][offset_b]) {
        return true;
      } else if (s[u][offset_a] > s[v][offset_b]) {
        return false;
      }
    }
    if (offset_a == len[u]) {
      ++i;
      offset_a = 0;
    }
    if (offset_b == len[v]) {
      ++j;
      offset_b = 0;
    }
  }
  return false;
}

int main() {
  int n, k;
