  for (int i = 0; i < n; ++i) {
    scanf("%s", s[i]);
    len[i] = strlen(s[i]);
  }
  int m = 0;
  for (int i = 0; i < n; ++i) {
    m = min(m + len[i], k);
    for (int j = m; j >= len[i]; --j) {
      if (j - len[i] > 0 && dp[j - len[i]].empty()) continue;
      auto cur = dp[j - len[i]];
      cur.push_back(i);
      if (dp[j].empty() || smaller(cur, dp[j])) {
        dp[j] = move(cur);
      }
    }
