  REP(i,n)sp[i]=mp(s[i], i);
  sort(ALL(sp));
  vector<int> ind(n+1);
  vector<int> len(n);
  REP(i,n)ind[sp[i].second] = i;
  REP(i,n)len[i] = s[i].size();  
  ind[n] = -100;

  // VECCOUT(ind);VECCOUT(len);

  // 復元していくのを無視して計算してみる
  // 逆順でDP dp[i][j]:i番目を先頭にしてj文字を取れるか
  // 先頭にする→それ以降しか取れない
  // boolでDPするのではなく、可能な中で辞書順最小になる先のindexを持つ

  // 

  vector<vector<pair<int,int>>> dp(n+1, vector<pair<int,int>>(k+1, mp(INF,INF)));  
  dp[n][0] = mp(n,-10000);
  REPR(i,n-1){
    REP(j,k+1){

      // 次に選択した物のindexを持つようにする

      if(dp[i+1][j] != mp(INF,INF))
        dp[i][j] = min(dp[i][j], dp[i+1][j]);
      if(j >= len[i] && dp[i+1][j-len[i]] != mp(INF,INF))
        dp[i][j] = min(dp[i][j], mp(ind[dp[i+1][j-len[i]].first], ind[i]));

      // dp[i][j] = max({dp[i][j], dp[i+1][j], j < len[i] ? -1 : dp[i+1][j-len[i]]});
    }
  }
  /*
  REP(i,n+1){
    REP(j,k+1)
      SCOUT(dp[i][j].first);
    ENDL;
  }
  */

  // VECCOUT(ind);

  // 辞書順で0番目になるようなindex

  // vector<vector<P>> でDPをする
  // dp[i][j]: i番目以降を使ってj文字取った時の{前の値の辞書順index, 実際に使った値}

  function<list<int>(int,int)> f = [&](int pos, int num){

    list<int> vec;
    vec.pb(sp[dp[pos][num].second].second);

    if(dp[pos][num].first == -100)return vec;
    if(dp[pos][num].first == -10000)return list<int>(0);

    vec.splice(vec.begin(), move(f(ind[dp[pos][num].first], num - len[sp[dp[pos][num].second].second])));
    return move(vec);
  };

  int min_ind = 0;
  int min_val = MOD;
  REP(i,n)
    if(dp[i][k] != mp(INF,INF) && ind[sp[dp[i][k].second].second] < min_val){
      min_ind = i;
      min_val = ind[sp[dp[i][k].second].second];
    }

  int indd = min_ind;

  list<int> hoge = f(indd, k);
  // VECCOUT(hoge);
  for(auto it = prev(hoge.end());;--it){
    cout << s[*it];
    if(it==hoge.begin())break;
  }
  ENDL;

  return 0;
}

