#include<bits/stdc++.h>
#define maxn 2005
#define maxl 10005
#define p 75679
#define q 937527359ll
#define Val(x) ((((long long)x) % q + q) % q)
using namespace std;
int n,k;
string s[maxn];
int len[maxn];
vector<int> h[maxn];
int fac[maxn];
inline int get_hash(int idx,int l,int r) {
	if(l==0)
		return h[idx][r];
	return Val(h[idx][r] - (long long)h[idx][l-1]*fac[r-l+1]);
}
struct state {
	int len,hash,idx;
};
struct node {
	node *lch,*rch;
	state data;
	state Merge(state lch,state rch) {
		if(rch.len == -1)	return lch;
		return state{lch.len+rch.len,Val(lch.hash*fac[rch.len]+rch.hash),-1};
	}
	void modify(int l,int r,int pos,node* pre,state now) {
		if(l==r) {
			this->data = now;
		}
		else {
			int mid = (l+r)>>1;
			if(pos <= mid) {
				this->lch = new node();
				this->rch = (pre != nullptr ? pre->rch : nullptr);
				this->lch->modify(l,mid,pos,(pre != nullptr ? pre->lch : nullptr),now);
			}
			else {
				this->lch = (pre != nullptr ? pre->lch : nullptr);
				this->rch = new node();
				this->rch->modify(mid+1,r,pos,(pre != nullptr ? pre->rch : nullptr),now);
			}
			this->data = Merge(this->lch->data,this->rch==nullptr ? state{-1,-1,-1} : this->rch->data);
		}
	}
	int find_ql(int l,int r,int need) {
		if(l==r)
			return l;
		else {
			int mid = (l+r)>>1;
			if(this->rch == nullptr || this->rch->data.len < need)
				return this->lch->find_ql(l,mid,need-(this->rch != nullptr ? this->rch->data.len : 0));
			else
				return this->rch->find_ql(mid+1,r,need);
		}
	}
	int cal(int l,int r,int num) {
		if(l==r) {
			return get_hash(this->data.idx,0,num-1);
		}
		else {
			int mid = (l+r)>>1;
			if(this->rch==nullptr || this->lch->data.len >= num)
				return this->lch->cal(l,mid,num);
			else
				return Val(this->lch->cal(l,mid,num)*fac[num-this->lch->data.len]+this->rch->cal(mid+1,r,num-this->lch->data.len));
		}
	}
	int get(int l,int r,int num) {
		if(l==r) {
			return s[this->data.idx][num-1];
		}
		else {
			int mid = (l+r)>>1;
			if(this->rch==nullptr || this->lch->data.len >= num)
				return this->lch->get(l,mid,num);
			else
				return this->rch->get(mid+1,r,num-this->lch->data.len);
		}
	}
	int cmp(int l,int r,int ql,int qr,int idx,int &st) {
		int mid = (l+r)>>1;
		if(l==r) {
			int sz = len[idx] - st;
			int a = this->data.idx;
			int l = 0 , r = sz - 1 , m;
			while(true) {
				if(r - l < 3) {
					for(m=l;m<=r && get_hash(a,0,m) == get_hash(idx,st,st+m);m++);
					m--;
					break;
				}
				m = (l+r)>>1;
				if(get_hash(a,0,m) == get_hash(idx,st,st+m))
					l = m;
				else
					r = m - 1;
			}
			if(m == sz-1)
				return 0;
			else {
				if(s[idx][st+m+1] < s[a][m+1])
					return 1;
				else
					return -1;
			}
		}
		else if(l==ql && r==qr) {
			if(this->lch->data.hash != get_hash(idx,st,st+this->lch->data.len-1))
				return this->lch->cmp(l,mid,ql,mid,idx,st);
			else {
				st += this->lch->data.len;
				return this->rch->cmp(mid+1,r,mid+1,qr,idx,st);
			}
		}
		else {
			if(qr<=mid)
				return this->lch->cmp(l,mid,ql,qr,idx,st);
			else if(ql>mid)
				return this->rch->cmp(mid+1,r,ql,qr,idx,st);
			else {
				int l_result = this->lch->cmp(l,mid,ql,mid,idx,st);
				if(l_result == 1)	return 1;
				if(l_result == 0 && st < len[idx])
					return this->rch->cmp(mid+1,r,mid+1,qr,idx,st);
				return -1;
			}
		}
	}
	void dfs(int l,int r) {
		if(l==r)
			cout << s[this->data.idx];
		else {
			int mid = (l+r)>>1;
			if(this->lch!=nullptr)	this->lch->dfs(l,mid);
			if(this->rch!=nullptr)	this->rch->dfs(mid+1,r);
		}
	}
};
int cmp_prefix(node *a,node *b,int len) {
	int l = 0 , r = len - 1 , m;
	while(true) {
		if(r-l<3) {
			for(m=l;m<=r && a->cal(1,n,m)==b->cal(1,n,m);m++);
			m--;
			break;
		}
		m = (l+r)>>1;
		if(a->cal(1,n,m) == b->cal(1,n,m))
			l = m;
		else
			r = m - 1;
	}
	if(m == len-1)
		return 0;
	if(a->get(1,n,m+1) < b->get(1,n,m+1))
		return 1;
	else
		return -1;
}
