					dp[i][j]->modify(1,n,SZ[i-1][j-len[i]]+1,dp[i-1][j-len[i]],state{len[i],h[i][len[i]-1],i});
					SZ[i][j] = SZ[i-1][j-len[i]] + 1;
					tag[i][j] = i;
				}
			}
	} 
	dp[n][k]->dfs(1,n);
	cout << '\n';
	return 0;
}

