	node(int a, int b) { x = a, y = b; }
} b[M];
inline void exkmp(char s[], int n) {
	int k = 1; f[1] = m;
	rep(i, 2, n) {
		f[i] = max(0, min(k+f[k]-i, f[i-k+1]));
		while(i+f[i] <= n && s[f[i]+i] == s[f[i]+1]) f[i]++;
		if(f[i]+i > f[k]+k) k = i;
	}
	//rep(i, 1, n) printf("%d ", f[i]); puts("");
}/*
