			int lcp=0;
			bool ok=true;
			while(ans[i][j+lcp]==s[i][1+lcp])lcp++;
			int nxt=j+lcp;
			if(lcp==len[i]){
				start[i][nxt]=1;
				continue;
			}
			if(ans[i][nxt]>s[i][lcp+1]){
				for(int _=j;_<j+len[i];_++){
					start[i][_]=0;
					ans[i][_]=s[i][_-j+1];
				}
				for(int _=j+len[i];_<=k;_++)ans[i][_]=Max,start[i][j]=0;
				start[i][j]=1;
				break;
			}
		}
		for(int j=1;j<=k;j++)hash_ans[i][j]=hash_ans[i][j-1]*base+ans[i][j];
	}
	for(int i=1;i<=k;i++)putchar(ans[n][i]);putchar('\n');
	return 0;
}

