int cmp(node n1,node n2)//< -1 = 0 > 1
{
	if(!n1.y&&!n2.y)return 0;
	if(!n1.y)return -cmp(n2,n1);
	if(!n2.y)
	{
		if(n1.x<=n2.x)return 0;int L=P[n2.x+1+len[n1.y]];
