inline int cmp(int a,int b){
	int left=a-1;
	int right=a+s[b].size();
	while(left+1<right){
		int M=(left+right)/2;
		if(eq(a,M+1,b)){
			left=M;
		}else right=M;
	}
	//printf("%d\n",right);
	if(right==a+s[b].size())return 0;
	if(s[b][right-a]<st[b][right])return 1;
	return -1;
}
