int N,K,len[2005],e[10005];
bool ed[2005][10005],c[2005][10005];
struct node {
	char s[10005];
	int hsh[10005],len;
	void calc() {
		for(int i = 1 ; i <= len ; ++i) {
			hsh[i] = (1LL * e[i] * (s[i] - 'a' + 1) + hsh[i - 1]) % MOD;
		}
	}
	int getrange(int l,int r) {
		return 1LL * (hsh[r] + MOD - hsh[l]) * e[K - l] % MOD;
	}
}a[2005],dp[2005];
bool check(node &s,int l1,int r1,node &t,int l2,int r2) {
	return s.getrange(l1,r1) == t.getrange(l2,r2);
}
int getlen(node &s,int l1,node &t,int l2) {
	int l = 0,r = min(s.len - l1 + 1,t.len - l2 + 1);
	while(l < r) {
		int m = (l + r + 1) >> 1;
		if(check(s,l1,l1 + m - 1,t,l2,l2 + m - 1)) l = m;
		else r = m - 1;
	}
	return l;
}
int main() {
#ifdef ivorysi
