#endif
	read(N);read(K);
	e[0] = 1;
	for(int i = 1 ; i <= K ; ++i) {
		e[i] = 1LL * e[i - 1] * ba % MOD;
	}
	for(int i = 1 ; i <= N ; ++i) {
		scanf("%s",a[i].s + 1);
		a[i].len = strlen(a[i].s + 1);
		a[i].calc();
	}
	c[N + 1][K] = 1;
	for(int i = N ; i >= 1 ; --i) {
		c[i][K] = 1;
		for(int j = K ; j >= 0 ; --j) {
			if(j >= a[i].len) c[i][j - a[i].len] |= c[i + 1][j];
			c[i][j] |= c[i + 1][j];
		}
	}
	ed[0][0] = 1;
	for(int i = 1 ; i <= N ; ++i) {
		int s = -1;
		int app = -1;
		for(int j = K ; j >= 0 ; --j) {
			if(ed[i - 1][j] && j + a[i].len <= K && c[i + 1][j + a[i].len]) {
				int l = getlen(a[i],1,dp[i - 1],j + 1);
				if(l == a[i].len) continue;
				if(j + l < dp[i - 1].len) {
					if(dp[i - 1].s[j + l + 1] > a[i].s[l + 1]) app = j;
				}
				else if(s != -1){
					int t = getlen(a[i],l + 1,a[i],s);
					if(a[i].s[s + t] > a[i].s[l + 1 + t]) {app = j;s = l + 1;}
				}
				else {
					s = l + 1;app = j;
				}
			}
		}
		if(app != -1) {
			for(int j = 0 ; j <= app ; ++j) {
				dp[i].s[j] = dp[i - 1].s[j];
				if(ed[i - 1][j] && c[i + 1][j]) ed[i][j] = 1;
			}
			dp[i].len = app + a[i].len;
			for(int j = app + 1 ; j <= app + a[i].len ; ++j) dp[i].s[j] = a[i].s[j - app];
			dp[i].calc();
			for(int j = 0 ; j <= app ; ++j) {
				if(ed[i - 1][j]) {
					int l = getlen(a[i],1,dp[i],j + 1);
					if(l == a[i].len) ed[i][j + a[i].len] = 1;
				}
			}
		}
		else {
			for(int j = 0 ; j <= dp[i - 1].len ; ++j) {
				dp[i].s[j] = dp[i - 1].s[j];
				if(ed[i - 1][j] && c[i + 1][j]) ed[i][j] = 1;
			}
			dp[i].len = dp[i - 1].len;
			while(!ed[i][dp[i].len]) --dp[i].len;
			dp[i].calc();
		}
	}
	for(int i = 1 ; i <= dp[N].len ; ++i) {
		putchar(dp[N].s[i]);
	}
	enter;
	return 0;
}

