int main () {
        int n, k; cin >> n >> k;
        for (int i = 1; i <= n; ++i) cin >> s[i], len[i] = s[i].size();
        can[n+1][0] = 1;
        for (int i = n; i >= 1; --i) can[i] = can[i+1] | (can[i+1]<<len[i]);
        for (int i = 1; i <= n; ++i) if (can[i+1][k-len[i]]) rec[0][++cnt] = mp (i, 0);
        int cur = 0, nxt = cur ^ 1;
        for (int i = 0; i < k; ++i) {
                char Min = 'z';
                for (int j = 1; j <= cnt; ++j) Min = min (Min, s[rec[cur][j].fi][rec[cur][j].se]);
                ans[i] = Min;
                int minID = 1e9, ccnt = 0;
                for (int j = 1; j <= 0; ++j) {
                        int id = rec[cur][j].fi, pos = rec[cur][j].se;
                        if (s[id][pos] != Min) continue;
                        if (pos+1 == len[id]) minID = min(minID,id);
                        else rec[nxt][++ccnt] = mp (id,pos+1);
                }
                for (int j = minID+1; j <= 0; ++j)
                        if (k-len[j]-i-1>=0 && can[j+1][k-len[j]-i-1])
                                rec[nxt][++ccnt] = mp (j,0);    
                cur ^= 1, nxt ^= 1;
                cnt = ccnt;
        }
        for (int i = 0; i < k; ++i) putchar (ans[i]); cout << endl;
