bool cmp(data p,data q,int i){//p>q
    if (!p.y&&!q.y) return false;
    if (p.x>q.x){
        if (!q.y) return false;
        if (!p.y) return cmps(q.x+l[i],min(p.x-q.x,l[i]))>0;
        int t=cmps(q.x+l[i],min(p.x-q.x,l[i]));
        return t>0||t==0&&cmps(p.x-q.x,l[i]-(p.x-q.x))<0;
    }
    else{
        if (!p.y) return false;
        if (!q.y) return cmps(p.x+l[i],min(q.x-p.x,l[i]))<0;
        int t=cmps(p.x+l[i],min(q.x-p.x,l[i]));
        return t<0||t==0&&cmps(q.x-p.x,l[i]-(q.x-p.x))>0;
    }
}
