int main() {
    ios::sync_with_stdio(false);
    cin>>n>>k;
    for (re int i=1;i<=n;++i) cin>>s[i],l[i]=s[i].length();
    dp[1][l[1]]=s[1],v[1][l[1]]=1;
    for (re int i=1;i<n;++i) {
        int now=i&1,nxt=now^1;
        for (re int j=1;j<=k;++j) dp[nxt][j]="",v[nxt][j]=0;
        dp[nxt][l[i+1]]=s[i+1],v[nxt][l[i+1]]=1;
        for (re int j=1;j<=k;++j) {
            if (!v[now][j]) continue;
            if (!v[nxt][j]||dp[now][j]<dp[nxt][j])
                dp[nxt][j]=dp[now][j],v[nxt][j]=1;
            if (j+l[i+1]<=k) {
                if (!v[nxt][j+l[i+1]]||dp[now][j]+s[i+1]<dp[nxt][j+l[i+1]])
                    dp[nxt][j+l[i+1]]=dp[now][j]+s[i+1],v[nxt][j+l[i+1]]=1;
            }
        }
    }
    cout<<dp[n&1][k]<<endl;
    return 0;
}

