inline int cmp(vi&A, vi&B)
{
    forn(i, min(A.size(), B.size()))
        if(A[i]<B[i]&&to[A[i]].size()>=to[B[i]].size()) return 0;
        else if(A[i]>B[i]) return 1;
    return A.size()>B.size();
}

inline void Umin(int i, const int j)
{
    if(!i) return;
    if(!dp[i].size()||cmp(dp[i], dp[j])) dp[i]=dp[j], sz[i]=i;
}

