template <typename T> struct rolling_hash {
    static uint64_t add(uint64_t a, uint64_t b) { return a + b >= T::M ? a + b - T::M : a + b; }
    static uint64_t sub(uint64_t a, uint64_t b) { return T::add(a, T::M - b); }
    static uint64_t mul(uint64_t, uint64_t);
    static uint64_t X;
    static vector<uint64_t> mpow;
    static void resize(int n) {
        T::mpow.reserve(n + 1);
        while(T::mpow.size() <= n) {
            T::mpow.push_back(T::mpow.empty() ? 1 : T::mul(T::mpow.back(), T::X));
        }
    }
    vector<uint64_t> prefix;
    rolling_hash() {}
    rolling_hash(const string& s) { append(s); }
    uint64_t query(int L, int R) {
        assert(L <= R), assert(R <= prefix.size());
        resize(R - L);
        return L ? T::sub(prefix[R - 1], T::mul(prefix[L - 1], T::mpow[R - L])) : prefix[R - 1];
    }
    T& append(char c) {
        prefix.push_back(prefix.empty() ? c : T::add(T::mul(prefix.back(), T::X), c));
        return (T&)*this;
    }
    T& append(const string& s) {
        prefix.reserve(prefix.size() + s.size());
        for(const char& c : s) {
            push_back(c);
        }
        return (T&)*this;
    }
    T& operator+=(char c) { return append(c); }
    T& operator+=(const string& s) { return append(s); }
    void push_back(char c) { append(c); }
    void pop_back() { prefix.pop_back(); }
};
template <typename T> uint64_t rolling_hash<T>::X = uniform_int_distribution<uint64_t>(256, T::M - 1)(rng);
template <typename T> vector<uint64_t> rolling_hash<T>::mpow;
struct hash1 : public rolling_hash<hash1> {
    static const uint64_t M = (1ull << 61) - 1;
    static uint64_t mul(uint64_t a, uint64_t b) {
        uint64_t l1 = (uint32_t)a, h1 = a >> 32, l2 = (uint32_t)b, h2 = b >> 32;
        uint64_t l = l1 * l2, m = l1 * h2 + l2 * h1, h = h1 * h2;
        uint64_t ret = (l & M) + (l >> 61) + (h << 3) + (m >> 29) + (m << 35 >> 3) + 1;
        ret = (ret & M) + (ret >> 61);
        ret = (ret & M) + (ret >> 61);
        return ret - 1;
    }
    hash1() {}
    hash1(const string& s) : rolling_hash<hash1>(s) {}
};
struct hash2 : public rolling_hash<hash2> {
    static const uint64_t M = (1ull << 31) - 1;
    static uint64_t mul(uint64_t a, uint64_t b) {
        uint64_t ret = a * b + 1;
        ret = (ret & M) + (ret >> 31);
        ret = (ret & M) + (ret >> 31);
        return ret - 1;
    }
    hash2() {}
    hash2(const string& s) : rolling_hash<hash2>(s) {}
};
template <typename T> T bsearch(T L, T R, const function<bool(T)>& can, bool left_feasible = true) {
    T& feasible = left_feasible ? L : R;
    T& infeasible = left_feasible ? R : L;
    while(R - L > 1) {
        T M = L + (R - L) / 2;
        (can(M) ? feasible : infeasible) = M;
    }
    return feasible;
}
const int PREFIX = 0, SUFFIX = 1, LEX_SMALLER = 2, LEX_LARGER = 3;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    vector<string> s(n);
    cin >> s;
    vector<vector<bool>> can(n + 1, vector<bool>(k + 1));
    for(int i = n; i >= 0; i--) {
        for(int j = 0; j <= k; j++) {
            if(i == n) {
                can[i][j] = j == 0;
            } else {
                can[i][j] = can[i + 1][j] or (s[i].size() <= j and can[i + 1][j - s[i].size()]);
            }
        }
    }
    vector<hash1> h1;
    vector<hash2> h2;
    for(auto& ss : s) {
        h1.push_back(hash1(ss));
        h2.push_back(hash2(ss));
    }
    string ans = "";
    hash1 h1_ans;
    hash2 h2_ans;
    auto check = [&](int pos, int i) {
        if(pos == ans.size()) {
            return LEX_SMALLER;
        } else {
            int lcp_sz = bsearch<int>(0, min(s[i].size(), ans.size() - pos) + 1, [&](int k) {
                return h1[i].query(0, k) == h1_ans.query(pos, pos + k)
                    and h2[i].query(0, k) == h2_ans.query(pos, pos + k);
            });
            if(pos + lcp_sz == ans.size()) {
                return SUFFIX;
            } else if(lcp_sz == s[i].size()) {
                return PREFIX;
            } else {
                return s[i][lcp_sz] < ans[pos + lcp_sz] ? LEX_SMALLER : LEX_LARGER;
            }
        }
    };
    vector<int> insertable = {0};
    for(int i = 0; i < n; i++) {
        vector<int> new_insertable;
        for(int j : insertable) {
            new_insertable.push_back(j);
            if(j + s[i].size() <= k and can[i + 1][k - (j + s[i].size())]) {
                int res = check(j, i);
                if(res == LEX_SMALLER) {
                    while(ans.size() > j) {
                        ans.pop_back();
                        h1_ans.pop_back();
                        h2_ans.pop_back();
                    }
                    ans += s[i];
                    h1_ans += s[i];
                    h2_ans += s[i];
                    new_insertable.push_back(j + s[i].size());
                    break;
                } else if(res == SUFFIX) {
                    for(int pos = ans.size() - j; pos < s[i].size(); pos++) {
                        ans += s[i][pos];
                        h1_ans += s[i][pos];
                        h2_ans += s[i][pos];
                    }
                    new_insertable.push_back(j + s[i].size());
                } else if(res == PREFIX) {
                    new_insertable.push_back(j + s[i].size());
                }
            }
        }
        insertable = new_insertable;
    }
    cout << ans << endl;
    return 0;
}

