const int MAXN = 2005;
const int MAXK = 10005;

int n, k;
string s[MAXN];
bool dp1[MAXN][MAXK];
bool dp2[MAXN][MAXK];
bool opt[MAXN][MAXK]; // which prefix of opts[i] is optimal at this moment?
string opts[MAXN];
char buf[1000005];

int main(){
	scanf("%d %d",&n,&k);
	for(int i=1; i<=n; i++){
		scanf("%s", buf);
		s[i] = buf;
	}
	dp1[0][0] = 1;
	for(int i=1; i<=n; i++){
		memcpy(dp1[i], dp1[i-1], sizeof(dp1[i]));
		for(int j=s[i].size(); j<=k; j++){
			dp1[i][j] |= dp1[i-1][j-s[i].size()];
		}
	}
	dp2[n+1][k] = 1;
	for(int i=n; i; i--){
		memcpy(dp2[i], dp2[i+1], sizeof(dp2[i]));
		for(int j=0; j+s[i].size()<=k; j++){
			dp2[i][j] |= dp2[i+1][j+s[i].size()];
		}
	}
	opt[0][0] = 1;
	for(int i=1; i<=n; i++){
		vector<int> vect(k + 1);
		for(int j=0; j<=k; j++){
			int transitable = 0;
			if(dp2[i+1][j] && opt[i-1][j]) transitable |= 1;
			if(dp2[i+1][j] && j >= s[i].size() && opt[i-1][j - s[i].size()]) transitable |= 2;
			if(transitable == 3){
				if(opts[i-1].substr(j - s[i].size(), s[i].size()) <= s[i]) transitable = 1;
				else transitable = 2;
			}
			vect[j] = transitable;
		}
		if(count(vect.begin(), vect.end(), 2) == 0){
			int lst = 0;
			for(int j=0; j<=k; j++){
				if(vect[j]){
					opt[i][j] = opt[i-1][j];
					lst = j;
				}
			}
			opts[i] = opts[i-1].substr(0, lst);
			continue;
		}
		for(int j=0; j<=k; j++){
			if(vect[j] == 2){
				string this_part = opts[i-1].substr(0, j - s[i].size()) + s[i];
				// hardest part (others are easy to optimize)
				// become interesting
				for(int x = j; x <= k && x < j + s[i].size(); x++){
					if(vect[x] == 2){
						string next_part = opts[i-1].substr(0, x - s[i].size()) + s[i];
						if(this_part >= next_part.substr(0, this_part.size())){
							this_part = next_part;
						}
					}
				}
				opts[i] = this_part;
				break;
			}
		}
		int matched = 1;
		for(int j=0; j<=opts[i].size(); j++){
			if(vect[j] == 1){
				if(opts[i-1].substr(0, j) == opts[i].substr(0, j)) opt[i][j] = 1;
			}
			if(vect[j] == 2){
				if(opts[i-1].substr(0, j - s[i].size()) + s[i] == opts[i].substr(0, j)) opt[i][j] = 1;
			}
		}
	}
	puts(opts[n].c_str());
}

