            if (o.x[i] > T[k+i]) { ok = false; break; }
            if (o.x[i] < T[k+i]) { ok = true; break; }
        }
        if (!ok) break;
        for (int i = 0; i < o.x.size(); i++) {
            T[k+i] = o.x[i];
        }
        build(k+o.x.size(), o.y+1);
    }
    string q; q.resize(K-k);
    memcpy(const_cast<char*>(q.c_str()),T+k,K-k);
    M[{k,n}] = q;
}

