	{
		for (j = 0; j <= k; j++)
		{
			if (dp[i + 1][j])
			{
				dp[i][j] = true;
			}
			if (dp[i + 1][j] && j + val[i].length() <= k)
			{
				dp[i][j + val[i].length()] = true;
			}
		}
	}
	int now = 0, pre = 1;
	int cnt = 0;
	for (i = 1; i <= n; i++)
	{
		if (dp[i + 1][k - val[i].length()])
		{
			cnt++;
			loc[pre][cnt][0] = i;
			loc[pre][cnt][1] = 0;
		}
	}
	string res = "";
	int remain = k;
	for (i = 1; i <= k; i++)
	{
		mem(vis, 0);
		char minx = 'z';
		for (j = 1; j <= cnt; j++)
		{
			minx = min(minx, val[loc[pre][j][0]][loc[pre][j][1]]);
		}
		int ncnt = 0;
		int mn = 1e8;
		for (j = 1; j <= cnt; j++)
		{
			char x = val[loc[pre][j][0]][loc[pre][j][1]];
			if (x != minx)continue;
			if (loc[pre][j][1] == val[loc[pre][j][0]].length() - 1)
			{
				mn = min(mn, loc[pre][j][0]);
			}
			else
			{
				vis[loc[pre][j][0]] = 1;
				++ncnt;
				loc[now][ncnt][0] = loc[pre][j][0];
				loc[now][ncnt][1] = loc[pre][j][1] + 1;
			}
		}
		remain--;
		for (j = mn + 1; j <= n; j++)
		{
			if (vis[j])continue;
			if (dp[j + 1][remain - val[j].length()])
			{
				ncnt++;
				loc[now][ncnt][0] = j;
				loc[now][ncnt][1] = 0;
			}
		}
		res = res + minx;
		cnt = ncnt;
		pre = 1 - pre;
		now = 1 - now;
	}
	cout << res << endl;
}

