vector<int> Z(const string& str){
    int n = str.size();
    vector<int> ret(n);
    int L=0, R=0;
    for(int i=1;i<n;i++){
        if(R<i){
            L = R = i;
            while(R<n&&str[R-L]==str[R]) R++;
            ret[i] = R-L; R--;
        }
        else{
            int k = i-L;
            if(ret[k] <= R-i+1) ret[i] = ret[k];
            else{
                L = i;
                while(R<n&&str[R-L]==str[R]) R++;
                ret[i] = R-L; R--;
            }
        }
    }
    return ret;
}

const int NMAX = 2222;
const int KMAX = 11111;
bool ok[NMAX][KMAX];
string ans;
string in[NMAX];
bool dp[2][KMAX];

int main(){
    cin.sync_with_stdio(0);
    cout.sync_with_stdio(0);

    int N, K; cin>>N>>K;
    for(int i=1;i<=N;i++) cin>>in[i];

    ok[N][K] = true;
    for(int i=N;i>1;i--) for(int j=0;j<=K;j++) if(ok[i][j]){
        ok[i-1][j] = true;
        if(j>=in[i].size()) ok[i-1][j-in[i].size()] = true;
    }

    ans = "";
    dp[0][0] = true;
    for(int i=1;i<=N;i++){
        for(int j=0;j<=K;j++) dp[i%2][j] = false;
        vector<int> z = Z(in[i]+'$'+ans);
        int S = in[i].size();

        // find first proper index
        int f = -1;
        for(int j=0;j<ans.size();j++) if(j+S<=K && dp[(i+1)%2][j] && ok[i][j+S]){
            if(z[S+1+j] < min(S, (int)ans.size() - j)){
                if(ans[j+z[S+1+j]] > in[i][z[S+1+j]]){
                    f = j;
                    break;
                }
            }
        }

        if(f>=0){
            // slice
            string str = ans.substr(0,f) + in[i];
            vector<int> z2 = Z(in[i]+'$'+str);
            for(int j=0;j<=str.size()-S;j++) if(dp[(i+1)%2][j]){
                dp[i%2][j] = true;
                if(z2[S+1+j] == S) dp[i%2][j+S] = true;
            }
            ans = str;
            continue;
        }

        // check tail case
        vector<int> z2 = Z(in[i]);
        bool tail = false;
        int offset = 0;
        while(ans.size()+S-offset > K)
            offset++;

        int st = offset;
        if(offset == 0) tail = true, st++;
        for(int j=st;j<S;j++) if(ans.size()>=j && dp[(i+1)%2][ans.size()-j]){
            if(!tail){
                int t = z[S+1+ans.size()-j];
                if(t + ans.size()-j < ans.size()){
                    if(ans[t+ans.size()-j] > in[i][t]){
                        tail = true;
                        offset = j;
                    }
                }
                continue;
            }
            if(z2[j] <= z2[offset]){
                if(j+z2[j]<S && in[i][j+z2[j]] < in[i][offset+z2[j]])
                    offset = j;
            }
            else{
                if(j+z2[offset]<S && in[i][j+z2[offset]] < in[i][offset+z2[offset]])
                    offset = j;
            }
        }

        if(tail){
            string str = ans.substr(0,ans.size()-offset) + in[i];
            vector<int> z3 = Z(in[i]+'$'+str);
            for(int j=0;j<=str.size()-S;j++) if(dp[(i+1)%2][j]){
                dp[i%2][j] = true;
                if(z3[S+1+j] == S) dp[i%2][j+S] = true;
            }
            ans = str;
        }
        else{
            for(int j=0;j<=ans.size();j++) dp[i%2][j] = dp[(i+1)%2][j];
        }
    }

    cout<<ans;
}

