		}
		else id[i] = id[i - 1], st[i] = st[i - 1];

        if(Rm[i + 1][k - st[i - 1].size()])
            st[i] = checkagain(st[i - 1], st[i], s[i], nowp, pos, i);

		//cerr << st[i] << ", size = " << id[i].size() << endl;
	}

	cout << st[n];
	return 0;
