string str[2000];

const int MAXN=2e4+5;
int z[MAXN];
string s,ss;
void Zvalue(int len){
   z[0]=len;
   int l=0,r=0,x;
   for(int i=1;i<len;i++){
      if(r<i||z[i-l]>=r-i+1){
         r<i?x=i:x=r+1;
         while(x<len&&ss[x]==ss[x-i])  x++;
         z[i]=x-i;if(i<x){l=i;r=x-1;};
      }
      else
         z[i]=z[i-l];
   }
   z[len]=0;
}

bool dp[2001][10001];
bool can[10001];
int main(){
	ios_base::sync_with_stdio(0);
