	for(int i=n-1;i>=0;i--)
		for(int j=0;j<=k;j++)
			dp[i][j]=(dp[i+1][j]|(j<str[i].size()?false:dp[i+1][j-str[i].size()]));
	int now=0;
	can[0]=true;
	for(int i=0;i<n;i++){
		ss=str[i]+'@'+s;
		int len=str[i].size();
		Zvalue(ss.size());
		int mn=-1;
		for(int j=0;j<=now;j++){
			if(!can[j]||(str[i].size()+j>k)||!dp[i+1][k-str[i].size()-j])	continue;
			if(mn==-1){
				if(j==now)	mn=j;
			/*	else if(z[len+j+1]==len)
					mn=j;
				else if(z[len+j+1]<len&&ss[z[len+j+1]]<ss[len+j+1+z[len+j+1]])	mn=j;*/
				else if(z[len+j+1]<len&&(len+j+1+z[len+j+1]==ss.size()||ss[z[len+j+1]]<ss[len+j+1+z[len+j+1]]))	mn=j;
			}
			else{
				if(z[len+mn+1]>=j-mn){
					if(z[j-mn]==len-(j-mn))
						mn=j;
					else if(str[i][z[j-mn]]<str[i][j-mn+z[j-mn]])
						mn=j;
				}
				else if(s[z[len+mn+1]+mn]<str[i][z[len+mn+1]])
					mn=j;
			}
		}
		if(mn!=-1){
			int tmp=mn+z[len+mn+1];
			ss=str[i]+'@'+s.substr(0,mn)+str[i];
			Zvalue(ss.size());
			for(int j=tmp+1;j<=10000;j++)
				can[j]=false;
			for(int j=k;j>=0;j--)
				if((can[j]&&dp[i+1][k-j])||(j-len>=0&&can[j-len]&&dp[i+1][k-j]&&z[j+1]==len))
						can[j]=true;
				else
					can[j]=false;

			can[mn+str[i].size()]=true;
			s=s.substr(0,mn);
			s+=str[i];
			now=mn+str[i].size();
		}
	}
	cout<<s<<endl;
}

