		s.push_back(t);
		low.push_back(i);
		for ( int j = 0; j < t.size(); j++ ){
			if ( j )  Hash[i][j] = Hash[i][j-1] + ( po[j] * t[j]) ;
			else Hash[i][j] = t[j];
		}
		for ( int j = 0; j <= k; j++ ) dp2[i].push_back("");
	}
	sort(low.begin(),low.end(),cmp);
	for ( int i = 0; i < n; i++ ) ra[low[i]] = i;

	for ( int i = 0; i < n; i++ ){
		for ( int j = i ; j < n; j++ ) rmq[i].push_back(j);
		sort(rmq[i].begin(),rmq[i].end(),cmprank);
	}

	string ans = getstr(0,0);
	cout << ans << endl;
	return 0;
}

