	{
		vector<bool> dp(1, 1);
		can.pb(dp);
		for(int i = n - 1; i >= 0; i--){
			vector<bool> next(dp.size() + v[i].size());
			rep(j, dp.size()) if(dp[j]) next[j] = next[j + v[i].size()] = 1;
			can.pb(next);
			dp = next;
		}
		reverse(all(can));
	}
	vector<bool> from(1, 1);
	string ans;

	rep(i, n){
		vector<bool> next(from.size() + v[i].size());

		rep(j, from.size()) if(from[j]){
