void add(string &a,ll in)
{
	ll i=0;
	for(int j=0;j<a.length();j++)
	{
		if(tree[i].nxt[a[j]-'a']==-1)
			tree[i].nxt[a[j]-'a']=make_new();
		i=tree[i].nxt[a[j]-'a'];
	}
	tree[i].end=1;
	tree[i].id.pb(in);
}
void dfs(ll i)
{
	if(i==-1)return;
	if(tree[i].end)
	{
		sort(tree[i].id.begin(), tree[i].id.end());
		for(auto j:tree[i].id)
			order.pb(j);
	}
	for(int j=0;j<26;j++)
		dfs(tree[i].nxt[j]);
}
