{
	ans+=s[i];
	if(s[i].length()==cnt)
		return;
	for(auto j:order)
		if(j>i&&yup[cnt-s[i].length()][at[j]])
		{
			get_ans(j,cnt-s[i].length());
			break;
		}
}
