#include <bits/stdc++.h>

using namespace std;

typedef unsigned long long ull;

const int maxn = 2e3 + 505;
const int maxm = 2e4 + 505;
const ull seed = 499;

int n, k;

ull fac[maxn * 505];
ull cur[maxm];

char ex[maxm];
string s[maxm], st[maxm];

struct Node {
	int id, s;
	Node (int Id = 0, int S = 0) {
		id = Id; s = S;
	}
};

vector<ull> Hash[maxn];
vector<Node> id[maxn];

bool Rm[maxn][maxm];

inline int read() {
	char ch = getchar(); int u = 0, f = 1;
	while(!isdigit(ch)) {if(ch == '-') f = -1; ch = getchar();}
	while(isdigit(ch)) {u = u * 10 + ch - 48;  ch = getchar();} return u * f;
}

inline void checkit(string &st, string &s, int &nowp, int &pos, int i, int j, int id) {
	int l = 1, r = min(pos, j) + s.size(), R = 0, mid = (l + r) / 2; R = r;
	int siz = s.size(), ans = 0, ch0, ch1;
	while(l <= r) {
		mid = (l + r) / 2;
		ull H0 = 0, H1 = 0;
		if(mid <= pos) H0 = cur[mid];
		else H0 = cur[pos] * fac[mid - pos] + Hash[id][mid - pos];
		if(mid <= j)   H1 = cur[mid];
		else H1 = cur[j] * fac[mid - j] + Hash[id][mid - j];
		if(H0 == H1) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	if(ans == R) {if(j > pos) nowp = i, pos = j;}
	else {
		if(ans >= pos) ch0 = s[ans - pos]; else ch0 = st[ans];
		if(ans >= j) ch1 = s[ans - j]; else ch1 = st[ans];
		if(ch0 > ch1) nowp = i, pos = j;
	}
}

inline string checkagain(string &st, string &now, string &s, int nowp, int pos, int p) {
	int l = 1, r = min(now.size(), st.size()), R = 0, mid = (l + r) / 2; R = r;
	int siz = s.size(), ans = 0, ch0, ch1;
	while(l <= r) {
		mid = (l + r) / 2;
		ull H0 = 0, H1 = 0;
		H0 = cur[mid];
		if(mid <= pos) H1 = cur[mid];
		else H1 = cur[pos] * fac[mid - pos] + Hash[p][mid - pos];
		if(H0 == H1) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	if(ans == R) {
        if(st.size() > now.size()) {
            id[p] = id[p - 1]; return st;
        } else return now;
	}
	else {
		ch0 = now[ans]; ch1 = st[ans];
		if(ch0 > ch1) {id[p] = id[p - 1]; return st;}
		else return now;
	}
}

int main() {
	//freopen("data.out", "r", stdin);
	//freopen("my.out", "w", stdout);

	n = read(); k = read(); fac[0] = 1;

	for(register int i = 1; i < maxn * 505; i++)
		fac[i] = fac[i - 1] * seed;

	for(register int i = 1; i <= n; i++) {
		scanf("%s", ex); s[i] = ex;
		Hash[i].resize(s[i].size() + 1);
		for(register int j = 1; j <= s[i].size(); j++)
			Hash[i][j] = Hash[i][j - 1] * seed + s[i][j - 1];
	}

	//cerr << "ok" << endl;
    cerr << endl;

	Rm[n + 1][0] = 1;
	for(register int i = n; i >= 1; i--)
		for(register int j = 0; j <= k; j++) {
			bool t = 0;
			if(j - s[i].size() >= 0) t = Rm[i + 1][j - s[i].size()];
			Rm[i][j] = Rm[i + 1][j] | t;
		}

	if(Rm[2][k - s[1].size()]) {
        id[1].push_back(Node(1, s[1].size()));
        st[1] = s[1];
	}

	for(register int i = 2; i <= n; i++) {
		int nowp = -1, pos = -1; cur[0] = 0;

		for(register int j = 1; j <= min(k, (int)st[i - 1].size()); j++)
			cur[j] = cur[j - 1] * seed + st[i - 1][j - 1];

		for(register int j = 0; j <= id[i - 1].size(); j++) {
			int siz = j ? id[i - 1][j - 1].s : 0;
			if(siz + s[i].size() > k) continue;
			if(Rm[i + 1][k - (siz + s[i].size())]) {
				if(nowp == -1) nowp = j, pos = siz;
				else checkit(st[i - 1], s[i], nowp, pos, j, siz, i);
			}
		}

		if(nowp != -1) {
			//id[i] = id[i - 1]; id[i].resize(nowp);
			id[i].clear();
			for(register int j = 0; j < nowp; j++) id[i].push_back(id[i - 1][j]);
			id[i].push_back(Node(i, pos + s[i].size()));
			st[i] = st[i - 1].substr(0, pos) + s[i];
		}
		else id[i] = id[i - 1], st[i] = st[i - 1];

        if(Rm[i + 1][k - st[i - 1].size()])
            st[i] = checkagain(st[i - 1], st[i], s[i], nowp, pos, i);

		cerr << st[i] << ", size = " << id[i].size() << endl;
	}

	cout << st[n];
	return 0;
}
