#include <bits/stdc++.h>
using namespace std;

int n, k;
string s[2005], ans;
bitset <10001> ok[2005];
bitset <10001> dp[2005];

int z[10005];
void do_z(string s){
    ///z[i] = prefixul maxim care coincide cu [i, i + z[i] - 1]

    int L = s.size();
    z[0] = L;
    for(int i = 1, last = 1, right = 1; i < L ; ++i){
        z[i] = 0;
        if(i <= right) z[i] = min(right - i + 1, z[i - last]);

        while(s[z[i]] == s[i + z[i]]) ++z[i];
        if(i + z[i] - 1 > right) right = i + z[i] - 1, last = i;
    }
}

int main()
{
    cin.tie(0);
    ios_base::sync_with_stdio(0);

    cin >> n >> k;
    for(int i = 1; i <= n ; ++i) cin >> s[i];

    ok[n + 1][0] = true;
    for(int i = n; i >= 1 ; --i){
        ok[i] = ok[i + 1];
        ok[i] = ok[i] | (ok[i + 1] << (s[i].size()));
    }

    dp[0][0] = 1;
    for(int i = 1; i <= n ; ++i){
        do_z(s[i] + ans);

        dp[i] = dp[i - 1];
        int L = s[i].size();
        for(int j = L; j <= k ; ++j){
            if(j - L > ans.size()) break ;
            if(dp[i - 1][j - L] == false || ok[i + 1][k - j] == false) continue ;

            int aux = z[j];
            if(aux >= L){
                dp[i][j] = true;
                continue ;
            }

            if(j - L == ans.size() || s[i][aux] < ans[aux]){
                dp[i][j] = true;
                ans = ans.substr(0, j - L) + s[i];
                for(int t = j + 1; t <= k ; ++t)
                    dp[i][t] = false;
                break ;
            }

        }
    }

    cout << ans;

    return 0;
}

