  dp[n][0] = mp(n,-10000);
  REPR(i,n-1){
    REP(j,k+1){

      // 次に選択した物のindexを持つようにする

      if(dp[i+1][j] != mp(INF,INF))
        dp[i][j] = min(dp[i][j], dp[i+1][j]);
      if(j >= len[i] && dp[i+1][j-len[i]] != mp(INF,INF))
        dp[i][j] = min(dp[i][j], mp(ind[i], dp[i+1][j-len[i]].first));

