    lis.pb(sp[dp[pos][siz].first].second);

    if(dp[pos][siz].second == n)return lis;
    lis.splice(lis.begin(), move(f(sp[dp[pos][siz].second].second, siz - len[sp[dp[pos][siz].first].second])));

    return move(lis);
  };
  pair<int,int> hog(INF,INF);
  REP(i,n){
    if(dp[i][k].first == INF)
      continue;
    hog = min(hog, dp[i][k]);
  }
  // VECCOUT(li);
