vector<PII> trans[2]; 

int main () {

	File();

	n = read(); k = read();

	For (i, 1, n)
		scanf ("%s", str[i] + 1), len[i] = strlen(str[i] + 1);

	dp[n + 1][0] = true;
	Fordown (i, n, 1)
