struct myBitset{
    vector < ull > f;
    myBitset(int x) : f(x / 64 + 1) {}

    myBitset() {

    }

    void shift() {
        for (int i = f.size() - 1; i >= 0; i--) {
            if (i + 1 < f.size()) {
                f[i + 1] |= 1;
            }
            f[i] = f[i] << 1;
        }
    }
    bool get(int x) {
        return (bool)((f[x / 64] >> (x & 63)) & one);
    }

    void set(int x, bool p) {
        if (p) {
            f[x / 64] |= (one << (x & 63));
        }
        else {
            f[x / 64] |= (one << (x & 63));
            f[x / 64] ^= (one << (x & 63));
        }
    }

    bool can_and(myBitset& other) {
        bool c = false;
        for (int i = 0; i < f.size(); i++) {
            c |= (f[i] & other.f[i]);
        }
        return c;
    }

    void do_and(myBitset& other) {
        for (int i = 0; i < f.size(); i++) {
            f[i] &= other.f[i];
        }
    }
};

