        if (can[i + 1][k - s[i].size()] && s[i][0] == best + 'a') {
            bits[i].set(0, true);
        }
        for (int j = 0; j < 26; j++) {
            at_most[i][j] = myBitset(s[i].size());
            at_least[i][j] = myBitset(s[i].size());
            for (int p = 0; p < s[i].size(); p++) {
                if (s[i][p] - 'a' <= j) {
                    at_most[i][j].set(p, true);
                }
                if ((int)(s[i][p] - 'a') > j) {
                    at_least[i][j].set(p, false);
                }
                else {
                    at_least[i][j].set(p, true);
                }
            }
        }
    }
    for (int len = 2; len <= k; len++) {
        int at_least = n + 1;
//        cout << 1 << " " << bits[1].f[0] << " HI " << endl;
        for (int i = 1; i <= n; i++) {
            if (bits[i].get(s[i].size() - 1)) {
                at_least = i;
                break;
            }
        }
//        cout << len << " " << at_least << endl;
        for (int i = n; i >= 1; i--) {
            bits[i].shift();
            if (i >= at_least + 1 && k - len + 1 >= s[i].size() && can[i + 1][k - len + 1 - s[i].size()]) bits[i].set(0, true);
        }
        int l = -1;
        int r = 25;
        while (r - l > 1) {
            int mid = (l + r) / 2;
            bool ok = false;
            for (int j = 1; j <= n; j++) {
                if (bits[j].can_and(at_most[j][mid])) {
                    ok = true;
                    break;
                }
            }
            if (ok) r = mid;
            else l = mid;
        }
//        cout << "GOT " << r << endl;
        ans += (char)(r + 'a');
        if (r != 25) {
            for (int i = n; i >= 1; i--) {
                bits[i].do_and(::at_least[i][r]);
            }
        }
//        if (len == 2) {
//            cout << bits[1].f[0] << " WUT " << endl;
//        }
    }
    cout << ans;
    return 0;
}

