vector<int> ZAlgorithm(string s){
	vector<int> z(s.size());
	z[0] = s.size();
	int i = 1, j = 0;
	while (i < s.size()) {
		while (i+j < s.size() && s[j] == s[i+j]) ++j;
		z[i] = j;
		if (j == 0) { ++i; continue;}
		int k = 1;
		while (i+k < s.size() && k+z[k] < j) z[i+k] = z[k], ++k;
		i += k; j -= k;
	}
	return z;
}

class Solution {
public:
	void solve() {
		int n, k;
		cin >> n >> k;
		vector<string> s(n);
		for(int i=0; i<n; i++)cin >> s[i];
		vector<vector<bool>> ok(n+1, vector<bool>(k+1, false));
		ok[n][k] = true;
		for(int i=n; i >= 1; i--){
			int l = s[i-1].length();
			for(int j=k; j >= 0; j--){
				if(!ok[i][j])continue;
				ok[i-1][j] = true;
				if(j-l >= 0)ok[i-1][j-l] = true;
			}
		}
		string cs(k, 'z');
		set<int> p({0});
		for(int i=0; i < n; i++){
			string t = s[i] + cs;
			int len = s[i].length();
			auto z = ZAlgorithm(t);
			set<int> np;
			for(auto j: p){
				np.insert(j);
				if(j+len > k)continue;
				if(!ok[i+1][j+len])continue;
				else if(z[j+len] >= len){
					np.insert(j+len);
				}
				else if(z[j+len] < len){
					if(s[i][j+z[j+len]] < cs[z[j+len]]){
						for(int l=z[j+len]; l < len; l++)cs[j + l] = s[i][l];
						for(auto l: p)if(l <= j+len)np.insert(l);
						np.insert(j+len);
						break;
					}
				}
			}
			p = np;
		}
		cout << cs << "\n";

		return;
	};
};

