vector<int> Z(const string& str){
    int n = str.size();
    vector<int> ret(n);
    int L=0, R=0;
    for(int i=1;i<n;i++){
        if(R<i){
            L = R = i;
            while(R<n&&str[R-L]==str[R]) R++;
            ret[i] = R-L; R--;
        }
        else{
            int k = i-L;
            if(ret[k] <= R-i+1) ret[i] = ret[k];
            else{
                L = i;
                while(R<n&&str[R-L]==str[R]) R++;
                ret[i] = R-L; R--;
            }
        }
    }
    return ret;
}

const int NMAX = 2222;
const int KMAX = 11111;
bool ok[NMAX][KMAX];
string ans;
string in[NMAX];
bool dp[2][KMAX];

int main(){
    cin.sync_with_stdio(0);
    cout.sync_with_stdio(0);

    int N, K; cin>>N>>K;
    for(int i=1;i<=N;i++) cin>>in[i];

    ok[N][K] = true;
    for(int i=N;i>1;i--) for(int j=0;j<=K;j++) if(ok[i][j]){
        ok[i-1][j] = true;
        if(j>=in[i].size()) ok[i-1][j-in[i].size()] = true;
    }

    ans = "";
    dp[0][0] = true;
    for(int i=1;i<=N;i++){
        for(int j=0;j<=K;j++) dp[i%2][j] = false;
        vector<int> z = Z(in[i]+'$'+ans);
        int S = in[i].size();

        // find first proper index
        int f = -1;
        for(int j=0;j<ans.size();j++) if(dp[(i+1)%2][j] && ok[i][j+S]){
            if(z[S+1+j] < S){
                if(ans[j+z[S+1+j]] > in[i][z[S+1+j]]){
                    f = j;
                    break;
                }
            }
        }

        if(f>=0){
            // slice

            ans = ans.substr(0,f);
            ans += in[i];
            for(int j=0;j<=ans.size()-S;j++) if(dp[(i+1)%2][j])
                dp[i%2][j] = true;
            dp[i%2][ans.size()] = true;
            continue;
        }

        // append.
        dp[i%2][ans.size()] = true;
        for(int j=0;j<ans.size();j++) if(dp[(i+1)%2][j]){
            dp[i%2][j] = true;
            if(z[S+1+j] == S) dp[i%2][j+S] = true;
        }
        if(ans.size() + S <= K && ok[i][ans.size()+S]){
            ans += in[i];
            dp[i%2][ans.size()] = true;
        }
    }

    cout<<ans;
}

