inline void checkit(string &st, string &s, int &nowp, int &pos, int i, int j, int id) {
	int l = 1, r = min(pos, j) + s.size(), R = 0, mid = (l + r) / 2; R = r;
	int siz = s.size(), ans = 0, ch0, ch1;
	while(l <= r) {
		mid = (l + r) / 2;
		ull H0 = 0, H1 = 0;
		if(mid <= pos) H0 = cur[mid];
		else H0 = cur[pos] * fac[mid - pos] + Hash[id][mid - pos];
		if(mid <= j)   H1 = cur[mid];
		else H1 = cur[j] * fac[mid - j] + Hash[id][mid - j];
		if(H0 == H1) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	if(ans == R) {if(j > pos) nowp = i, pos = j;}
	else {
		if(ans >= pos) ch0 = s[ans - pos]; else ch0 = st[ans];
		if(ans >= j) ch1 = s[ans - j]; else ch1 = st[ans];
		if(ch0 > ch1) nowp = i, pos = j;
	}
}

inline string checkagain(string &st, string &now, string &s, int nowp, int pos, int p) {
	int l = 1, r = min(now.size(), st.size()), R = 0, mid = (l + r) / 2; R = r;
	int siz = s.size(), ans = 0, ch0, ch1;
	while(l <= r) {
		mid = (l + r) / 2;
		ull H0 = 0, H1 = 0;
		H0 = cur[mid];
		if(mid <= pos) H1 = cur[mid];
		else H1 = cur[pos] * fac[mid - pos] + Hash[p][mid - pos];
		if(H0 == H1) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	if(ans == R) {
        if(st.size() > now.size()) {
            id[p] = id[p - 1]; return st;
        } else return now;
	}
	else {
		ch0 = now[ans];
		ch1 = st[ans];
		if(ch0 > ch1) {id[p] = id[p - 1]; return st;}
		else return now;
	}
}

