void updateNext(char c, int remain)
{
	next_which.clear();
	next_pos.clear();
	int firstFinish = n + 1;
	//int rate = which.size() / 4000;
	int rate = 0;
	for (int i = 0; i < which.size(); i += (rate + 1))
