}P[2005];
int tot = 0;
void Solve() {
    read(N);read(K);
    for(int i = 1 ; i <= N ; ++i) cin >> str[i];
    f[N + 1][0] = 1;
    for(int i = N ; i >= 1 ; --i) {
	int l = str[i].length();
	for(int j = K ; j >= 0 ; --j) {
	    if(j >= l) f[i][j] |= f[i + 1][j - l];
	    f[i][j] |= f[i + 1][j];
	}
    }
    base[0] = 1;
    for(int i = 1 ; i <= 10000 ; ++i) base[i] = 1LL * base[i - 1] * ba % MOD;
    for(int i = 1 ; i <= N ; ++i) {
	may.clear();
	for(int j = 0 ; j <= tot ; ++j) {
	    if(P[j].s.length() + str[i].length() <= K && f[i + 1][K - P[j].s.length() - str[i].length()]) may.pb(j);
	}
	if(!may.size()) continue;
	int t = may[0];
	for(int j = 1 ; j < may.size() ; ++j) {
	    int k = may[j];
	    int h = min(P[t].s.length(),P[k].s.length());
	    int l = 0,r = h - 1;
	    while(l < r) {
		int mid = (l + r + 1) >> 1;
		if(P[t].hsh[mid] != P[k].hsh[mid]) r = mid - 1;
		else l = mid;
	    }
	    if(r == h - 1) {
		if(P[t].s.length() < P[k].s.length()) t = k;
	    }
	    else {
		if(P[k].s[r + 1] < P[t].s[r + 1]) t = k;
	    }
	}
	P[++tot].s = P[t].s + str[i];
	for(int j = 0 ; j < P[tot].s.length() ; ++j) {
	    P[tot].hsh[j] = 1LL * base[j] * (P[tot].s[j] - 'a' + 1);
	    if(j != 0) {
		P[tot].hsh[j] += P[tot].hsh[j - 1];
		P[tot].hsh[j] %= MOD;
	    }
	}
    }
    string ans = "";
    for(int i = 1 ; i <= tot ; ++i) {
	if(P[i].s.length() == K) {
	    if(ans == "") ans = P[i].s;
	    else ans = min(ans,P[i].s);
	}
    }
    cout << ans << endl;
}

