	Rm[n + 1][0] = 1;
	for(register int i = n; i >= 1; i--)
		for(register int j = 0; j <= k; j++) {
			bool t = 0;
			if(j - s[i].size() >= 0) t = Rm[i + 1][j - s[i].size()];
			Rm[i][j] = Rm[i + 1][j] | t;
		}

	if(Rm[2][k - s[1].size()]) {
        id[1].push_back(Node(1, s[1].size()));
        st[1] = s[1];
	}

	for(register int i = 2; i <= n; i++) {
		int nowp = -1, pos = -1; cur[0] = 0;

		for(register int j = 1; j <= min(k, (int)st[i - 1].size()); j++)
			cur[j] = cur[j - 1] * seed + st[i - 1][j - 1];

		for(register int j = 0; j <= id[i - 1].size(); j++) {
			int siz = j ? id[i - 1][j - 1].s : 0;
			if(siz + s[i].size() > k) continue;
			if(Rm[i + 1][k - (siz + s[i].size())]) {
				if(nowp == -1) nowp = j, pos = siz;
				else checkit(st[i - 1], s[i], nowp, pos, j, siz, i);
			}
		}

		if(nowp != -1) {
			//id[i] = id[i - 1]; id[i].resize(nowp);
			id[i].clear();
			for(register int j = 0; j < nowp; j++) id[i].push_back(id[i - 1][j]);
