inline ll gethash(ll* ha,int x,int y)
{
	if(!x)
		return ha[y];
	return ha[y]-ha[x-1]*fmp[y-x+1];
}
int lcpdp(int x,int y)
{
	int l=0,r=y+1;
	while(r-l>1)
	{
		int mid=(l+r)>>1;
		if(gethash(dphash[x],0,mid-1)==gethash(dphash[y],0,mid-1))
			l=mid;
		else
			r=mid;
	}
	return l;
}
int lcp2(int x,int y,int xoff)
{
	int l=0,r=len[y]+1;
	while(r-l>1)
	{
		int mid=(l+r)>>1;
		if(gethash(dphash[x],xoff,xoff+mid-1)==gethash(strhash[y],0,mid-1))
			l=mid;
		else
			r=mid;
	}
	return l;
}
