				if(!vis[j])vis[j]=1,A[j]=node(j-ll,i);
				else A[j]=(A[j]<node(j-ll,i)?A[j]:node(j-ll,i));
			}
		}tp=0;
		for(int j=0;j<=K;j++)if(vis[j])
		{
			while(tp&&A[j]<sta[tp])--tp;
			if(!tp||A[j]==sta[tp])sta[++tp]=A[j];
		}assert(tp);
		anslen=sta[tp].x+len[sta[tp].y];if(sta[tp].y)--anslen;
		for(int j=1;j<len[sta[tp].y];j++)ans[j+sta[tp].x]=S[sta[tp].y][j];
		memset(flag,0,sizeof(flag));
		for(int j=1;j<=tp;j++)flag[sta[j].x+(sta[j].y?len[sta[j].y]-1:0)]=1;

//		for(int j=1;j<=anslen;j++)putchar(ans[j]);puts("");
	}
	assert(anslen==K);
	for(int i=1;i<=K;i++)putchar(ans[i]);
	return 0;
}

