void build(int k, int n) {
    if (M.find({k,n}) != M.end()) {
        string &s = M[{k,n}];
        memcpy(T+k, s.c_str(), K-k);
        return;
    }
    if (k == K) return;

    vector<pair<string,int>> O;
    for (int i = n; i < N; i++) {
        if (W[N-i][K-k] && 
                ((k + S[i].size() == K) ||
                 (k + S[i].size() < K && W[N-i-1][K-k-S[i].size()]))) {
            O.push_back({S[i],i});
        }
    }
    sort(wh(O));
