class SuffixArray{
    void make_lcp(int const*s){
        for(int i=0, k=0;i<n;++i)
            if(inv[i]!=0){
                for(int j = sa[inv[i]-1];k<n-max(i, j) && s[i+k]==s[j+k];++k);
                lcp[inv[i]-1]=k;
                if(k)--k;
            } else k=0;
    }
    bool cmp(vector<int> const&rank,int i,int j,int l){
        return i<n-l && j<n-l && rank[i]==rank[j] && rank[i+l]==rank[j+l];
    }
    void build_SA(int const*s){
        int m = max(256, n);
        sa.resize(n);
        vector<int> x(n), y(n), buck(m);
        int i,j,p;
        for(i=0;i<n;++i) buck[x[i]=s[i]]++;
        for(i=1;i<m;++i) buck[i]+=buck[i-1];
        for(i=n-1;i>=0;--i) sa[--buck[x[i]]]=i;
        for(p=0,j=1;p+1<n;m=p+1,j*=2) {
            for(p=0,i=n-j;i<n;++i) y[p++]=i;
            for(i=0;i<n;++i) if (sa[i]>=j) y[p++]=sa[i]-j;
            memset(buck.data(),0,sizeof(int)*(m));
            for(i=0;i<n;++i) ++buck[x[y[i]]];
            for(i=1;i<m;++i) buck[i]+=buck[i-1];
            for(i=n-1;i>=0;--i) sa[--buck[x[y[i]]]]=y[i];
            x.swap(y);
            for(p=0,x[sa[0]]=0,i=1;i<n;i++) x[sa[i]]=cmp(y,sa[i-1],sa[i],j) ? p : ++p;
        }
        x.swap(inv); y.swap(lcp);
        for(int i=0;i<n;++i) inv[sa[i]]=i;
        make_lcp(s);
    }
    public:
    SuffixArray(int const*s, int _N):n(_N){build_SA(s);}
    SuffixArray(vector<int> const&s):SuffixArray(s.data(), s.size()){}
    SuffixArray(char const*s, int _N):n(_N){build_SA(vector<int> (s, s+n).data());}
    SuffixArray(string const&s):SuffixArray(s.data(), s.size()){}
    vector<int> sa, inv, lcp;
    const int n;
};
const int K = 10001;
vi suffix_badness(string s){
    SuffixArray sa(s);
    vi ans(sz(s));
    int badness = 0;
    rep(i,0,sz(s)-1){
        ans[sa.sa[i]] = badness;
        if(sa.lcp[i] != sz(s)-sa.sa[i])
            ++badness;
    }
    return ans;
}
void _(){
    int n,k;
    cin >> n >> k;
    vs arr(n);
    cin >> arr;
    vector<bitset<K>> can_finish(n+1);
    can_finish[n][k] = true;
    for(int i = n; i >= 1; --i)
        can_finish[i-1] = can_finish[i] | (can_finish[i] >> sz(arr[i-1]));
    string s = "";
    vb splits(K);
    splits[0] = true;
    rep(i,0,n-1){
        vi badness = suffix_badness(arr[i]);
        vi match_len = z_alg(arr[i]+s);
        match_len = vi(match_len.begin()+sz(arr[i]),match_len.end());
        match_len.pb(sz(arr[i]));
        vvi upgrades;
        for(int keep = sz(s); keep >= 0; --keep){
            if(keep+sz(arr[i]) > k) continue;
            if(!splits[keep]) continue;
            if(!can_finish[i+1][keep+sz(arr[i])]) continue;
            int same = min(match_len[keep],int(sz(arr[i])));
            same = min(same,int(sz(s))-keep);
            if(same == sz(arr[i])){
                splits[keep+same] = true;
                continue;
            }
            if(same+keep == sz(s)){
                upgrades.pb({same+keep,badness[same],same});
            }else{
                int nxt_diff = same+keep;
                if(arr[i][same] > s[nxt_diff]) continue;
                upgrades.pb({same+keep,badness[same],same});
            }
        }
        if(upgrades.empty()) continue;
        //assert(!upgrades.empty());
        sort(all(upgrades));
        while(
                upgrades.back()[0] != upgrades[0][0] ||
                upgrades.back()[1] != upgrades[0][1])
            upgrades.pop_back();
        int same_keep = upgrades[0][0];
        int same = upgrades[0][2];
        s = s.substr(0,same_keep) + arr[i].substr(same);
        splits[sz(s)] = true;
        fill(splits.begin()+sz(s)+1,splits.end(),false);
        for(auto _ : upgrades){
            int total_len = _[0] + sz(arr[i]) - _[2];
            assert(total_len <= sz(s));
            splits[total_len] = true;
        }
    }
    print(s);
}
