    int curl = cur.length();
    for(int j = 1; j <= curl - 1; j++)
      dp[i][j] = dp[i - 1][j];
    for(int j = curl; j <= k; j++){
      dp[i][j] = "\256";
      if(dp[i-1][j].length() == j)
        dp[i][j] = minst(dp[i][j], dp[i - 1][j]);
      if(dp[i-1][j-curl].length() == j-curl)
        dp[i][j] = minst(dp[i][j], dp[i - 1][j - curl] + cur);
    }
  }
  string ans = "\256";
  for(int i = 1; i <= n; i++){
    ans = minst(ans, dp[i][k]);
  }
  cout << ans << endl;
  return 0;
}

