std::vector<int> z_algorithm(const std::string& S) {
  std::vector<int> Z(S.size());
  for(int i = 1, L = 0, R = 0; i < S.size(); ++i) {
    if(i > R) {
      L = R = i;
      while(R < S.size() && S[R - L] == S[R]) ++R;
      Z[i] = R-- - L;
    } else {
      if(Z[i - L] < R - i + 1) Z[i] = Z[i - L];
      else {
        L = i;
        while(R < S.size() && S[R - L] == S[R]) ++R;
        Z[i] = R-- - L;
      }
    }
  }
  return Z;
}

