    if(can[i+1][k-len[i]]) loc.push_back(start[i]);
  }
  string ans = "";
  for(int eee = 0; eee < k; eee++){
    //for(int x : loc) cout << x << " "; cout << endl;
    assert(!loc.empty());
    int mn = 1e9;
    for(int x : loc){
      mn = min(mn, ss[x]);
    }
    ans.push_back(mn + 'a');
    int mnn = 1e9;
    vector<int> nextloc;
    for(int x : loc){
      if(ss[x] != mn) continue;
      if(critical[x+1] != -1){
	mnn = min(mnn, critical[x+1]);
      }
      else{
	nextloc.push_back(x+1);
      }
    }
    if(mnn != 1e9){
      for(int i = mnn; i < n; i++){
	if(k-eee-1-len[i]>=0 && can[i+1][k-eee-1-len[i]]) nextloc.push_back(start[i]);
      }
    }
    loc = nextloc;
  }
  cout << ans << "\n";
}

