vector<int> Z(const string& str){
    int n = str.size();
    vector<int> ret(n);
    int L=0, R=0;
    for(int i=1;i<n;i++){
        if(R<i){
            L = R = i;
            while(R<n&&str[R-L]==str[R]) R++;
            ret[i] = R-L; R--;
        }
        else{
            int k = i-L;
            if(ret[k] <= R-i+1) ret[i] = ret[k];
            else{
                L = i;
                while(R<n&&str[R-L]==str[R]) R++;
                ret[i] = R-L; R--;
            }
        }
    }
    return ret;
}

