        if(f>=0){
            // slice

            ans = ans.substr(0,f);
            ans += in[i];
            for(int j=0;j<=ans.size()-S;j++) if(dp[(i+1)%2][j])
                if(ok[i][j]) dp[i%2][j] = true;
            if(ok[i][ans.size()]) dp[i%2][ans.size()] = true;
