void Zalgo(char* str,int s,int* lcp){
	fill(lcp,lcp+s+1,0);
	int p=0;
	FOR(i,1,s){
		if(i+lcp[i-p]<p+lcp[p])
			lcp[i]=lcp[i-p];
		else{
			lcp[i]=max(0,p+lcp[p]-i);
			while(i+lcp[i]<s&&str[lcp[i]]==str[i+lcp[i]])
				lcp[i]++;
			p=i;
		}
	}
	lcp[0]=s;
}

