			if(j > p + s[i].size() - 1) continue;
			if(!Rm[i + 1][k - (j - 1)] || !ok[t][j]) continue;
            ull H0 = 0, H1 = 0;
            H0 = cur[j - 1];
			if(j > p - 1) H1 = cur[p - 1] * fac[j - p] + Hash[j - p];
            else H1 = cur[j - 1];
            if(H0 == H1) ok[t0][j] = 1;
		}

