using namespace std;
int n, k;
const int maxn = 2005;
const int maxk = 10005;
const int maxc = 1e6 + 20;
int len[maxn];
int start[maxn];

bitset<maxk> can[maxn];
int ss[maxc];
int critical[maxc];

int main(){
  memset(critical, -1, sizeof(critical));
  cin >> n >> k;
  int tt = 0;
  vector<bool> appr(26);
  for(int i=0;i<n;i++){
    string s; cin >> s;
    len[i] = s.length();
    start[i] = tt;
    critical[tt] = i;
    for(int e=0;e<s.length();e++){
      int c = s[e] - 'a';
      appr[c] = true;
      ss[tt] = c;
      tt++;
    }
  }
  int numappr = 0;
  for(int i=0;i<26;i++)if(appr[i]) numappr++;
  if(numappr == 1){
    for(int i=0;i<26;i++){
      if(appr[i]){
	cout << string(k, (i + 'a')) << "\n";
	return 0;
      }
    }
  }

  can[n][0] = true;
  for(int i=n-1;i>=0;i--){
    can[i] = can[i+1] | (can[i+1]<<len[i]);
  }
  vector<int> loc;
  for(int i=0;i<n;i++){
    if(can[i+1][k-len[i]]) loc.push_back(start[i]);
  }
  string ans = "";
  for(int eee = 0; eee < k; eee++){
    //for(int x : loc) cout << x << " "; cout << endl;
    assert(!loc.empty());
    int mn = 1e9;
    for(int x : loc){
      mn = min(mn, ss[x]);
    }
    ans.push_back(mn + 'a');
    int mnn = 1e9;
    vector<int> nextloc;
    for(int x : loc){
      if(ss[x] != mn) continue;
      if(critical[x+1] != -1){
	mnn = min(mnn, critical[x+1]);
      }
      else{
	nextloc.push_back(x+1);
      }
    }
    if(mnn != 1e9){
      for(int i = mnn; i < n; i++){
	if(k-eee-1-len[i]>=0 && can[i+1][k-eee-1-len[i]]) nextloc.push_back(start[i]);
      }
    }
    loc = nextloc;
  }
  cout << ans << "\n";
}

