char memo[2001][10010];
bool can(int ne, int res) {
  if (res < 0) return false;
  if(res == 0) return true;
  if(ne == n) return false;
  if(memo[ne][res>=0)
     return memo[ne][res];

  for (int i = ne; i < n; ++i) {
    if (can(i + 1, res - SZ(s[i])))
      return memo[ne][res] = true;
  }

  return memo[ne][res] = false;
}

