		for(int i = 0 ; i < S.size() ; i ++){
			if(i+(1<<(t-1)) < S.size()){
				sa[i][t] = lower_bound(vec.begin(),vec.end(),P(sa[i][t-1],sa[i+(1<<(t-1))][t-1]))-vec.begin();
			}
			else {
				sa[i][t] = lower_bound(vec.begin(),vec.end(),P(sa[i][t-1],-1)) - vec.begin();
			}
		}
	}
}

int comp(int x,int y,int len,int t){
	if(len == 0)return 0;
	if(len < (1<<t))return comp(x,y,len,t-1);
	if(sa[x][t] == sa[y][t])return comp(x+(1<<t),y+(1<<t),len-(1<<t),t-1);
	else {
		if(sa[x][t] < sa[y][t])return 1;
		else return -1;
	}
}

