	SA_IS(string &S){
		S.push_back('$');
		vector<int> n(S.size());

		map<int,int> mp;

		for(int i=0;i<S.size();i++){
			n[i] = encode(S[i]);
			mp[n[i]]=0;
		}

		int now = 0;
		for(auto &a:mp){
			a.second = now;
			now++;
		}

		for(int i=0;i<n.size();i++){
			n[i] = mp[n[i]];
		}

		a = suffix_array(n);

		rank.resize(a.size());
		for(int i=0;i<a.size();i++){
			rank[a[i]]=i;
		}

		LCP = build_LCP(n);
	}

	vector<int> suffix_array(vector<int> n){

		{
			vector<int> ret(n.size(),-1);
			bool f = true;
			for(int i=0;i<n.size();i++){
				if(ret[n[i]]!=-1){
					f=false;
					break;
				}
				ret[n[i]]=i;
			}
			if(f)return ret;
		}

		vector<bool> is_L(n.size(),false);
		vector<vector<int>> indices(n.size(),vector<int>());
		vector<int> l(n.size()),r(n.size());

		for(int i=n.size()-2;i>=0;i--){
			if(n[i]==n[i+1])is_L[i]=is_L[i+1];
			else if(n[i]>n[i+1])is_L[i]=true;
		}

		for(int i=0;i<n.size();i++){
			indices[n[i]].push_back(-1);
		}

		for(int i=0;i<n.size();i++){
			l[i] = 0;
			r[i] = indices[i].size();
		}

		for(int i=n.size()-1;i>=1;i--){
			if(!is_L[i]&&is_L[i-1]){
				r[n[i]]--;
				indices[n[i]][r[n[i]]]=i;
			}
		}



		induced_sort(n,is_L,indices,l,r);

