				indices[i][j]=-1;
			}
			l[i] = 0;
			r[i] = indices[i].size();
		}

		for(int i=LMSs.size()-1;i>=0;i--){
			int pos = LMSs[i];
			r[n[pos]]--;
			indices[n[pos]][r[n[pos]]]=pos;
