bool dfs(int x,int y)
{
	if(y<0) return false;
	if(x==n) return (y==0);
	if(f[x][y]!=-1) return f[x][y];
	f[x][y]=dfs(x+1,y-len[x]) | dfs(x+1,y);
	return f[x][y];
}

bool same(const pii &a,const pii &b,int l)
{
	//1. 都在两个的id范围内
	if(l<=a.first && l<=b.first)
	{
		return true;
	}
	//2. 在a的id范围内，在b的str[var]内(说明b.second==1)
	if(l<=a.first)
	{
		if(gethash(curH,b.first,l)==gethash(strH,0,l-b.first)) return true;else return false;
	}
	//3. 在b的id范围内。
	if(l<=b.first)
	{
		if(gethash(curH,a.first,l)==gethash(strH,0,l-a.first)) return true;else return false;
	}
	//4. 都在范围外
	/*
	____--
	__--
	*/
	if(a.first>b.first)
	{
		if(gethash(curH,b.first,a.first)!=gethash(strH,0,a.first-b.first)) return false;
		if(gethash(strH,0,b.first+len[var]-a.first)!=gethash(strH,a.first-b.first,len[var])) return false;
		return true;
	}
	else
	{
		if(gethash(curH,a.first,b.first)!=gethash(strH,0,b.first-a.first)) return false;
		if(gethash(strH,0,a.first+len[var]-a.first)!=gethash(strH,b.first-a.first,len[var])) return false;
		return true;
	}
}

bool compare(const pii &a,const pii &b)
{
	int len1=a.first+a.second*len[var];
	int len2=b.first+b.second*len[var];
	int l=min(a.first,b.first),r=min(len1,len2),mid,res=-1;
	while(l<=r)
	{
		mid=(l+r)>>1;
		if(same(a,b,mid))
		{
			res=mid;
			l=mid+1;
		}
		else
		{
			r=mid-1;
		}
	}
	if(res==min(len1,len2)) return len1>len2;
	if(res>=a.first && res>=b.first)
	{
		return str[var][res-a.first]<str[var][res-b.first];
	}
	if(res>=a.first)
	{
		return str[var][res-a.first]<cur[res];
	}
	if(res>=b.first)
	{
		return cur[res]<str[var][res-b.first];
	}
}

bool check(pii a,pii b)
{
	int len1=a.first+a.second*len[var];
	int len2=b.first+b.second*len[var];
	int l=0,r=min(len1,len2),mid,res=-1;
	if(len2>len1) return false;
	while(l<=r)
	{
		mid=(l+r)>>1;
		if(same(a,b,mid))
		{
			res=mid;
			l=mid+1;
		}
		else
		{
			r=mid-1;
		}
	}
	if(res==min(len1,len2)) return true;
	return false;
}

