pii operator+(pii a, pii b) { return pii(a.Fi+b.Fi>=P1 ? a.Fi+b.Fi-P1 : a.Fi+b.Fi, a.Se+b.Se>=P2 ? a.Se+b.Se-P2 : a.Se+b.Se); }
