void write(int x, char c) {
	ans[x] = c;
	sans[x] = sans[x-1] + pii(c, c) * PW[x];
}

pii get_h1(int l, int r) {
	return (sans[r] - sans[l-1]) * PW[10005 - r];
}

vector <pii> In[2020];
pii get_h2(int x, int idx) {
	return In[x][idx] * PW[10005 - idx];
}

pair<string, int> X[2020];
int main() {
	PW[0] = pii(1, 1); for(int i=1;i<10010;i++) PW[i] = pii(PV, PV) * PW[i-1];
	scanf("%d%d", &N, &K);
	for(int i=1;i<=N;i++) {
		scanf("%s", buf);
		s[i] = (string)buf;
		X[i] = make_pair(s[i], i);
		pii now = pii(0, 0);
		for(int j=0;buf[j];j++) {
			now = now + pii(buf[j], buf[j]) * PW[j];
			In[i].pb(now);
		}
	}
	sort(X+1, X+1+N);

	for(int i=0;i<=K;i++) dp[i] = -1;
	dp[0] = N+1;
	for(int i=N;i;i--) {
		int x = szz(s[i]);
		for(int j=K;j>=x;j--) if(dp[j] == -1) {
			if(dp[j-x] != -1) dp[j] = i;
		}
	}
	for(int i=0;i<10010;i++) min_index[i] = N + 1, write(i, 'z' + 1);
	min_index[0] = 0;

	for(int L=0;L<=K;L++) {
