		int idx = min_index[L];
		for(int a=1;a<=N;a++) {
			int j = X[a].Se;
			if(j <= idx) continue;
			int lj = szz(X[a].Fi);
			if(L + lj > K || dp[K-L-lj] <= j) continue;

			int op = 0;
			int low = 0, high = lj - 1, fd = -1;
			while(low <= high) {
				int mid = (low + high) >> 1;
				if(get_h1(L+1, L+1+mid) != get_h2(a, mid)) fd = mid + 1, high = mid - 1;
				else low = mid + 1;
			}
			if(fd != -1) {
				op = (ans[L+fd] > X[a].Fi[fd-1]) ? 1 : -1;
			}

			if(op == -1) break;
			if(op == 0) {
				if(min_index[L+lj] > j) {
					min_index[L+lj] = j;
				}
			}
			else {
				for(int b=L+fd;b<=L+lj;b++) min_index[b] = N + 1, write(b, X[a].Fi[b-L-1]); // ans[b] = X[a].Fi[b-L-1];
				for(int b=L+lj+1;b<=K;b++) min_index[b] = N + 1, write(b, 'z'+ 1); // ans[b] = 'z' + 1;
				min_index[L+lj] = j;
			}
		}
	}
	for(int i=1;i<=K;i++) printf("%c", ans[i]); puts("");

	return 0;
}

