    tag[0]=true;
    rep(i,1,n){
        a=s[i]+str; exKMP(a);
        rep(j,0,k) if (tag[j]) cur[j]={j,0};
        data mx={-1,0};
        per(j,k,1){
            if (!f[i+1][k-j]){ tag[j]=false; continue; }
            if (tag[j]) cur[j]={j,0};
            if (j>=l[i]&&tag[j-l[i]]){
                if (tag[j]&&cmp(cur[j],{j-l[i],1},i)) cur[j]={j-l[i],1};
                else if (!tag[j]) tag[j]=true,cur[j]={j-l[i],1};
            }
            if (mx.x==-1) mx=cur[j];
        }
        if (mx.x==-1) continue;
        per(j,k,1) if (tag[j]&&cmp(mx,cur[j],i)) mx=cur[j];
        rep(j,1,k) if (cmp(cur[j],mx,i)) tag[j]=false;
        per(j,k,1)
