			if (u[s[i].size()] == mod) {
				u[s[i].size()] = i;
			}
			else {
				int id = u[s[i].size()];
				if (s[id] > s[i]) {
					u[s[i].size()] = i;
				}
			}
		}
	}
	rep(i, k) {
		int mi = 25;
		rep1(j, k) {
			if (u[j] == mod)continue;
			int id = u[j];
			mi = min(mi, s[id][s[id].size() - j] - 'a');
		}
		char ch = 'a' + mi;
		vector<int> nex;
		//cout << i << " " << u[1] << endl;
		if (u[1] < mod&&s[u[1]][s[u[1]].size() - 1] == ch) {
			Rep(j, u[1] + 1, n) {
				if (k - i - 1 >= s[j].size() && b[j + 1][k - i - 1 - (int)s[j].size()]) {
					nex.push_back(j);
				}
			}
		}
		ans.push_back(ch);
		u[1] = mod;
		Rep1(j, 2, k) {
			if (u[j] == mod)continue;
			if (s[u[j]][s[u[j]].size() - j] == ch) {
				u[j - 1] = u[j];
			}
			u[j] = mod;
		}
		rep(j, nex.size()) {
			int id = nex[j];
			//cout << i << " " << id << endl;
			int len = s[id].size();
			if (u[len] == mod) {
				u[len] = id;
			}
			else {
				int to = u[len];
				if (to < id) {
					if (s[to].substr(s[to].size() - len, len) > s[id]) {
						u[len] = id;
					}
				}
				else {
					if (s[to].substr(s[to].size() - len, len) >= s[id]) {
						u[len] = id;
					}
				}

			}
		}
	}
	cout << ans << endl;
}

