P vis[2][maxk];
int main() {
    while (~scanf("%d%d",&n,&k)) {
        memset(ans,0,sizeof(ans));
        for (int i=1;i<=n;i++) scanf("%s",s[i]),len[i]=strlen(s[i]);
        dp[n+1][0]=1;
