int n, k;
string str[2000];

int memo1[2000][10005];
int dp1(int now, int len){ // returns 1 if reach end, 0 otherwise
	if(now == n){
		return len == k;
	}

	int& ret = memo1[now][len];
	if(ret != -1)return ret;

	ret = dp1(now+1, len);
	if(len+str[now].size() <= k)ret |= dp1(now+1, len+str[now].size());
	return ret;
}

bool dp2[2005][10005];

// Z[i] = LCP of string s[0..N] and s[i..N]
int Z[20005];
void buildZ(string s){
	int l,r;
	l = r = 0;
	Z[0] = s.size();
	for(int i = 1; i < s.size(); i++) {
	    if(i > r) { // over bound -> manual widen
	        l = r = i;
	        while(r < s.size() && s[r-l] == s[r]) r++;
	        Z[i] = r-l; r--;
	    }else{
	        if(Z[i-l] < r-i+1) Z[i] = Z[i-l];
	        else{ // lcp exceeds bound -> manual widen
	            l = i;
	            while(r < s.size() && s[r-l] == s[r]) r++;
	            Z[i] = r-l; r--;
	        }
	    }
	}
	Z[s.size()] = 0;
}

int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    #define endl '\n'
    cout.setf(ios::fixed);
    cout.setf(ios::showpoint);
    cout.precision(10);

    cin>>n>>k;
    FOR(i,n){
    	cin>>str[i];
    }

    memset(memo1, -1, sizeof memo1);

    string ans;
    dp2[0][0] = 1;
    FOR(i,n){
    	buildZ(str[i] + ans);

    	int right_lim = k;
    	int best = -1;
    	REP(j,0,k){
    		if(j <= right_lim && dp2[i][j] == 1){
    			dp2[i+1][j] = 1; // not adding str[i];

    			if(j+str[i].size() <= k && dp1(i+1, j+str[i].size())){
    				// adding str[i] can still reach end
    				int lcp = (j == ans.size()) ? 0 : Z[str[i].size() + j]; // lcp of str[i][0] and ans[j]
    				if(best != -1)lcp = Z[j - best]; // ans is already updated
    				if(lcp >= str[i].size()){ // adding str[i] won't do anything
    					dp2[i+1][j+str[i].size()] = 1;
    				}else if(lcp < str[i].size()){
    					if(lcp+j < ans.size() && str[i][lcp] > ans[lcp+j]){ // adding results in worse
    						// well, do nothing
    					}else{ // better result
    						dp2[i+1][j+str[i].size()] = 1;
    						right_lim = min(right_lim, j + lcp);

    						if(best != -1 && lcp+j < ans.size())dp2[i+1][best+str[i].size()] = 0;
    						best = j;
    						ans = ans.substr(0, best) + str[i];
    					}
    				}
    			}
    		}
    	}
    }

    assert(ans.size() == k);

    // printf("size ans %d, k %d\n",ans.size(),k);

    cout << ans << endl;

    return 0;
}

