bitset<Len> dp[N]; char str[N][Len], ans[Len];
int n, k, len[N];

vector<PII> trans[2]; 

int main () {

	File();

	n = read(); k = read();

	For (i, 1, n)
		scanf ("%s", str[i] + 1), len[i] = strlen(str[i] + 1);

	dp[n + 1][0] = true;
	Fordown (i, n, 1)
		dp[i] = dp[i + 1] | (dp[i + 1] << len[i]);

	int cur = 0;
	For (i, 1, n)
		if (dp[i + 1][k - len[i]])
			trans[cur].pb(mp(i, 1));

	For (i, 1, k) {

		char res = 'z';
		for (PII to : trans[cur]) {
			chkmin(res, str[to.fir][to.sec]);
		}
		ans[i] = res;

		int tot = 0;
		int pos = n;
		for (PII to : trans[cur]) {
			if (str[to.fir][to.sec] == res) {
				if (to.sec < len[to.fir])
					trans[cur ^ 1].pb(mp(to.fir, to.sec + 1));
				else
					chkmin(pos, to.fir);
			}
		}

		int rest = k - i;
		For (j, pos + 1, n) {
			if (rest >= len[j] && dp[j + 1][rest - len[j]])
				trans[cur ^ 1].pb(mp(j, 1));
		}
		trans[cur].clear(); cur ^= 1;

		while (trans[cur].size() > n) trans[cur].pop_back();

	}
	printf ("%s\n", ans + 1);

