    	int right_lim = k;
    	int best = -1;
    	REP(j,0,k){
    		if(j <= right_lim && dp2[i][j] == 1){
    			dp2[i+1][j] = 1; // not adding str[i];

    			if(j+str[i].size() <= k && dp1(i+1, j+str[i].size())){
    				// adding str[i] can still reach end
    				int lcp = Z[str[i].size() + j]; // lcp of str[i][0] and ans[j]
    				if(lcp >= str[i].size()){ // adding str[i] won't do anything
    					dp2[i+1][j+str[i].size()] = 1;
    				}else if(lcp < str[i].size()){
    					if(lcp+j < ans.size() && str[i][lcp] > ans[lcp+j]){ // adding results in worse
    						// well, do nothing
    					}else{ // better result
    						dp2[i+1][j+str[i].size()] = 1;
    						right_lim = min(right_lim, j + lcp);

    						best = j;
    					}
    				}
    			}
    		}
    	}
    	if(best != -1) ans = ans.substr(0, best) + str[i];
    }

