				if(j-l >= 0)ok[i-1][j-l] = true;
			}
		}
		string cs(k, 'z');
		set<int> p({0});
		for(int i=0; i < n; i++){
			string t = s[i] + cs;
			int len = s[i].length();
			auto z = ZAlgorithm(t);
			set<int> np;
			for(auto j: p){
				np.insert(j);
				if(j+len > k)continue;
				if(!ok[i+1][j+len])continue;
				else if(z[j+len] >= len){
					np.insert(j+len);
				}
				else if(z[j+len] < len){
					if(t[j+z[j+len]] < cs[j]){
						for(int l=0; l < len; l++)cs[j + l] = s[i][l];
						for(auto l: p)if(l <= j+len)np.insert(l);
						np.insert(j+len);
						break;
					}
				}
			}
			p = np;
		}
		cout << cs << "\n";

		return;
	};
};

