    for(int i=1;i<=n;++i)
    {
        S='*'+st[i]+ans;ExKMP();int mn=-1;
        for(int j=0;j+len[i]<=K;++j) if(f[j]&&b[i+1][j+len[i]])
        {
            if(mn==-1) {mn=j;continue;}
            if(Small(mn,j,len[i])>=0) mn=j;
        }
        if(mn==-1) continue;
        memset(f+mn+1,0,sizeof(bool)*(K-mn+3));
        for(int j=0;j<=mn;++j) 
        {
            if((f[j]&&b[i+1][j])) f[j]=1;
            if(f[j]&&b[i+1][j+len[i]]&&(j==mn||Small(j,mn,len[i])==0)) f[j+len[i]]=1;
        }
        ans=ans.substr(0,mn)+st[i];
    }
    cout<<ans;
    return 0;
}

