	std::vector<std::vector<int>> can_make(n + 1);
	can_make.back() = std::vector<int>(k + 1, n);
	can_make.back()[0] = -1;
	for (int i = n - 1; i >= 0; --i) {
		can_make[i] = can_make[i + 1];
		for (int j = k - str[i].size(); j >= 0; --j) {
			if (can_make[i][j] != n && rank[i] < rank[can_make[i][j + str[i].size()]]) {
				can_make[i][j + str[i].size()] = i;
			}
		}
	}
	std::vector<int> result;
	int rest{ k }, pos{ can_make.front()[k] };
	while (rest > 0) {
		result.push_back(pos);
		rest -= str[result.back()].size();
		pos = can_make[pos + 1][rest];
	}
	for (const auto i : result) {
		std::cout << str[i];
	}
	std::cout << '\n';
}

