typedef pair <P,int> PP;

char instr[MX];
string str[SIZE];
vector <PP> dp[MX];//dp[i]=PP(P(後ろからi番目までの長さの和,i含むhashの和),id)
vector <PP> now;
vector <ll> hash1[SIZE];//後ろからのhash
ll rt[MX],all[SIZE];
int n,K;

void make()
{
	rt[0]=1;
	for(int i=1;i<MX;i++) rt[i]=rt[i-1]*B1%M1;
}
ll get_hash(vector <PP> vec,int L,int len)//先頭L文字分
{
	L=len-L;//後ろ先求める
	int f=lower_bound(vec.begin(),vec.end(),PP(P(L+1,-1),-1))-vec.begin()-1;
	ll ret=0;
	if(f>0) ret=vec[f-1].first.second;
	int v=vec[f].second;
	int zan=L-vec[f].first.first;
	ret+=hash1[v][zan]*rt[L-zan]%M1;
	if(ret>=M1) ret-=M1;
	//ret:先頭L文字分
	ll sum=vec[vec.size()-1].first.second;
	sum-=ret;
	if(sum<0) sum+=M1;
	return sum;
}
char get_char(vector <PP> vec,int L,int len)//先頭L文字目
{
	L=len-L;//後ろからL文字目に直す
	int f=lower_bound(vec.begin(),vec.end(),PP(P(L+1,-1),-1))-vec.begin()-1;
	int v=vec[f].second;
	int zan=L-vec[f].first.first;
	//printf("* %d %d : %d %d\n",str[v].size(),zan,vec[f].first.first,f);
	return str[v][str[v].size()-zan];
}
int main()
{
	make();
	scanf("%d %d",&n,&K);
	for(int i=0;i<n;i++)
	{
		scanf("%s",&instr);
		str[i]=instr;
		ll sum=0;
		hash1[i].push_back(sum);
		for(int j=0;j<str[i].size();j++)
		{
			sum+=rt[i+1]*(ll) (str[i][str[i].size()-j-1]-'a'+1)%M1;
			if(sum>=M1) sum-=M1;
			hash1[i].push_back(sum);
		}
		all[i]=sum;
	}
	for(int i=n-1;i>=0;i--)
	{
		for(int j=K;j>=str[i].size();j--)
		{
			int to=j-str[i].size();
			if(to>0&&dp[to].empty()) continue;
			now=dp[to];
			ll sum=to==0?0:dp[to][dp[to].size()-1].first.second;
			sum+=rt[to]*all[i]%M1;
			if(sum>=M1) sum-=M1;
			now.push_back(PP(P(to,sum),i));
			if(dp[j].empty()) dp[j]=now;
			else//compare
			{
				int l=0,r=j+1;//はじめて異なる場所
				while(r-l>1)
				{
					int m=(l+r)/2;
					if(get_hash(dp[j],m,j)==get_hash(now,m,j)) l=m;
					else r=m;
				}/*
				if(j==K)
				{
					printf("%d %d : %c %c\n",i,l,get_char(dp[j],l,j),get_char(now,l,j));
					for(int k=0;k<now.size();k++) printf("%d ",now[k].second);puts("");
					for(int k=0;k<dp[j].size();k++) printf("%d ",dp[j][k].second);puts("");
				}*/
				if(l<j&&get_char(dp[j],l,j)>get_char(now,l,j)) dp[j]=now;
			}
		}
	}
	for(int i=0;i<dp[K].size();i++)
	{
		int v=dp[K][dp[K].size()-i-1].second;
		printf("%s",str[v].c_str());
	}puts("");
	return 0;
}

