		if(mid <= pos) H1 = cur[mid];
		else H1 = cur[pos] * fac[mid - pos] + Hash[p][mid - pos];
		if(H0 == H1) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	if(ans == R) {
        if(st.size() > now.size()) {
            id[p] = id[p - 1]; return st;
        } else return now;
	}
	else {
		//if(ans >= pos) ch0 = s[ans - pos]; else ch0 = st[ans];
		//ch1 = st[ans + 1];
		ch0 = now[ans];
		ch1 = st[ans];
		if(ch0 > ch1) {id[p] = id[p - 1]; return st;}
		else return now;
	}
}

