int n,k;
int dp[2005][10005];
bool vs[2005][10005];
string dp2[2005][10005];
vector < string > s;
vector < int > low;
int ra[2005];
char inp[10005];
vector < int > rmq[2005];

bool cmp( int a, int b ){
	return s[a] < s[b];
}

bool cmprank( int a, int b ){
	return ra[a] < ra[b];
}

int dfs( int pos, int sz ){
	if ( sz > k ) return false;
	if ( sz == k ) return true;
	if ( pos == n ) return false;
	int &ans = dp[pos][sz];
	if ( ans != -1 ) return ans;
	ans = dfs(pos+1,sz);
	if ( sz + s[pos].size() <= k ) ans = max( ans, dfs(pos+1, sz + s[pos].size()));
	return ans;
}

string getstr( int pos, int sz ){
	if ( pos >= n ) return "";
	if ( sz == k ) return  "";

	if ( vs[pos][sz] ) return dp2[pos][sz];
	int len = rmq[pos].size();
	vs[pos][sz] = true;

	string ans = "";
	for ( int i = 0; i < len; i++ ){
		int id = rmq[pos][i];
		if ( dfs(id+1, sz + s[id].size()) ) {
			string tmp;
			tmp = s[id] + getstr(id+1, sz + s[id].size() );
			if ( ans == "" || tmp < ans ) ans = tmp;
			if ( tmp >= ans ) break;
		}
	}
	return dp2[pos][sz] = ans;
}

int main(){
	memset(dp,-1,sizeof(dp));
	scanf("%d%d",&n,&k);
	for ( int i = 0; i < n; i++ ){
		scanf("%s",&inp);
		string t = inp;
		s.push_back(t);
		low.push_back(i);
	}
	sort(low.begin(),low.end(),cmp);
	for ( int i = 0; i < n; i++ ) ra[low[i]] = i;

	for ( int i = 0; i < n; i++ ){
		for ( int j = i ; j < n; j++ ) rmq[i].push_back(j);
		sort(rmq[i].begin(),rmq[i].end(),cmprank);
	}

	string ans = "";
	for ( int i = 0; i < n; i++ ){
		int id = rmq[0][i];
		if ( dfs(id+1, s[id].size()) ){
			string tmp = s[id] + getstr(id+1, s[id].size());
			if ( ans == "" || tmp < ans ) ans = tmp;
			if ( tmp >= ans ) break;
		}
	}
	cout << ans << endl;
	return 0;
}

