const int maxn = 2020, maxk = 10100;
using bs = bitset<maxk>;
bs can[maxn];
string s[maxn];
int len[maxn];
char ss[maxk];
int main(){
	int n, k; cin >> n >> k;
	for(int i = 0; i < n; i++){
      scanf("%s", ss);
      s[i] = ss;
    }
	for(int i = 0; i < n; i++) len[i] = s[i].size();
	can[n][0] = 1;
	for(int i = n - 1; i >= 0; i--) can[i] = can[i + 1] | (can[i + 1] << s[i].size());
	vector<pair<int,int> > q, nq;
	for(int i = 0; i < n; i++) if(k - len[i] >= 0 && can[i + 1][k - len[i]]) q.push_back({i, 0});
	for(int i = 1; i <= k; i++){
		char best = 'z';
		for(auto e : q) best = min(best, s[e.first][e.second]);
		printf("%c", best);
		int f = n;
		for(auto e : q){
			if(s[e.first][e.second] != best) continue;
			if(e.second + 1 == s[e.first].size()) f = min(f, e.first);
			else nq.push_back({e.first, e.second+1});
		}
		for(int j = f + 1; j < n; j++){
			if(k - i - len[j] >= 0 && can[j + 1][k - i - len[j]]){
				nq.push_back({j, 0});
			}
		}
		q = nq;
		nq.clear();
	}
	printf("\n");
	return 0;
}

