vector<int> zalgo(string s){
	int i=1,j=0,n=s.size();
	vector<int> a(n,0);
	a[0]=n;
	while(i<n){
		while(i+j<n && s[j]==s[i+j]) j++;
		a[i]=j;
		if(j==0){i++;continue;}
		int k=1;
		while(i+k<n && k+a[k]<j){a[i+k]=a[k];++k;}
		i+=k;j-=k;
	}
	return a;
}

//T[0~be]とT[0~j]+Sを比較
int cal(int i,int be,int j){
	if(be<=j) return 0;
	int ma=za[j+len[i]];ma=min(ma,min(be-j,len[i]));
	if(ma==min(be-j,len[i])) return 0;
	else if(s[i][ma]<t[i][j+ma]) return 1;
	return -1;
}

//T[0~be]+SとT[0~j]+Sを比較
int cal2(int i,int be,int j){
	if(be>j) return -cal2(i,j,be);
	if(be==j) return 0;
	int ma=za[len[i]+be];
	if(ma<j-be){
		if(t[i][ma]<s[i][ma]) return 1;return -1;
	}
	else{
		ma=za[j-be];
		//if(i==2 && be==3 && j==4) cout<<ma<<endl;cout<<s[ma]<<' '<<
		if(ma>=len[i]-j+be) return 0;
		else if(s[i][ma]<s[i][ma+j-be]) return 1;return -1;
	}
}
int main()
{
