	memset(dp,false,sizeof(dp));dp[n][k]=true;
	rep(i,n){
		cin>>s[i];len[i]=s[i].size();
	}
	for(int i=n;i>0;i--) rep(j,k+1){
		if(!dp[i][j]) continue;
		if(j>=len[i-1]) dp[i-1][j-len[i-1]]=true;
		dp[i-1][j]=true;
	}
	/*rep(i,n) rep(j,k+1){
		if(dp[i][j]) cout<<i<<' '<<j<<endl;
	}*/
	rep(i,n) t[i]="";
	memset(d2,false,sizeof(d2));d2[0][0]=true;
	rep(i,n){
		//cout<<t[i]<<endl;rep(j,t[i].size()+1){if(d2[i][j]) cout<<j<<' ';}cout<<endl;
		za=zalgo(s[i]+t[i]);
		int be=-1;
		rep(j,t[i].size()+1){
			if(j+len[i]>k || !dp[i+1][j+len[i]] || !d2[i][j]) continue;
			if(be<0){
				int x=cal(i,t[i].size(),j);
				if(x>0 || (x==0 && j+len[i]>t[i].size())) be=j;
			}
			else{
				int x=cal2(i,be,j);
				if(x>=0) be=j;
			}
		}
		rep(j,t[i].size()+1){
			if(!d2[i][j]) continue;
			if(dp[i+1][j]){
				if(be<0) d2[i+1][j]=true;
				else{
					if(cal(i,j,be)<=0) d2[i+1][j]=true;
				}
			}
			if(j+len[i]>k || !dp[i+1][j+len[i]]) continue;
			if(be<0){
				if(cal(i,t[i].size(),j)>=0) d2[i+1][j+len[i]]=true;
			}
			else{
				if(cal2(i,be,j)>=0) d2[i+1][j+len[i]]=true;
			}
		}
		if(be<0) t[i+1]=t[i];
		else t[i+1]=t[i].substr(0,be)+s[i];
	}
	if(t[n].size()!=k){
		while(1){}
	}
	cout<<t[n]<<endl;
}

