	for(register int i = n; i >= 1; i--)
		for(register int j = 0; j <= k; j++) {
			if(j >= s[i].size()) Rm[i][j] |= Rm[i + 1][j - s[i].size()];
			Rm[i][j] |= Rm[i + 1][j];
		}

	if(Rm[2][k - s[1].size()]) {
		ok[0][1] = 1; len[1] = s[1].size();
		st[1] = s[1];
	}

	for(register int i = 2; i <= n; i++) {
		int t = i & 1, t0 = t ^ 1, p = -1;
		memset(ok[t0], 0, sizeof(ok[t0]));

		cur[0] = Hash[0] = 0;
		for(register int j = 1; j <= st[i - 1].size(); j++)
			cur[j] = cur[j - 1] * seed + st[i - 1][j - 1];
		for(register int j = 1; j <= s[i].size(); j++)
			Hash[j] = Hash[j - 1] * seed + s[i][j - 1];

        if(i == 147)
            int kk = 0;

		for(register int j = 1; j <= st[i - 1].size() + 1; j++) {
			if(ok[t][j]) ok[t0][j] = 1;
			if(!Rm[i + 1][k - (j + s[i].size() - 1)] || !(ok[t][j] || j > st[i - 1].size())) continue;
			if(gethash(j, i)) ok[t0][j + s[i].size()] = 1;
			if(p == -1) p = j;
			else p = checkit(st[i - 1], s[i], p - 1, j - 1) + 1;
		}

        if(p != -1)
            st[i] = st[i - 1].substr(0, p - 1) + s[i];
        else st[i] = st[i - 1];

		if(Rm[i + 1][k - st[i - 1].size()])
			st[i] = checkagain(st[i - 1], st[i], s[i], p - 1);

		if(st[i] == st[i - 1]) p = st[i].size() + 1;

		ok[t0][p] = 1;
		for(register int j = p + 1; j <= k; j++) ok[t0][j] = 0;

		//if(i == 147)
        //    cerr << st[i - 1].size() << " " << st[i].size() << endl;

		if(st[i].size() > st[i - 1].size()) {
			ull H0 = cur[st[i - 1].size()];
			ull H1 = cur[p - 1] * fac[st[i - 1].size() - (p - 1)] + Hash[st[i - 1].size() - (p - 1)];
			if(H0 == H1) ok[t0][st[i - 1].size() + 1] = 1;
		}

		/*cerr << "case" << i << ": " << endl;
		cerr << st[i] << endl;
		for(register int j = 1; j <= k; j++)
			cerr << ok[t0][j] << " ";
		cerr << "\n\n";*/
	}

	cout << st[n];
	return 0;
}
