typedef pair<int,int> pii;
const int maxn=2001;
const int maxk=10001;
const int maxs=1123456;
int n,K;
string s[maxk];
char tmp[maxs];
bitset<maxk> bit[maxn+1];
pii v[2][maxk];
int main()
{

    scanf("%d%d",&n,&K);
    for (int i=1;i<=n;++i) {
        scanf("%s",tmp);
        s[i]=tmp;
    }
    bit[n+1][0]=1;
    for (int i=n;i>=1;--i)
        bit[i]=bit[i+1]|(bit[i+1]<<s[i].length());
    int c1=0;
    for (int i=1;i<=n;++i)
        if (bit[i+1][K-s[i].length()])
            v[1][c1++]=pii(i,0);
    for (int o=1;o<=K;++o) {
        char mmin='z';
        for (int i=0;i<c1;++i)
            mmin=min(mmin,s[v[o&1][i].first][v[o&1][i].second]);
        putchar(mmin);
        int ID=n+1,c2=0;
        for (int i=0;i<c1;++i) {
            char ch=s[v[o&1][i].first][v[o&1][i].second];
            if (ch!=mmin) continue;
            ++v[o&1][i].second;
            if (v[o&1][i].second==(int)s[v[o&1][i].first].length()) ID=min(ID,v[o&1][i].first);
            else v[(o+1)&1][c2++]=v[o&1][i];
        }
        for (int i=ID+1;i<=n;++i) if (K-o-(int)s[i].length()>=0&&bit[i+1][K-o-s[i].length()])
            v[(o+1)&1][c2++]=pii(i,0);
        c1=c2;
    }
    return 0;
}

