class SuffixArray {
public:	
	int Sa[maxn], temp[maxn], rnk[maxn], height[maxn], tex[maxn], Height[maxn], st[maxn][20];
	IL void Sort(int n, int m) {
		for (int i = 0; i <= m; ++i) tex[i] = 0;
		for (int i = 1; i <= n; ++i) tex[rnk[i]]++;
		for (int i = 1; i <= m; ++i) tex[i] += tex[i - 1];
		for (int i = n; i; --i) Sa[tex[rnk[temp[i]]]--] = temp[i];
	}
	IL bool cmp(int x, int y, int w, int n) {
		return temp[x] == temp[y] && (x + w > n ? -1 : temp[x + w]) == (y + w > n ? -1 : temp[y + w]);
	}

	IL void build(char *s) {
		int n = strlen(s), m = 256;
		for (int i = 1; i <= n; ++i) rnk[i] = s[i - 1], temp[i] = i;
		Sort(n, m);
		for (int i = 1, p = 0, w = 1; p < n; w <<= 1, m = p) {
			for (i = n - w + 1, p = 0; i <= n; ++i) temp[++p] = i;
			for (i = 1; i <= n; ++i) if (Sa[i] > w) temp[++p] = Sa[i] - w;
			Sort(n, m);
			swap(temp, rnk);
			for (rnk[Sa[1]] = 1, p = 1, i = 2; i <= n; ++i) 
				rnk[Sa[i]] = cmp(Sa[i], Sa[i - 1], w, n) ? p : ++p;
		}
		for (int i = 1; i <= n; ++i) printf("%d ", Sa[i]); printf("\n");
		for (int i = 1, k = 0; i <= n; Height[rnk[i++]] = k) {
			if (k) --k;
			while (s[Sa[rnk[i] - 1] + k - 1] == s[i + k - 1]) k++;
		}
		for (int i = 2; i <= n; ++i) st[i][0] = Height[i];
	}

	IL int Lcp(int x, int y) {	
		x = rnk[x], y = rnk[y];
		if (x > y) swap(x, y); x++;
		int LOG = log2(y - x + 1);
		return min(st[x][LOG], st[y - (1 << LOG) + 1][LOG]);
	}
