			can[i+1][j] = true;
			if(j+v <= X) can[i+1][j+v] = true;
		}

	}
	show(can);
	string pre;
	using P = pair<int,bool>;
	V<bool> isActive(X+1); isActive[0] = true;
	rep(t,N){
		V<P> nxt(X+1,P(-1,false));
		string s = ss[t];
		int n = si(s);
		V<int> Z = Zalgo(s+"$"+pre);
		auto getDif = [&](P x,P y){
			int a = x.fs, b = y.fs;
			if(!x.sc){
				if(a<=b) return a;
				int pfx = Z[n+1+b];
				return b+pfx;
			}else{
				if(!y.sc){
					return a+Z[n+1+a];
				}else{
					int pfx = Z[n+1+a];
					if(b-a <= n){
						if(pfx < b-a) return a+pfx;
						return b + Z[b-a];
					}else{
						return a + pfx;
					}
				}
			}
		};
		auto getChar = [&](P x,int i){
			if(i < x.fs) return pre[i];
			return s[i-x.fs];
		};
		auto Set = [&](P& x, P y){
			if(x.fs == -1){
				x = y;
				return;
			}
			int i = getDif(x,y);
			int sz = x.fs + (x.sc ? n : 0);
			if(i == sz) return;
			if(getChar(x,i) > getChar(y,i)) x = y;
		};
		rep(len,X+1) if(isActive[len]){
			Set(nxt[len],P(len,false));
			if(len+n <= X) Set(nxt[len+n],P(len,true));
		}
		stack<int> st;
		rep(len,X+1) if(can[N-1-t][X-len] && nxt[len].fs != -1){
			if(st.empty()){
				st.push(len);
				continue;
			}
			int prev = st.top();
			int i = getDif(nxt[prev],nxt[len]);
			show(len);show(prev);show(i);
			if(i == prev){
				st.push(len);
			}else if(getChar(nxt[prev],i) < getChar(nxt[len],i)){
			}else{
				while(!st.empty() && st.top() > i) st.pop();
				st.push(len);
			}
		}
		int mx = st.top();
		rep(i,X+1) isActive[i] = false;
		while(!st.empty()){
			isActive[st.top()] = true;
			st.pop();
		}
		if(!nxt[mx].sc) pre = pre.substr(0,mx);
		else pre = pre.substr(0,nxt[mx].fs)+s;

		shows("--------- t done = ",t);
		show(mx);
		show(pre);
		show(nxt);
		show(isActive);

		assert(si(pre) == mx);
	}
	cout << pre << endl;
}

