void solve() {
	int n, k; cin >> n >> k;
	vector<string> s(n);
	rep(i, n) {
		cin >> s[i];
	}
	vector<bt> b(n + 1);
	b[n] = 0; b[n][0] = 1;
	per(i, n) {
		b[i] = b[i + 1] | (b[i + 1] << s[i].size());
	}
	string ans;
	vector<P> cur; int l = 0;
	rep(i, k) {
		int r = k - i;
		int mi = 26;
		Rep(j, l, n) {
			if (r >= s[j].size() && b[j + 1][r - s[j].size()]) {
				mi = min(mi, s[j][0] - 'a');
			}
		}
		rep(j, cur.size()) {
			if (cur[j].first == n)continue;
			mi = min(mi, s[cur[j].first][cur[j].second+1]-'a');
		}
		char ch = 'a' + mi; int nl = mod;
			vector<P> nex;
			Rep(j, l, n) {
				if (s[j][0]==ch&&r >= s[j].size() && b[j + 1][r - s[j].size()]) {
					if(s[j].size()>1){
						nex.push_back({ j,0 });
					}
					else {
						nl = min(nl, j + 1);
					}
				}
			}
			rep(j, cur.size()) {
				int id = cur[j].first;
				int sc = cur[j].second;
				if (id == n)continue;
				if (s[id][sc + 1] == ch) {
					if (sc + 1 == s[id].size() - 1)nl = min(nl, id + 1);
					else nex.push_back({ id,sc + 1 });
				}
			}
			ans.push_back(ch);
			cur = nex; l = nl;
	}
	cout << ans << endl;
}

