int main() {
  int N, K;
  cin >> N >> K;
  vector<string> S(N);
  for(auto& i: S) cin >> i;

  vector<vector<bool>> reach(N + 1, vector<bool>(K + 1));
  reach[N][0] = true;
  for(int i = N - 1; 0 <= i; --i) {
    reach[i] = reach[i + 1];
    for(int j = K; S[i].size() <= j; --j) reach[i][j] = reach[i][j] | reach[i][j - S[i].size()];
  }

  vector<string> CS(N + 1, "{}");
  vector<vector<bool>> dp(N + 1, vector<bool>(K + 1));
  dp[0][0] = true;
  for(int i = 0; i < N; ++i) {
    string best = CS[i];
    for(int j = 0; j <= K - S[i].size(); ++j) if(dp[i][j]) if(reach[i + 1][K - j - S[i].size()]) {
      auto s = CS[i].substr(0, j) + S[i] + "{}";
      best = min(best, s);
    }
    for(int j = 0; j <= int(best.size()) - int(S[i].size()); ++j) if(dp[i][j]) dp[i + 1][j] = true;
    dp[i + 1][best.size() - 2] = true;
    CS[i + 1] = best;
  }

  cout << CS[N].substr(0, CS[N].size() - 2) << endl;
}

