  for(int i=0;i<n;i++){
    //string s; getline(cin, s);
    cin >> s;
    len[i] = s.length();
    start[i] = tt;
    critical[tt] = i;
    for(int e=0;e<s.length();e++){
      int c = s[e] - 'a';
      appr[c] = true;
      ss[tt] = c;
      tt++;
    }
  }
  int numappr = 0;
  for(int i=0;i<26;i++)if(appr[i]) numappr++;
  if(numappr == 1){
    for(int i=0;i<26;i++){
      if(appr[i]){
	cout << string(k, (i + 'a')) << "\n";
	return 0;
      }
    }
  }

  can[n][0] = true;
  for(int i=n-1;i>=0;i--){
    can[i] = can[i+1] | (can[i+1]<<len[i]);
  }

  int q = 0;
  int cnt = 0;

  for(int i=0;i<n;i++){
    if(can[i+1][k-len[i]]) loc[q][cnt++] = start[i];
  }
  string ans = "";


  for(int eee = 0; eee < k; eee++){
    int mn = 1e9;
    for(int i=0;i<cnt;i++){
      int x = loc[q][i];
      mn = min(mn, ss[x]);
    }
    ans.push_back(mn + 'a');
    int mnn = 1e9;
    int ncnt = 0;
    for(int i=0;i<cnt;i++){
      int x = loc[q][i];
      if(ss[x] != mn) continue;
      if(critical[x+1] != -1){
	mnn = min(mnn, critical[x+1]);
      }
      else{
	loc[q ^ 1][ncnt++] = x + 1;
      }
    }
    if(mnn != 1e9){
      for(int i = mnn; i < n; i++){
	if(k-eee-1-len[i]>=0 && can[i+1][k-eee-1-len[i]]) loc[q ^ 1][ncnt++] = start[i];
      }
    }

    q ^= 1;
    cnt = ncnt;
  }
  cout << ans << "\n";
}

