vector< int > z_algorithm(const string &s) {
  vector< int > prefix(s.size());
  for(int i = 1, j = 0; i < s.size(); i++) {
    if(i + prefix[i - j] < j + prefix[j]) {
      prefix[i] = prefix[i - j];
    } else {
      int k = max(0, j + prefix[j] - i);
      while(i + k < s.size() && s[k] == s[i + k]) ++k;
      prefix[i] = k;
      j = i;
    }
  }
  prefix[0] = (int) s.size();
  return prefix;
}

int main() {
  int N, K;
  cin >> N >> K;

  vector< string > S(N);
  cin >> S;

  vector< bitset< 10001 > > reach(N + 1);
  reach.back().set(K);
  for(int i = N - 1; i >= 1; --i) {
    reach[i] = reach[i + 1] | (reach[i + 1] >> S[i].size());
  }

  bitset< 10001 > dp;
  dp[0] = true;

  string ans;
  for(int i = 0; i < N; ++i) {
    auto d = z_algorithm(S[i] + ans);
    string prefix;
    prefix.reserve(ans.size());
    for(int j = 0; j <= ans.size() && j + S[i].size() <= K; ++j) {
      int t = (j == ans.size() ? 0 : d[S[i].size() + j]);
      if(dp[j] && reach[i + 1][j + S[i].size()] && (j == ans.size() || (t < S[i].size() && ans[j + t] > S[i][t]))) {
        for(int l = j + t + 1; l <= ans.size(); ++l) dp[l] = false;
        ans = prefix + S[i];
        dp[j + S[i].size()] = true;
        break;
      }
      if(j < ans.size()) prefix.push_back(ans[j]);
    }
  }

  cout << ans << endl;
}

