void Zvalue(int len){
   z[0]=len;
   int l=0,r=0,x;
   for(int i=1;i<len;i++){
      if(r<i||z[i-l]>=r-i+1){
         r<i?x=i:x=r+1;
         while(x<len&&ss[x]==ss[x-i])  x++;
         z[i]=x-i;if(i<x){l=i;r=x-1;};
      }
      else
         z[i]=z[i-l];
   }
   z[len]=0;
}

