  int add(string& s) {
    int i = 0;
    rep(j,sz(s)) {
      if (c[i][s[j]-'a'] == -1) {
        c[i][s[j]-'a'] = p.size();
        p.push_back(i);
        c.push_back(vi(26,-1));
      }
      i = c[i][s[j]-'a'];
    }
    return i;
  }
  vi vk, vl; int k;
  void init() {
    vk = vl = vi(sz(p)); k = 0;
    dfs(0);
  }
  void dfs(int v) {
    vl[v] = k;
    rep(i,26) if (c[v][i] != -1) {
      dfs(c[v][i]);
    }
    vk[v] = k++;
  }
};
