		s.pb(readString());
		pos[i]=sum;
		for(auto c:s[i])
			cat[sum++]=c;
		cat[sum++]='a'-1;
	}
	auto sa=SA_IS::BuildSA(cat,sum+1);
	auto st=getST(sa.lcp,[&](int a,int b){return min(a,b);});
	auto lcp=[&](pi a,pi b){
		return st.get(sa.as[pos[a.fs]+a.sc],sa.as[pos[b.fs]+b.sc]);
	};
	auto cmp=[&](pi a,pi b){
		return sa.as[pos[a.fs]+a.sc]<sa.as[pos[b.fs]+b.sc];
	};

	dp[n][0]=1;
	per(i,n){
		rep(j,k+1){
			dp[i][j]=dp[i+1][j];
			if(j>=int(s[i].size()))
				dp[i][j]|=dp[i+1][j-s[i].size()];
		}
	}

	vi idx(n);
	iota(all(idx),0);
	sort(all(idx),[&](int a,int b){
		return sa.as[pos[a]]<sa.as[pos[b]];
	});

	V<pi> cur,nx;
	string ans;
	int mn=0;
	rep(i,k){
		nx.clear();
		auto push=[&](pi b){
			if(nx.size()){
				pi a=nx.back();
				int x=s[a.fs].size()-a.sc;
				int y=lcp(a,b);
				if(x>y)return;
				if(x==y&&x==int(s[b.fs].size()-b.sc)){
					chmin(nx.back(),b);
					return;
				}
			}
			nx.pb(b);
		};
		int p=0;
		for(auto j:idx)if(mn<=j&&i+int(s[j].size())<=k&&dp[j+1][k-i-s[j].size()]){
			while(p<int(cur.size())&&cmp(cur[p],pi(j,0)))
				push(cur[p++]);
			push(pi(j,0));
		}
		while(p<int(cur.size()))
			push(cur[p++]);
		cur.clear();
		ans+=s[nx[0].fs][nx[0].sc];
		mn=inf;
		for(auto w:nx){
			if(w.sc+1==int(s[w.fs].size())){
				mn=w.fs+1;
			}else{
				cur.eb(w.fs,w.sc+1);
			}
		}
	}

	cout<<ans<<endl;
}

