			if (R<=Len&&Hash[R]==(Hash[j]*Pow[len[i]]+HashS[len[i]])%MOD) continue;//completely the same
			while(L<R-1){
				int M=L+R>>1;
				if (R<=Len&&Hash[M]==(Hash[j]*Pow[M-j]+HashS[M-j])%MOD) L=M;
				else R=M;
			}
