template < typename T >

inline T read( T &x )
{

    x = 0 ;

    int f = 0 ;

    char ch = getchar() ;

    while( ch < '0' || ch > '9' )  {

        f |= ( ch == '-' ) , ch = getchar() ;

    }

    while( ch >= '0' && ch <= '9' )  {

        x = ( x << 1 ) + ( x << 3 ) + ch - '0' , ch = getchar() ;

    }

    return x = f ? -x:x ;

}
//

LL vec_pass( LL n , vector<LL>v )
{

    LL val = 0 ;

    for( auto i = v.begin() ; i != v.end() ; i++ )  {

        val += ( n % (*i) ) ;  

    }

    return val ;

}

