	if (s[p1]<s[p2]) return 0;
	// in case left is a prefix of right
	ll POW=Pow[p1-p2],HashBound1=HashS[p1-1],HashBound2=HashS[p2-1];
	if (SUB(HashS[p1+R],HashBound1)==SUB(HashS[p2+R],HashBound2)*POW%MOD) return 1;
	// L:must same; R:must diff
	while(L<R-1){
		int M=L+R>>1;
		if (SUB(HashS[p1+M],HashBound1)==SUB(HashS[p2+M],HashBound2)*POW%MOD) L=M;
		else R=M;
	}
	if (s[p1+R]<s[p2+R]) return 0;
	else return 1;
}
int main(){
	ios::sync_with_stdio(false);
	Pow[0]=1;
	for (int i=1;i<10005;++i) Pow[i]=Pow[i-1]*H%MOD;
	cin>>n>>k;
	for (int i=1;i<=n;++i) cin>>S[i],len[i]=S[i].size();
	can[n][k]=1;
	for (int i=n;i>=1;--i) can[i-1]=can[i]|(can[i]>>len[i]);
	term[0]=1;Len=0;
	for (int i=1;i<=n;++i){
		if (len[i]>k) continue;
		for (int j=1;j<=len[i];++j) s[j]=S[i][j-1];
		for (int j=1;j<=len[i];++j) HashS[j]=(HashS[j-1]+s[j])*H%MOD;
		int bestPos=k+1,bestInsert;
		vector<int> PossibleTerm;
		for (int j=0;j+len[i]<=k&&j<=Len;++j){
			if (!term[j]||!can[i][j+len[i]]) continue;
			if (j>=bestPos) break;
			if (j==Len){// last chance: directly add this string
				if (bestPos>Len+1||bestPos==Len+1&&compareUpdates(bestPos-bestInsert,1,len[i])) bestPos=j+1,bestInsert=j;
				break;
			}
			int L=j,R=j+len[i];//L:must same;  R:must diff
			if (R<=Len&&Hash[R]==(Hash[j]*Pow[len[i]]+HashS[len[i]])%MOD){//completely the same, but possible termination
				PossibleTerm.pb(R);continue;
			} 
			while(L<R-1&&L<bestPos){
				int M=L+R>>1;
				if (M<=Len&&Hash[M]==(Hash[j]*Pow[M-j]+HashS[M-j])%MOD) L=M;
				else R=M;
			}
			if (R>bestPos) continue;
			if (R>Len){//the original is a prefix
				// you may add this string as answer won't get worse
				if (bestPos>R||bestPos==R&&compareUpdates(bestPos-bestInsert,R-j,len[i])) bestPos=R,bestInsert=j;
				continue;
			}
			int oldchar,curchar=s[R-j];
			for (int ch='a';ch<='z';++ch) if (Hash[R]==(Hash[L]+ch)*H%MOD) oldchar=ch;
			if(curchar<oldchar) if(bestPos>R||bestPos==R&&compareUpdates(bestPos-bestInsert,R-j,len[i])) bestPos=R,bestInsert=j;
		}
		if (bestPos<=k){// valid update
			for (int p=bestInsert+1;p<=bestInsert+len[i];++p) Hash[p]=(Hash[p-1]+s[p-bestInsert])*H%MOD;
			for (int p=bestInsert+1;p<=k;++p) term[p]=path[p]=0;
			term[Len=bestInsert+len[i]]=1;
			path[Len]=i;
		}
		for (int j=0;j<PossibleTerm.size();++j) if (!term[PossibleTerm[j]]) term[PossibleTerm[j]]=1,path[PossibleTerm[j]]=i;
	}
	printAns(k);
	cout<<endl;
	return 0; 
}

