mt19937 rng(seq);
struct hash_struct {
    struct hash_parameters {
        const uint64_t M, X;
        const function<uint64_t(uint64_t, uint64_t)> add, sub, mul;
        vector<uint64_t> mpow;
        void resize(int n) {
            if(mpow.size() < n) {
                mpow.resize(n);
                for(int i = 0; i < n; i++) {
                    mpow[i] = i ? mul(mpow[i - 1], X) : 1;
                }
            }
        }
    };
    hash_parameters& h;
    vector<uint64_t> rolling;
    hash_struct(hash_parameters& h, const string& s)
    : h(h), rolling(s.size() + 1) {
        h.resize(s.size() + 1);
        for(int i = int(s.size()) - 1; i >= 0; i--) {
            rolling[i] = h.add(h.mul(rolling[i + 1], h.X), s[i]);
        }
    }
    uint64_t query(int L, int R) {
        assert(L <= R);
        return h.sub(rolling[L], h.mul(rolling[R], h.mpow[R - L]));
    }
};
hash_struct hash1(const string& s) {
    constexpr uint64_t M = (1ull << 61) - 1;
    static uint64_t X = uniform_int_distribution<uint64_t>(256, M - 1)(rng);
    static constexpr auto add = [](uint64_t a, uint64_t b) { return a + b >= M ? a + b - M : a + b; };
    static constexpr auto sub = [](uint64_t a, uint64_t b) { return add(a, M - b); };
    static constexpr auto mul = [](uint64_t a, uint64_t b) {
        uint64_t l1 = (uint32_t)a, h1 = a >> 32, l2 = (uint32_t)b, h2 = b >> 32;
        uint64_t l = l1 * l2, m = l1 * h2 + l2 * h1, h = h1 * h2;
        uint64_t ret = (l & M) + (l >> 61) + (h << 3) + (m >> 29) + (m << 35 >> 3) + 1;
        ret = (ret & M) + (ret >> 61);
        ret = (ret & M) + (ret >> 61);
        return ret - 1;
    };
    static hash_struct::hash_parameters h = {M, X, add, sub, mul};
    return hash_struct(h, s);
}
hash_struct hash2(const string& s) {
    constexpr uint64_t M = (1ull << 31) - 1;
    static uint64_t X = uniform_int_distribution<uint64_t>(256, M - 1)(rng);
    static constexpr auto add = [](uint64_t a, uint64_t b) { return a + b >= M ? a + b - M : a + b; };
    static constexpr auto sub = [](uint64_t a, uint64_t b) { return add(a, M - b); };
    static constexpr auto mul = [](uint64_t a, uint64_t b) {
        uint64_t ret = a * b + 1;
        ret = (ret & M) + (ret >> 31);
        ret = (ret & M) + (ret >> 31);
        return ret - 1;
    };
    static hash_struct::hash_parameters h = {M, X, add, sub, mul};
    return hash_struct(h, s);
}
template <typename T> T bsearch(T L, T R, const function<bool(T)>& can, bool left_feasible = true) {
    T& feasible = left_feasible ? L : R;
    T& infeasible = left_feasible ? R : L;
    while(R - L > 1) {
        T M = L + (R - L) / 2;
        (can(M) ? feasible : infeasible) = M;
    }
    return feasible;
}
const int PREFIX = 0, SUFFIX = 1, LEX_SMALLER = 2, LEX_LARGER = 3;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    vector<string> s(n);
    cin >> s;
    vector<vector<bool>> can(n + 1, vector<bool>(k + 1));
    for(int i = n; i >= 0; i--) {
        for(int j = 0; j <= k; j++) {
            if(i == n) {
                can[i][j] = j == 0;
            } else {
                can[i][j] = can[i + 1][j] or (s[i].size() <= j and can[i + 1][j - s[i].size()]);
            }
        }
    }
    vector<hash_struct> h1, h1_ans;
    for(auto& ss : s) {
        h1.push_back(hash1(ss));
    }
    string ans = "";
    h1_ans.push_back(hash1(ans));
    auto check = [&](int pos, int i) {
        if(pos == ans.size()) {
            return LEX_SMALLER;
        } else {
            int lcp_sz = bsearch<int>(0, min(s[i].size(), ans.size() - pos) + 1, [&](int k) {
                return h1[i].query(0, k) == h1_ans.back().query(pos, pos + k);
            });
            if(pos + lcp_sz == ans.size()) {
                return SUFFIX;
            } else if(lcp_sz == s[i].size()) {
                return PREFIX;
            } else {
                return s[i][lcp_sz] < ans[pos + lcp_sz] ? LEX_SMALLER : LEX_LARGER;
            }
        }
    };
    vector<int> insertable = {0};
    for(int i = 0; i < n; i++) {
        vector<int> new_insertable;
        for(int j : insertable) {
            new_insertable.push_back(j);
            if(j + s[i].size() <= k and can[i + 1][k - (j + s[i].size())]) {
                int res = check(j, i);
                if(res == LEX_SMALLER or res == SUFFIX) {
                    ans = ans.substr(0, j) + s[i];
                    h1_ans.push_back(hash1(ans));
                    new_insertable.push_back(j + s[i].size());
                    if(res == LEX_SMALLER) break;
                } else if(res == PREFIX) {
                    new_insertable.push_back(j + s[i].size());
                }
            }
        }
        insertable = new_insertable;
    }
    cout << ans << endl;
    return 0;
}

