  for(int i=0;i<n;i++){
    if(can[i+1][k-len[i]]) loc[q][cnt++] = start[i];
  }
  string ans = "";


  for(int eee = 0; eee < k; eee++){
    int mn = 1e9;
    for(int i=0;i<cnt;i++){
