    int mnn = 1e9;
    int ncnt = 0;
    for(int i=0;i<cnt;i++){
      int x = loc[q][i];
      if(ss[x] != mn) continue;
      if(critical[x+1] != -1){
	mnn = min(mnn, critical[x+1]);
      }
      else{
	loc[q ^ 1][ncnt++] = x + 1;
      }
    }
    if(mnn != 1e9){
      for(int i = mnn; i < n; i++){
	if(k-eee-1-len[i]>=0 && can[i+1][k-eee-1-len[i]]) loc[q ^ 1][ncnt++] = start[i];
      }
    }

    q ^= 1;
    cnt = ncnt;
  }
  cout << ans << "\n";
}

