int cmp(node u,node v){
	if (!u.y && !v.y) return 0;
	if (!u.y) return -cmp(v,u);
	if (!v.y){
		if (v.x<=u.x) return 0;
		int t=f[u.x+u.y+1]; //if(u.x+u.y+1 == 1) while(1);
		if (u.x+t>=v.x) return 0; else
		return s1[t+1]<s1[u.x+u.y+t+1]?-1:1;
	}
	if (u.x==v.x) return 0;
	if (u.x>v.x) return -cmp(v,u);
	int t=f[u.x+u.y+1]; //if(u.x+u.y+1 == 1) while(1);
	if (u.x+t>=v.x){
		t=v.x-u.x;
		if (f[t+1]>=u.y-t) return 0; //if(t+1 == 1) while(1);
		else return s1[f[t+1]+t+1]<s1[f[t+1]+1]?-1:1;
	} else return s1[t+1]<s1[u.x+u.y+t+1]?-1:1;
}
bool operator < (const node &x, const node &y) { return cmp(x, y) < 0; }
bool operator == (const node &x, const node &y) { return !cmp(x, y); }
int main() {
	scanf("%d%d", &n, &m);//a[i]是第i个串的长度
	rep(i, 1, n) { scanf("%s", s[i]+1); a[i] = strlen(s[i]+1); }
	fl[n+1][0] = 1;//fl[i][j]表示i到n的串中是否能拼出长度为j的串
	per(i, n, 1) rep(j, 0, m) {
		fl[i][j] = fl[i+1][j];//不选第i个串
		if(j >= a[i]) fl[i][j] |= fl[i+1][j-a[i]];//选第i个串
	}
	//rep(i, 1, n) rep(j, 0, m) printf("%d %d: %d\n", i, j, fl[i][j]);
	//ch保存目前为止【不考虑长度的字典序最小】且【最长】的串，并且之后是能拼出长度m的串的
	//ok[i]=1表示这是一个断点，len保存长度
	len = 0; ok[0] = 1;
	rep(i, 1, n) {// printf("%d\n", len);
		if(!len) {
			if(fl[i+1][m-a[i]]) rep(j, 1, a[i]) ch[++len] = s[i][j];
			ok[len] = 1; continue;
		}
		//将当前串s[i]和目前最优串ch拼起来，exkmp预处理出任意一个后缀与该串的lcp，用f保存
		tot = 0;
		rep(j, 1, a[i]) s1[++tot] = s[i][j];//s1保存拼接后的串
		rep(j, 1, len) s1[++tot] = ch[j];
		exkmp(s1, tot);
		memset(vis, 0, sizeof vis);
		rep(j, 0, m) if(fl[i+1][m-j]) {//枚举前i个串能拼成的合法长度
			if(ok[j]) { vis[j] = 1; b[j] = node(j, 0); }
			if(j >= a[i] && ok[j-a[i]]) {
				if(vis[j]) b[j] = min(b[j], node(j-a[i], a[i]));
				else { vis[j] = 1; b[j] = node(j-a[i], a[i]); }
			}
		}
		q[1] = 0; tp = 1;
		rep(j, 1, m) if(vis[j]) {
			while(tp > 1 && b[j] < b[q[tp]]) tp--;
			if(b[j] == b[q[tp]]) q[++tp] = j;
		}//这里的'=='表示是一个真包含关系，都要保存下来，记录断点
		len = q[tp];
		if(b[len].y) rep(j, 1, a[i]) ch[b[len].x+j] = s[i][j];
		ch[len+1] = 0;
		memset(ok, 0, sizeof ok);
		while(tp) ok[q[tp--]] = 1;
	}//由于每次操作都保证了之后的串能拼出长度为m的，所以最后的答案长一定为m
	printf("%s\n", ch+1);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> P;
typedef bitset<20010> B;

string S;
int sa[1000010][20];
void sa_init(){
	if(true){
		vector<P> vec;
		for(int i = 0 ; i < S.size() ; i ++){
			vec.push_back(P(S[i],0));
		}
		sort(vec.begin(),vec.end());
		for(int i = 0 ; i < S.size() ; i ++){
			sa[i][0] = lower_bound(vec.begin(),vec.end(),P(S[i],0)) - vec.begin();
		}
	}
	for(int t = 1 ; t < 20 ; t ++){
		vector<P> vec;
		for(int i = 0 ; i < S.size() ; i ++){
			if(i+(1<<(t-1)) < S.size())vec.push_back(P(sa[i][t-1],sa[i+(1<<(t-1))][t-1]));
			else vec.push_back(P(sa[i][t-1],-1));
		}
		sort(vec.begin(),vec.end());
		for(int i = 0 ; i < S.size() ; i ++){
			if(i+(1<<(t-1)) < S.size()){
				sa[i][t] = lower_bound(vec.begin(),vec.end(),P(sa[i][t-1],sa[i+(1<<(t-1))][t-1]))-vec.begin();
			}
			else {
				sa[i][t] = lower_bound(vec.begin(),vec.end(),P(sa[i][t-1],-1)) - vec.begin();
			}
		}
	}
}

int comp(int x,int y,int len,int t){
	if(len == 0)return 0;
	if(len < (1<<t))return comp(x,y,len,t-1);
	if(sa[x][t] == sa[y][t])return comp(x+(1<<t),y+(1<<t),len-(1<<t),t-1);
	else {
		if(sa[x][t] < sa[y][t])return 1;
		else return -1;
	}
}

