		ok_r[i] = ok_r[i+1] | (ok_r[i+1]>>(s[i].size()));
	}
	for(int i = 1 ; i <= n ; i ++){
		ok[i] = ok_l[i] & ok_r[i];
	}

	string ret(k,'z'+1);
	B start[2];
	int t=0,t_=1;
	start[t].reset(); start[t][0] = true;
	int sum = 0;
	for(int i = 1 ; i <= n ; i ++){
		start[t_].reset(); start[t_][0] = true;
		deque<int> deq;
		for(int j = 1 ; j <= k ; j ++){
			if(start[t][j-1] && ok[i][j+s[i].size()-1]){
				while(deq.size()>0){
					int r = comp(sum,sum+j-deq.back(),s[i].size()-(j-deq.back()),20);
					if(r == -1)deq.pop_back();
					else if(r == 0){
						deq.push_back(j);
						break;
					}
					else break;
				}
				if(deq.size() == 0)deq.push_back(j);
			}
			if(deq.size() > 0){
				char c = s[i][j-deq.back()];
				if(ret[j-1] < c){
					deq.clear();
				}
				else if(ret[j-1] == c){}
				else {
					for(int x = 0 ; x < s[i].size() ; x ++){
						ret[deq.back()-1+x] = s[i][x];
					}
					ret[deq.back()-1+s[i].size()] = 'z'+1;
					while(deq.size()>0){
						start[t_][deq.back()+s[i].size()-1] = true;
						deq.pop_back();
					}
					break;
				}
				if(deq.front() == j-s[i].size()+1){
					start[t_][j] = true;
					deq.pop_front();
				}
			}
			if(start[t][j])start[t_][j] = true;
		}
		swap(t,t_);
