bool prefix(const string &a, const string &b){
	int m = min(a.size(), b.size());
	return a.substr(0, m) == b.substr(0, m);
}

int main(){
	cin.tie(0); cin.sync_with_stdio(0);
	int n, len; cin >> n >> len; assert(len < 10000);
	vector<string> s(n);
	rep(i, n) cin >> s[i];

	vector<vector<bool>> go(n + 1, vector<bool>(len + 1));
	vector<vector<bool>> come(n + 1, vector<bool>(len + 1));
	go[n][len] = come[0][0] = 1;
	for(int i = n - 1; i >= 0; i--){
		go[i] = go[i + 1];
		for(int j = len; j >= s[i].size(); j--) if(go[i + 1][j]) go[i][j - s[i].size()] = 1;
	}

	string best = "";
	rep(i, n){
		come[i + 1] = come[i];
		string next = best;
		for(int j = 0, lim = len - (int)s[i].size(); j <= lim; j++) if(come[i][j] && go[i + 1][j + s[i].size()]){

			bool pre = 1, sml = 0;
			int pos = 0;
			for(int k = 0; k < s[i].size() && j + k < next.size(); k++) if(s[i][k] != next[j + k]){
				pos = k;
				pre = 0;
				sml = s[i][k] > next[j + k];
				break;
			}

			if(pre){
				come[i + 1][j + s[i].size()] = 1;
				if(next.size() < j + s[i].size()){
					int x = j + s[i].size() - next.size();
					rep(k, x) next += s[i][s[i].size() - x + k];
				}
				continue;
			}

			if(sml) continue;
			if(!sml){
				for(int l = j + pos; l <= len; l++) come[i + 1][l] = 0;
				lim = min(lim, j + pos - 1);
				next.erase(next.begin() + j, next.end());
				next += s[i];
			}
			come[i + 1][j + s[i].size()] = 1;
		}
		best = next;
	}
	cout << best << endl;

	return 0;
}

