const int SIGMA = 26;

struct Node {
  Node *child[SIGMA];
  Node *fail;
  int len;
};

Node pool[N << 1], *last, *head, *tail;
int idx[N];
int f[20][N << 1], dep[N << 1];
vector<int> a[N << 1];

Node *new_node(int len) {
  Node *p = last++;
  p->len = len;
  fill(p->child, p->child + SIGMA, (Node *)nullptr);
  p->fail = nullptr;
  return p;
}

void add(int c, int len) {
  Node *p = tail, *np = new_node(len);
  idx[len - 1] = np - pool;
  tail = np;
  for (; p && !p->child[c]; p = p->fail) {
    p->child[c] = np;
  }
  if (!p) {
    np->fail = head;
  } else {
    Node *q = p->child[c];
    if (q->len == p->len + 1) {
      np->fail = q;
    } else {
      Node *r = last++;
      *r = *q;
      r->len = p->len + 1;
      np->fail = q->fail = r;
      for (; p && p->child[c] == q; p = p->fail) {
        p->child[c] = r;
      }
    }
  }
}

void DFS(int u, int parent) {
  f[0][u] = parent;
  for (int k = 1; k < 20; ++k) {
    f[k][u] = f[k - 1] < 0 ? -1 : f[k - 1][f[k - 1][u]];
  }
  dep[u] = parent < 0 ? 0 : dep[parent] + 1;
  for (auto& v : a[u]) {
    DFS(v, u);
  }
}

int LCA(int x, int y) {
  if (dep[x] > dep[y]) swap(x, y);
  for (int delta = dep[y] - dep[x], k = 0; k < 20; ++k) {
    if (delta & (1 << k)) {
      y = f[k][y];
    }
  }
  for (int k = 19; k >= 0; --k) {
    if (f[k][x] != f[k][y]) {
      x = f[k][x];
      y = f[k][y];
    }
  }
  return x == y ? x : f[0][x];
}

bool smaller(const vector<int>& a, const vector<int>& b) {
  int offset_a = 0, offset_b = 0;
  // trace(a, b);
  for (int i = 0, j = 0; i < a.size() && j < b.size(); ) {
    // trace(i, j, offset_a, offset_b);
    int u = a[i], v = b[j], bound = min(len[u] - offset_a, len[v] - offset_b);
    // trace(sum[u], sum[v]);
    int x = idx[sum[u] + len[u] - 1 - offset_a],
      y = idx[sum[v] + len[v] - 1 - offset_b];
    // trace(u, v, x, y);
    int w = LCA(x, y);
    int lcp = min(pool[w].len, bound);
    if (lcp < bound) {
      return s[u][offset_a + lcp] < s[v][offset_b + lcp];
    }
    offset_a += lcp;
    offset_b += lcp;
    if (offset_a == len[u]) {
      ++i;
      offset_a = 0;
    }
    if (offset_b == len[v]) {
      ++j;
      offset_b = 0;
    }
  }
  return false;
}

int main() {
  int n, k;
  scanf("%d%d", &n, &k);
  last = pool;
  head = new_node(0), tail = head;
  int m = 0;
  for (int i = 0; i < n; ++i) {
    scanf("%s", s[i]);
    len[i] = strlen(s[i]);
    for (int j = len[i] - 1; j >= 0; --j) {
      add(s[i][j] - 'a', ++m);
    }
    sum[i + 1] = sum[i] + len[i];
  }
  for (Node* p = pool + 1; p != last; ++p) {
    int x = p->fail - pool, y = p - pool;
    a[x].push_back(y);
  }
  DFS(0, -1);

  m = 0;
  for (int i = 0; i < n; ++i) {
    m = min(m + len[i], k);
    for (int j = m; j >= len[i]; --j) {
      if (j - len[i] > 0 && dp[j - len[i]].empty()) continue;
      auto cur = dp[j - len[i]];
      cur.push_back(i);
      if (dp[j].empty() || smaller(cur, dp[j])) {
        dp[j] = move(cur);
      }
    }
    // for (int j = 0; j <= m; ++j) {
    //   trace(j, dp[j]);
    // }
  }
  for (auto& it : dp[k]) {
    printf("%s", s[it]);
  }
  puts("");
  return 0;
}

