        int S = in[i].size();

        // find first proper index
        int f = -1;
        for(int j=0;j<ans.size();j++) if(j+S<=K && dp[(i+1)%2][j] && ok[i][j+S]){
            if(z[S+1+j] < min(S, (int)ans.size() - j)){
                if(ans[j+z[S+1+j]] > in[i][z[S+1+j]]){
                    f = j;
                    break;
                }
            }
        }

        if(f>=0){
            // slice

            ans = ans.substr(0,f);
            ans += in[i];
            for(int j=0;j<=ans.size()-S;j++) if(dp[(i+1)%2][j])
                dp[i%2][j] = true;
            dp[i%2][ans.size()] = true;
            continue;
        }

        // append.
        dp[i%2][ans.size()] = true;
        for(int j=0;j<ans.size();j++) if(dp[(i+1)%2][j]){
            dp[i%2][j] = true;
