vector<int>Z_algorithm(const string& s) {
	int c = 0, n = s.size();
	vector<int>ret(n, 0);
	for (int i = 1; i < n; i++) {
		int l = i - c;
		if (i + ret[l] < c + ret[c]) {
			ret[i] = ret[l];
		}
		else {
			int j = max(0, c + ret[c] - i);
			while (i + j < n&&s[j] == s[i + j]) {
				j++;
			}
			ret[i] = j;
			c = i;
		}
	}
	ret[0] = n;
	return ret;
}

