    if (rest < 0) return false;
    if (idx >= s.size()) return false;
    if (m1[idx][rest]) return m2[idx][rest];
    bool res = can_make(idx+1, rest-s[idx].size()) || can_make(idx+1, rest);
    return m1[idx][rest] = true, m2[idx][rest] = res;
}

