using namespace std;

int valid[2000][10001];
int Z[20000];

void makeValid(const vector<string>& vs, int K){
	memset(valid, 0, sizeof(valid));
	int N = vs.size();
	valid[N-1][K] = 1;
	for(int i=N-2;i>=0;i--){
		for(int j=0;j<=K;j++){
			int p = j + vs[i+1].size();
			valid[i][j] = (valid[i+1][j] || (p <= K && valid[i+1][p]));
		}
	}
}

void makeZ(const string& S){
	Z[0] = S.size();
	int j=0, k=1;
	for(int i=1;i<S.size();i+=k,j=max(0,j-k)){
		while(i+j < S.size() && S[j] == S[i+j]) ++j;
		Z[i] = j;
		for(k=1;i+k < S.size() && k+Z[k] < j;k++) Z[i+k] = Z[k];
	}
}

int main(){
	int N, K;
	int use[2][10001];
	while(cin >> N >> K){
		vector<string> S(N);
		for(int i=0;i<N;i++) cin >> S[i];
		makeValid(S, K);
		memset(use, 0, sizeof(use));
		use[0][0] = 1;
		string best = "";
		for(int i=0;i<N;i++){
			int cur = i%2;
			int next = 1-cur;
			memset(use[next], 0, sizeof(use[next]));
			makeZ(S[i] + best);
			// cout << S[i] + best << endl;
			// for(int j=0;j<S[i].size()+best.size();j++) cout << Z[j] << " "; cout << endl;
			int joinPos = -1;
			vector<int> useNext;
			for(int j=0;j<=K;j++){
				if(!use[cur][j]) continue;
				if(valid[i][j]) use[next][j] = 1;
				int p = j + S[i].size();
				if(!(p <= K && valid[i][p])) continue;
				int check = (j < best.size() ? Z[S[i].size() + j] : 0);
				if(check >= S[i].size()){
					use[next][p] = 1;
				} else if(j+check >= best.size()){
					if(joinPos == -1){
						joinPos = j;
						useNext.push_back(p);
					} else {
						int offset = j - joinPos;
						int t = Z[offset];
						if(t+offset == S[i].size() || S[i][t] < S[i][t+offset]){
							joinPos = j;
							if(S[i][t] < S[i][t+offset]) useNext.clear();
							useNext.push_back(p);
						}
					}
					// if(joinPos == j) use[next][p] = 1;
				} else if(S[i][check] < best[j+check]){
					use[next][p] = 1;
					best = best.substr(0, j) + S[i];
					useNext.clear();
					break;
				}
			}
			for(int j=0;j<useNext.size();j++) use[next][useNext[j]] = 1;
			if(joinPos != -1) best = best.substr(0, joinPos) + S[i];
			// cout << i << " " << best << endl;
			// for(int j=0;j<=K;j++) cout << use[next][j] << " "; cout << endl;
		}
		cout << best << endl;
	}
}

