            cur -= str[fh[lenpos[cur]]].size();
         }
         si = '0'+si;
         bool flag = false;
         bool fail = false;
         for(int j = 1;j <= i; ++j){
            if(si[j] < minch[j]){
               flag = true;
               minch[j] = si[j];
            }
            else if(!flag && minch[j] < si[j]){
               fail = true; break;
            }
            if(flag)minch[j] = si[j];
         }
         if(fail){
            lenpos[i] = 0;continue ;
         }
      }
      for(int j = 1;j <= n; ++j){
         if(pos[j] <= lenpos[i])continue ;
         if(i+(int)str[j].size() > k)continue ;
         if(!lenbag[j+1][k-i-(int)str[j].size()])continue ;
         int lenp = i+str[j].size();
         if(!lenpos[lenp])lenpos[lenp] = pos[j];
         else {
            if(lcp(lenpos[lenp]-(int)str[j].size()+1,
                     pos[j]-(int)str[j].size()+1) == str[j].size()){
               lenpos[lenp] = min(lenpos[lenp],pos[j]);
            } else if(rk[lenpos[lenp]-str[j].size()+1] > rk[pos[j]-str[j].size()+1]){
               lenpos[lenp] = pos[j];
            }
         }
      }
   }
   string ret;
   int cur = k;
   while(cur){
      ret = str[fh[lenpos[cur]]] + ret;
      cur = cur-str[fh[lenpos[cur]]].size();
   }
   cout << ret << endl;
   return 0;
}

#include<string>
#include<vector>
std::vector<int> z_algorithm(const std::string& S) {
  std::vector<int> Z(S.size(), S.size());
  for(int i = 1, L = 0, R = 0; i < S.size(); ++i) {
    if(i > R) {
      L = R = i;
      while(R < S.size() && S[R - L] == S[R]) ++R;
      Z[i] = R-- - L;
    } else {
      if(Z[i - L] < R - i + 1) Z[i] = Z[i - L];
      else {
        L = i;
        while(R < S.size() && S[R - L] == S[R]) ++R;
        Z[i] = R-- - L;
      }
    }
  }
  return Z;
}

#include<bits/stdc++.h>
using namespace std;

bool update(const auto& S, const auto& CS, const auto& Z, int j, int best) {
  if(CS.empty()) return true;
  if(best == -1) {
    // CS <=> CS[0...j] + S
    if(j == CS.size()) return true;                       // CS[0...j] + S = CS + S
    auto z = Z[S.size() + j];
    if(z == S.size() && j + z == CS.size()) return true;  // CS = CS[0...j] + S
    if(z >= S.size()) return true;                        // CS > CS[0...j] + S
    if(j + z >= CS.size()) return false;                  // CS < CS[0...j] + S
    if(CS[j + z] < S[z]) return false;                    // CS < CS[0...j] + S
    return true;                                          // CS > CS[0...j] + S
  } else {
    // CS[0...best] + S <=> CS[0...j] + S
    if(j == best) return true;
    if(j < best) {
      auto z = Z[S.size() + j];
      // CS[0...best] と CS[0...j] + S との比較
      if(j + z < best) {
        if(z >= S.size())    return true;
        if(CS[j + z] < S[z]) return false;
        else                 return true;
      }
      // CS[0...best] + S の S 上の要素と, CS[0...j] + S の S の上の要素とを比較
      if(j + z < best + S.size()) {
        auto d = best - j;
        z = Z[d];
        if(S[z] < S[d + z]) return false;
        else                return true;
      }
      // CS[0...best] + S = CS[0...j] + S
      return true;
    } else {
      auto z = Z[S.size() + best];
      // CS[0...best] + S と CS[0...j] との比較
      if(best + z < j) {
        if(z >= S.size())       return true;
        if(S[z] < CS[best + z]) return false;
        else                    return true;
      }
      // CS[0...best] + S の S 上の要素と, CS[0...j] + S の S の上の要素とを比較
      if(best + z < j + S.size()) {
        auto d = j - best;
        z = Z[d];
        if(S[d + z] < S[d]) return false;
        else                return true;
      }
      // CS[0...best] + S = CS[0...j] + S
      return true;
    }
  }
}

int main() {
  int N, K;
  cin >> N >> K;
  vector<string> S(N);
  for(auto& i: S) cin >> i;

  vector<vector<bool>> reach(N + 1, vector<bool>(K + 1));
  reach[N][0] = true;
  for(int i = N - 1; 0 <= i; --i) {
    reach[i] = reach[i + 1];
    for(int j = K; S[i].size() <= j; --j) reach[i][j] = reach[i][j] | reach[i][j - S[i].size()];
  }

  vector<string> CS(N + 1);
  vector<vector<bool>> dp(N + 1, vector<bool>(K + 1));
  dp[0][0] = true;
  for(int i = 0; i < N; ++i) {
//     cout<<"CS: "<<CS[i]<<endl;
//     cout<<"dp:";for(auto k:dp[i])cout<<" "<<k;cout<<endl;
//     cout<<"nx:";for(auto k:reach[i+1])cout<<" "<<k;cout<<endl;
    auto Z = z_algorithm(S[i] + CS[i]);
    int best = -1;
    CS[i + 1] = CS[i];
    for(int j = 0; j <= K - S[i].size(); ++j) {
      if(!dp[i][j]) continue;
      if(!reach[i + 1][K - j - S[i].size()]) continue;
      if(!update(S[i], CS[i], Z, j, best)) continue;
      best = j;
    }
    if(best != -1) {
      auto s = CS[i].substr(0, best) + S[i];
      if(s + "~" < CS[i + 1] + "~") CS[i + 1] = s;
    }

    int dif = 0;
    while(dif < CS[i].size() && dif < CS[i + 1].size() && CS[i][dif] == CS[i + 1][dif]) ++dif;
    for(int j = 0; j <= K; ++j) {
      if(!dp[i][j]) continue;
      if(best == -1) {
        if(!reach[i + 1][K - j]) continue;
        dp[i + 1][j] = true;
      } else {
        if(j < dif || update(S[i], CS[i], Z, j, best)) if(reach[i + 1][K - j]) dp[i + 1][j] = true;
        if(K < j + S[i].size()) continue;
        if(!reach[i + 1][K - j - S[i].size()]) continue;
        if(!update(S[i], CS[i], Z, j, best)) continue;
        dp[i + 1][j + S[i].size()] = true;
      }
    }
  }

  cout << CS[N] << endl;
}

