                        if (sumLen + curLen > k) continue;
                        if (can[i+1][k-sumLen-curLen] && ord[i] < minSelect)  
                                        minSelect = ord[i], minID = i;
                }
                if (minID == -1) assert(0);
                select.push_back(minID);
                sumLen += s[minID].fi.size();
                st = minID+1;
                if (sumLen == k) break;
        }
        for (auto &x : select) cout << s[x].fi; cout << endl;
        return 0;
}

