int gethash(int h[],int l,int r)
{
	if(r==0) return 0;
	return ((h[r-1]-1LL*(l?h[l-1]:0)*e[r-l]%mod)+mod)%mod;
}

void init(string &c,int h[])
{
	int len=c.size();
	h[0]=c[0];
