vector<int> Zalgorithm(string s) {
  vector<int> res(s.size());
  res[0] = s.size();
  int i = 1, j = 0;
  while (i < s.size()) {
    while (i + j < s.size() && s[j] == s[i + j]) ++j;
    res[i] = j;
    if (j == 0) {
      ++i;
      continue;
    }
    int k = 1;
    while (i + k < s.size() && k + res[k] < j) res[i + k] = res[k], ++k;
    i += k;
    j -= k;
  }

  return res;
}

signed main(int argc, char *argv[]) {
  int n = in(), k = in();
  vector<string> s(n + 1);
  for (int i = 1; i <= n; ++i) {
    cin >> s[i];
  }

  vector<bitset<10101>> reach(n + 1);
  reach.back().set(k);
  for (int i = n; i >= 1; --i) {
    reach[i - 1] = reach[i] | (reach[i] >> s[i].size());
  }

  auto dp = make_v(n + 1, k + 10000, 0);
  dp[0][0] = 1;

  string ans;
  for (int i = 1; i <= n; ++i) {
    dp[i] = dp[i - 1];

    vector<int> d = Zalgorithm(s[i] + ans);
    for (int j = 0; j <= ans.size() && j + s[i].size() <= k; ++j) {
      int t = d[s[i].size() + j];

      if (dp[i][j] && reach[i][j + s[i].size()] && (j == ans.size() || (t < s[i].size()) && (ans[j + t] > s[i][t]))) {
        ans = ans.substr(0, j) + s[i];
        for (int l = j + t + 1; l <= k; ++l) dp[i][l] = 0;
        dp[i][j + s[i].size()] = 1;
        break;
      }
    }
  }

  cout << ans << endl;
}

