const int maxn = 2e3 + 100, maxk = 1e4 + 10;
const ll inf = 2e18, mod = 1e9 + 7;

int n, k;
bool dp[maxn][maxk];
string s[maxn], ans;
vector<pair<int, int> > pool;
vector<int> delQ;

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> k;
	for (int i = 0; i < n; i++)
		cin >> s[i];
	dp[n][0] = true;
	for (int i = n - 1; i >= 0; i--)
	{
		dp[i][s[i].size()] = true;
		for (int j = 0; j <= k - s[i].size(); j++)
			dp[i][j + s[i].size()] |= dp[i + 1][j];
	}

	for (int i = 0; i < n; i++)
		if (dp[i][k])
			pool.pb(mp(i, 0));

	for (int len = 0; len < k; len++)
	{
		char c = 'z';
		for (pair<int, int> i : pool)
			c = min(c, s[i.ff][i.ss]);

		for (int i = pool.size() - 1; i >= 0; i--)
			if (s[pool[i].ff][pool[i].ss] != c)
				delQ.pb(i);
		for (int ind : delQ)
		{
			swap(pool[ind], pool[pool.size() - 1]);
			pool.popb();
		}
		delQ.clear();

		for (int i = pool.size() - 1; i >= 0; i--)
		{
			pool[i].ss++;
			if (pool[i].ss == s[pool[i].ff].size())
				delQ.pb(i);
		}
		for (int pos : delQ)
		{
			for (int i = pos + 1; i < n; i++)
				if (dp[i][k - len - 1])
					pool.pb(mp(i, 0));
			swap(pool[pos], pool[pool.size() - 1]);
			pool.popb();
		}
		delQ.clear();
		ans += c;
	}
	cout << ans << endl;
}

