    v_bool ok(K + 1, false);
    ok[0] = true;
    REP(i, N){
        vec z = z_algorithm(s[i] + '@' + T);
        v_Pii p;
        int n = SZ(s[i]), m = SZ(T);

        REP(k, K + 1) if(dp[i + 1][k]){
            if(ok[k]){
                if(SZ(p) == 0) p.pb(Pii(k, 0));
                else{
                    if(p.back().se == 0) p.pb(Pii(k, 0));
                    else{
                        int u = p.back().fi - n;
                        int c = z[n + 1 + u];
                        if(c == n) p.pb(Pii(k, 0));
                        else if(T[u + c] < s[i][c]) p = v_Pii({Pii(k, 0)});
                    }
                }
            }
            if(k - n >= 0 && ok[k - n]){
                if(SZ(p) == 0) p.pb(Pii(k, 1));
                else{
                    if(p.back().se == 0){
                        int u = k - n;
                        int c = z[n + 1 + u];
                        if(u + c >= p.back().fi) p.pb(Pii(k, 1));
                        else if(s[i][c] < T[u + c]) p = v_Pii({Pii(k, 1)});
                    }else{
                        int u = p.back().fi - n;
                        int c = z[n + 1 + u];
