        for(Pii q: p) ok[q.fi] = true;
        Pii q = p.back();
        if(q.se == 0) T = T.substr(0, q.fi);
        else T = T.substr(0, q.fi - n) + s[i];
    }
    Out(T);

    return 0;
}

