void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>K;
	FOR(i,N) cin>>S[i];

	can[N][K]=1;
	for(i=N-1;i>=1;i--) {
		for(j=0;j<=K;j++) {
			can[i][j] |= can[i+1][j];
			if(j>=S[i].size()) can[i][j-S[i].size()] |= can[i+1][j];
		}
	}
	can[0][0]=1;

	FOR(i,N) {
		string T=S[i]+CS[i];
		vector<int> Z=Zalgo(T);
		int cand=-1;

		/*
		for(j=0;j<=K;j++) {
			if(can[i][j] && j+S[i].size()<=K && can[i+1][j+S[i].size()]) cur=getmin(T,S[i].size(),CS[i].size(),T,Z,cur,{j,0});
			if(can[i][j] && can[i+1][j]) cur=getmin(T,S[i].size(),CS[i].size(),T,Z,cur,{j,1});
		}
		*/
		for(j=0;j+S[i].size()<=K;j++) if(can[i][j] && can[i+1][j+S[i].size()]) {
			string tmp=CS[i].substr(0,j)+S[i];
			//cout<<i<<j<<tmp<<endl;
			if(tmp<CS[i+1] || (CS[i+1].size()<tmp.size() && tmp.substr(0,CS[i+1].size())==CS[i+1])) {
				cand=j;
				CS[i+1]=tmp;
			}
		}

		if(cand!=-1) {
			CS[i+1]=CS[i].substr(0,cand)+S[i];
			if(CS[i]<CS[i+1] && !(CS[i].size()<=CS[i+1].size() && CS[i]==CS[i+1].substr(0,CS[i].size()))) cand=-1;
		}

		if(cand==-1) {
			assert(0);
			CS[i+1]=CS[i];
			FOR(j,K+1) can[i+1][j] &= can[i][j];
		}
		else {
			FOR(j,K+1) {
				if(j>CS[i+1].size()) can[i+1][j]=0;
				if(j<CS[i+1].size() && can[i+1][j]) {
					/*
					if(j>=S[i].size() && can[i][j-S[i].size()] && j-S[i].size()<=cand) continue;
					if(can[i][j] && j<=cand) continue;
					can[i+1][j]=0;
					*/
					string tt="{";
					if(can[i][j]) tt=CS[i].substr(0,j);
					if(j>=S[i].size() && can[i][j-S[i].size()]&&can[i+1][j]) tt=min(tt,CS[i].substr(0,j-S[i].size())+S[i]);
					if(tt>=CS[i+1]) can[i+1][j]=0;
				}
			}
		}
		//FOR(j,K+1) _P("%d",can[i+1][j]);
		//_P(" : %s\n",CS[i+1].c_str());


	}

	cout<<CS[N]<<endl;
}


