#include<bits/stdc++.h>

using namespace std;

const int MAXN = 2005;
const int MAXK = 10005;

int n, k, br;
string s[MAXN], curr;
int p[MAXK], r[MAXN];
bool dp[MAXN][MAXK], ok[MAXK];

void precompute () {
    dp[n][0] = 1;
    for (int i = n-1; i >= 0; i--) {
        int len = s[i].size();
        for (int j = 0; j <= k; j++) {
            dp[i][j] = dp[i + 1][j];
            if (j - len >= 0) dp[i][j] |= dp[i][j - len];
        }
    }
}

void kmp (int ind) {
    int len = s[ind].size();
    p[0] = 0;
    for (int i=1; i<len; i++) {
        p[i] = p[i-1];
        while (p[i] > 0) {
            if (s[ind][p[i]] == s[ind][i]) break;
            p[i] = p[p[i] - 1];
        }
        if (s[ind][p[i]] == s[ind][i]) p[i]++;
    }
    r[k] = 0;
    for (int i=k-1; i>=0; i--) {
        r[i] = r[i+1];
        while (r[i] > 0) {
            if (r[i] < len && s[ind][r[i]] == curr[i]) break;
            r[i] = p[r[i] - 1];
        }
        if (s[ind][r[i]] == curr[i]) r[i]++;
    }
}

void calc () {
    for (int i=0; i<k; i++) curr += '{';
    ok[0] = 1;
    for (int i=0; i<n; i++) {
        int len = s[i].size(), ind = -1;
        kmp(i);
        for (int j = 0; j + len <= k; j++) {
            if (!ok[j] || !dp[i+1][k - (j+len)]) continue;
            if (s[i][j + r[j]] < curr[j + r[j]]) {
                ind = j;
                break;
            }
        }
        if (ind == -1) continue;
        br = ind + len;
        for (int j=0; j<len; j++) {
            curr[ind + j] = s[i][j];
        }
        for (int j=br; j<k; j++) {
            curr[j] = '{';
        }
        ok[br] = 1;
        for (int j = br + 1; j <= k; j++) {
            ok[j] = 0;
        }
        //cout << curr << endl;
        //for (int j=0; j<=k; j++) cout << ok[j]; cout << endl;
    }
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    for (int i=0; i<n; i++) {
        cin >> s[i];
    }
    precompute();
    calc();
    cout << curr;
    return 0;
}

