#include <bits/stdc++.h>
const int maxn = 2007, maxk = int(1e4) + 7, inf = 0x3f3f3f3f;
char str[maxn][maxk], ans[maxk];
bool f[maxn][maxk];
int len_str[maxn], len_set, n, k;
struct { int index, pos; } set[2][maxn << 2];
int main() {
//    freopen("in.txt", "r", stdin);
    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; i++) {
        scanf("%s", str[i] + 1);
        len_str[i] = int(strlen(str[i] + 1));
    }
    f[n + 1][0] = true;
    for (int i = n, suf_sum = 0, upper; i >= 1; i--) {
        suf_sum += len_str[i], upper = std::min(suf_sum, k);
        for (int j = 0; j <= upper; j++) {
            f[i][j] = f[i + 1][j];
            if (j >= len_str[i]) f[i][j] |= f[i + 1][j - len_str[i]];
        }
    }
    for (int i = 1; i <= n; i++) if (f[i + 1][k - len_str[i]]) set[0][++len_set] = {i, 1};
    for (int i = 1, cur = 0, new_len_set, min_index; i <= k; i++) {
        char min_ch = 127;
        for (int j = 1, index, pos; j <= len_set; j++) {
            index = set[cur][j].index, pos = set[cur][j].pos;
            if (min_ch > str[index][pos]) min_ch = str[index][pos];
        }
        ans[i] = min_ch, new_len_set = 0, min_index = inf;
        for (int j = 1, index, pos; j <= len_set; j++) {
            index = set[cur][j].index, pos = set[cur][j].pos;
            if (str[index][pos] > min_ch) continue;
            if (pos < len_str[index]) set[cur ^ 1][++new_len_set] = {index, pos + 1};
            else if (index < min_index) min_index = index;
        }
        for (int j = min_index + 1; j <= n; j++) if (len_str[j] <= k - i && f[j + 1][k - i - len_str[j]])
            set[cur ^ 1][++new_len_set] = {j, 1};
        len_set = new_len_set, cur ^= 1;
    }
