	{
		for (int j = 0; j <= k; j++)
		{
			filler[i][j] |= filler[i + 1][j];
			if (j + s[i].size() <= k)
			{
				dp[i][j + s[i].size()] |= filler[i + 1][j];
				filler[i][j + s[i].size()] |= filler[i + 1][j];
			}
		}
	}

