int main(){
	cin >> n >> k;
	vector<int> awal[26];
	for(int i = 0; i < n; i++)
		cin >> ss[i];
	for(int i = 0; i < n; i++)
		awal[ss[i][0] - 'a'].pb(i);
	for(int now = n; now >= 0; now--){
		for(int panjang = 0; panjang <= k; panjang++){
			bool &ret = dp[now][panjang];
			if(now == n){
				ret = 0;
				if(panjang == 0)
					ret = 1;
				continue;
			}
			ret = 0;
			ret |= dp[(now + 1)][panjang];
			if(panjang - sz(ss[now]) >= 0){
				dp2[now][panjang] = dp[now + 1][panjang - sz(ss[now])];
				ret |= dp[(now + 1)][panjang - sz(ss[now])];
			}
		}
	}
	vector<pair<int, int>> ve;
	for(int i = 0; i <= k; i++)
		dimana[i] = 1e9;
	dimana[0] = -1;
	string ans = "";
	for(int i = 1; i <= k; i++){
		for(int x = 0; x < 26; x++){
			bool ada = false;
			char car = 'a' + x;
			for(int id : awal[x]){
				if(dp2[id][k - i + 1] && dimana[i - 1] < id){
					ve.pb({id, i});
					ada = true;
				}
			}
			for(auto it : ve){
				assert(i - it.s < sz(ss[it.f]));
				if(ss[it.f][i - it.s] == car){
					ada = true;
				}
			}
			if(!ada)
				continue;
			vector<pair<int, int>> baru;
			for(auto it : ve){
				if(ss[it.f][i - it.s] != car)
					continue;
				if(i - it.s + 1 == sz(ss[it.f])){
					dimana[i] = min(dimana[i], it.f);
					continue;
				}
				baru.pb(it);
			}
			ve = baru;
			ans += car;
			break;
		}
	}
	cout << ans << endl;
}

