void MAIN() {
    scanf("%d%d", &N, &K);
    REP (i, N) {
	scanf("%s", buf);
	S[i] = buf;
    }

    vis.set(K);
    for (int i=N; i--;) {
	REP (j, K-(int)S[i].size()+1) if (vis.test(j+S[i].size())) {
	    vis.set(j);
	    dp[i].set(j);
	}
    }

    REP (k, K+1) mi[k] = INF;
    mi[0] = 0;

    ans = string(K, '|');

    REP (k, K) {
	for (int i=mi[k]; i<N; i++) if (dp[i].test(k)) {
	    int p = -1;
