    scanf("%d%d",&n,&k);
    for (int i=1;i<=n;i++) scanf("%s",s[i]),len[i]=strlen(s[i]);
    dp[n+1][0]=1;
    for (int i=n;i>=1;i--) 
        dp[i]=dp[i+1]|(dp[i+1]<<len[i]);
    int cnt=0;
    for (int i=1;i<=n;i++) 
        if (dp[i+1][k-len[i]]) vis[0][++cnt]=make_pair(i,0);

