            if (k-len[j]-i-1>=0 && dp[j+1][k-len[j]-i-1]) vis[ii^1][++ncnt]=make_pair(j,0);
        }
        ii^=1;
        cnt=ncnt;
    }
    printf("%s\n", ans);
    return 0;
