int main()
{
    scanf("%d%d",&n,&K);
    for (int i=1;i<=n;++i) {
        scanf("%s",s[i]);
        len[i]=strlen(s[i]);
    }
    bit[n+1][0]=1;
    for (int i=n;i>=1;--i)
        bit[i]=bit[i+1]|(bit[i+1]<<len[i]);
    int c1=0;
    for (int i=1;i<=n;++i)
        if (bit[i+1][K-len[i]])
            v[0][++c1]=pii(i,0);
    for (int o=1;o<=K;++o) {
        char mmin='z',c2=0;
        for (int i=1;i<=c1;++i)
            mmin=min(mmin,s[v[(o-1)&1][i].first][v[(o-1)&1][i].second]);
        putchar(mmin);
        int ID=n+1;
        for (int i=1;i<=c1;++i) {
            int id=v[(o-1)&1][i].first,pos=v[(o-1)&1][i].second;
            if (s[id][pos]!=mmin) continue;
            if (pos+1==len[id]) ID=min(ID,id);
            else v[o&1][++c2]=pii(id,pos+1);
        }
        for (int i=ID+1;i<=n;++i)
            if (K-o-len[i]>=0&&bit[i+1][K-o-len[i]])
                v[o&1][++c2]=pii(i,0);
        c1=c2;
    }
