	rep(i, n) {
		if (k >= s[i].size() && b[i + 1][k - s[i].size()]) {
			if (u[s[i].size()] == mod) {
				u[s[i].size()] = i;
			}
			else {
				int id = u[s[i].size()];
				if (s[id] >= s[i]) {
					u[s[i].size()] = i;
				}
			}
		}
