				if (k - i-1 >= s[j].size() && b[j + 1][k - i-1 - s[j].size()]) {
					nex.push_back(j);
				}
			}
		}
		ans.push_back(ch);
		u[1] = mod;
		Rep1(j,2, k) {
			if (u[j] == mod)continue;
			if (s[u[j]][s[u[j]].size() - j] == ch) {
				u[j - 1] = u[j];
			}
			u[j] = mod;
		}
