}

inline int getpos(vector<Node> &now, int l, int r, int x) {
	int mid = (l + r) / 2, ans = 0;
	while(l <= r) {
		mid = (l + r) / 2;
		if(now[mid].s < x) r = mid - 1;
		else l = mid + 1, ans = mid;
	} return ans;
}

inline char getnext(vector<Node> &tmp, int ans) {
	int tmpsiz = tmp.size(), tmps = 0;
	if(ans == tmp[tmpsiz - 1].s) return 0;
	int tmpp = getpos(tmp, 0, tmpsiz - 1, ans);
	if(tmpp > 0)tmps = tmp[tmpp - 1].s;
	if(ans == tmp[tmpp].s) return s[tmp[tmpp + 1].id][1];
	else return s[tmp[tmpp].id][ans - tmps];
}

inline vector<Node> checkit(vector<Node> &tmp, vector<Node> &res) {
	int tmpsiz = tmp.size(), ressiz = res.size();
	if(!tmpsiz || !ressiz) return tmpsiz ? tmp : res;
	int l = 1, r = tmp[tmpsiz - 1].s, mid = 0, ans = 0;
	while(l <= r) {
		mid = (l + r) / 2;
		int tmpp = getpos(tmp, 0, tmpsiz - 1, mid);
		int resp = getpos(res, 0, ressiz - 1, mid);
		ull tmpt = 0, rest = 0, tmps = 0, ress = 0;
		if(tmpp > 0) tmpt = tmp[tmpp - 1].hash, tmps = tmp[tmpp - 1].s;
		tmpt += Hash[tmp[tmpp].id][mid - tmps] * fac[tmps];
		if(resp > 0) rest = res[resp - 1].hash, ress = res[resp - 1].s;
		rest += Hash[res[resp].id][mid - ress] * fac[ress];
		if(tmpt == rest) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	char tmpn = getnext(tmp, ans), resn = getnext(res, ans);
	if(tmpn < resn) return tmp; else return res;
}

