using namespace std;
vector<int>zalgo(string s)
{
	vector<int>r;
	r.resize(s.size());
	r[0] = s.size();
	s.push_back('$');
	s.push_back('@');
	int pt = 1, kn = 0;
	for (;;)
	{
		if (pt == r.size())break;
		for (;;)
		{
			if (s[pt + kn] != s[kn])break;
			else kn++;
		}
		r[pt] = kn;
		int t = 1;
		for (;;)
		{
			if (r[t] < kn - t)r[pt + t] = r[t], t++;
			else break;
		}
		pt += t;
		kn = max(0, kn - t);
	}
	return r;
}
