int reserved[20001];

int *buildZ(const string &s){
	int n = s.size();
	int *z = reserved;
	int l = 0, r = 0;

	memset(z, 0, sizeof(int)*(n + 1));
	for(int i = 1; i < n; i++){
		if(i <= r) z[i] = min(z[i - l], r - i + 1);
		while(i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
		if(i + z[i] - 1 > r){
			l = i;
			r = i + z[i] - 1;
		}
	}
	z[0] = n;
	return z;
}
int diff_point1(const string &s, const string &t, int l1, int l2, int *z){
	if(l2 < l1) return diff_point1(s, t, l2, l1, z);
	if(l1 < 0) return l2 < 0 ? s.size() : min((int)t.size(), z[t.size() + l2]) + l2;
	if(l1 == l2) return l1 + t.size();

	int l = z[t.size() + l1]; dbg(l, l1, l2);
	if(l < l2 - l1 || l >= t.size()) return l1 + min((int)t.size(), l);

	int m = z[l]; dbg(l, m);
	return l1 + min(l + m, (int)t.size());
	//if(m < t.size() - l2 + l1) return l2 + m;
	//return l1 + t.size();
}
int diff_point2(const string &s, const string &t, int l1, int l2, int *z){
	if(l1 == l2) return l1 < 0 ? s.size() : l1 + t.size();
	if(l2 < l1) return diff_point2(s, t, l2, l1, z);
	for(int i = 0; ; i++){
		if(l1 < 0){
			char c1 = i < s.size() ? s[i] : 0;
			char c2 = i < l2 ? s[i] : i - l2 < t.size() ? t[i - l2] : 0;
			if(c1 != c2 || c1 == 0) return i;
		}
		else{
			char c1 = i < l1 ? s[i] : i - l1 < t.size() ? t[i - l1] : 0;
			char c2 = i < l2 ? s[i] : i - l2 < t.size() ? t[i - l2] : 0;
			if(c1 != c2 || c1 == 0) return i;
		}
	}
}
int diff_point(const string &s, const string &t, int l1, int l2, int *z){
	//return diff_point1(s, t, l1, l2, z);
	int d1 = diff_point1(s, t, l1, l2, z);
	int d2 = diff_point2(s, t, l1, l2, z);

	if(d1 != d2){
		dbg(s, t, l1, l2, d1, d2); assert(0);
	}
	return d2;
}
int compare(const string &s, const string &t, int l1, int l2, int *z){
	if(l1 == l2) return 0;
	if(l2 < l1) return -compare(s, t, l2, l1, z);
	int k = diff_point(s, t, l1, l2, z);
	if(l1 < 0){
		//if(k >= s.size() && k >= l2 + t.size()) return 0;
		char c = k < s.size() ? s[k] : 0;
		char d = k < l2 ? s[k] : k - l2 < t.size() ? t[k - l2] : 0;
		if(c == d) return 0;
		return c < d ? -1 : 1;
	}

	//assert(!(k >= l1 + t.size() && k >= l2 + t.size()));
	char c = k < l1 ? s[k] : k - l1 < t.size() ? t[k - l1] : 0;
	char d = k < l2 ? s[k] : k - l2 < t.size() ? t[k - l2] : 0;
	if(c == d) return 0;
	dbg(c, d, s, t, k);
	return c < d ? -1 : 1;
}
bool prefix(const string &s, const string &t, int l1, int l2, int *z){
	if(l1 == l2) return 1;
	if(l2 < l1) swap(l1, l2);
	int k = diff_point(s, t, l1, l2, z); dbg(k);
	return k >= (l1 < 0 ? s.size() : l1 + t.size()) || k >= l2 + t.size();
}

