inline void exkmp(char s[], int n) {
	int k = 1; memset(f, 0, sizeof f); f[1] = n;
	rep(i, 2, n) {
		f[i] = max(0, min(k+f[k]-i, f[i-k+1]));
		while(i+f[i] <= n && s[f[i]+i] == s[f[i]+1]) f[i]++;
		if(k == 1 || f[i]+i > f[k]+k) k = i;
	}
}
inline int cmp(const node &u, const node &v) {//比较函数，-1/0/1表示</=/>，等于相当于存在真包含关系
	if(!u.y && !v.y) return 0;
	if(!u.y) return -cmp(v, u);
	if(!v.y) {
		if(v.x < u.x) return 0;
		int t = f[u.x+u.y+1];
		if(u.x+t >= v.x) return 0;
		return s1[t+1] < s1[u.x+u.y+t+1] ? -1 : 1;
	}
	if(u.x == v.x) return 0;
	if(u.x > v.x) return -cmp(v, u);
	int t = f[u.x+u.y+1];
	if(u.x+t <= v.x) return s1[t+1] < s1[u.x+u.y+t+1] ? -1 : 1;
	t = f[v.x-u.x+1];
	if(v.x+t >= u.x) return 0;
	return s1[v.x-u.x+t+1] < s1[t+1] ? -1 : 1;
}
bool operator < (const node &x, const node &y) { return cmp(x, y) < 0; }
bool operator == (const node &x, const node &y) { return !cmp(x, y); }
int main() {
	scanf("%d%d", &n, &m);//a[i]是第i个串的长度
	rep(i, 1, n) { scanf("%s", s[i]+1); a[i] = strlen(s[i]+1); }
	fl[n+1][0] = 1;//fl[i][j]表示i到n的串中是否能拼出长度为j的串
	per(i, n, 1) rep(j, 0, m) {
		fl[i][j] = fl[i+1][j];//不选第i个串
		if(j >= a[i]) fl[i][j] |= fl[i+1][j-a[i]];//选第i个串
	}
	//ch保存目前为止【不考虑长度的字典序最小】且【最长】的串，并且之后是能拼出长度m的串的
	//ok[i]=1表示这是一个断点，len保存长度
	len = 0; ok[0] = 1;
	rep(i, 1, n) {
		if(!len) {
			if(fl[i+1][m-a[i]]) rep(j, 1, a[i]) ch[++len] = s[i][j];
			ok[len] = 1; continue;
		}
		//将当前串s[i]和目前最优串ch拼起来，exkmp预处理出任意一个后缀与该串的lcp，用f保存
		tot = 0;
		rep(j, 1, a[i]) s1[++tot] = s[i][j];//s1保存拼接后的串
		rep(j, 1, len) s1[++tot] = ch[j];
		exkmp(s1, tot);
		memset(vis, 0, sizeof vis);
		rep(j, 0, m) if(fl[i+1][m-j]) {//枚举前i个串能拼成的合法长度
			if(ok[j]) { vis[j] = 1; b[j] = node(j, 0); }
			if(j >= a[i] && ok[j-a[i]]) {
				if(vis[j]) b[j] = min(b[j], node(j-a[i], a[i]));
				else { vis[j] = 1; b[j] = node(j-a[i], a[i]); }
			}
		}
		q[1] = 0; tp = 1;
		rep(j, 1, m) if(vis[j]) {
			while(tp > 1 && b[j] < b[q[tp]]) tp--;
			if(b[j] == b[q[tp]]) q[++tp] = j;
		}//这里的'=='表示是一个真包含关系，都要保存下来，记录断点
		len = q[tp];
		if(b[len].y) rep(j, 1, a[i]) ch[b[len].x+j] = s[i][j];
		ch[len+1] = 0;
		memset(ok, 0, sizeof ok);
		while(tp) ok[q[tp--]] = 1;
	}//由于每次操作都保证了之后的串能拼出长度为m的，所以最后的答案长一定为m
	printf("%s\n", ch+1);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long LL;

const int OO = 1e9;
const int MOD = 1e9 + 7;

const int N = 45;
const int M = 17;

int x[3];
int pw[N];

int dp[N][(1 << M)];

int get_hash(const vector<int>& a) {
	int mask = 0;
	int s = 0;
	for (int t: a) {
		s += t;
		mask ^= (1 << (s - 1));
	}
	return mask;
}

vector<int> dehash(int mask) {
	vector<int> a;
	int t = 0;
	while (mask > 0) {
		++t;
		if (mask & 1) {
			a.push_back(t);
			t = 0;
		}
		mask >>= 1;
	}
	return a;
}

inline int check(const vector<int>& a) {
	int i = 0;
	int sum = 0;
	for (int t: a) {
		if (i == 3)
			return 0;
		sum += t;
		if (sum > x[i])
			return 0;
		if (sum == x[i]) {
			++i;
			sum = 0;
		}
	}
	return i == 3 ? 1 : -1;
}

int recurse(int n, int mask) {
	int& ans = dp[n][mask];

	if (ans != -1)
		return ans;

	ans = 0;

	vector<int> a = dehash(mask);

	if (check(a) == 1)
		return ans = pw[n];
	if (n == 0)
		return ans = 0;

	for (int t = 1; t <= 10; ++t) {
		auto b = a;

		b.push_back(t);
		while (!b.empty() && !check(b))
			b.erase(b.begin());

		ans += recurse(n - 1, get_hash(b));
		if (ans >= MOD)
			ans -= MOD;
	}

	return ans;
}

void solve() {
	int n;
	scanf("%d%d%d%d", &n, x, x + 1, x + 2);

	memset(dp, -1, sizeof dp);

	pw[0] = 1;
	for (int i = 1; i < N; ++i)
		pw[i] = (LL) 10 * pw[i - 1] % MOD;

	printf("%d\n", recurse(n, 0));
}

