		ll HASH = 0;
		for (int j = 0; j < sz[i]; j++)
			HASH = (HASH * base + s[i][j]) % mod;
		hashVal[i] = HASH;
	}

	dp[n][0] = true;
	for (int i = n - 1; i >= 0; i--)
		dp[i] = (dp[i + 1] | (dp[i + 1] << sz[i]));

	int now = 0, tail = 0;
	for (int i = 0; i < n; i++)
	{
		if (dp[i + 1][k - sz[i]] && st.find(hashVal[i]) == st.end())
			pool[now][tail++] = mp(i, 0);
		st.insert(hashVal[i]);
	}

	for (int len = 0; len < k; len++)
	{
		char c = 'z';
		for (int i = 0; i < tail; i++)
			c = min(c, s[pool[now][i].ff][pool[now][i].ss]);

		/*cerr << "HERE " << len << ' ' << c << ':' << tail << endl;
		for (int i = 0; i < tail; i++)
			cerr << pool[now][i].ff << ' ' << pool[now][i].ss << endl;*/

		int TAIL = 0, mnpos = mod, x, y;
		for (int i = 0; i < tail; i++)
		{
			x = pool[now][i].ff;
			y = pool[now][i].ss;
			if (s[x][y] == c)
			{
				if (y + 1 == sz[x])
				{
					mnpos = min(mnpos, x);
					//cerr << "###" << endl;
				}
				else
				{
					pool[now ^ 1][TAIL++] = mp(x, y + 1);
					//cerr << "$$$" << endl;
				}
			}
		}
		st.clear();
		if (mnpos != mod)
			for (int i = mnpos + 1; i < n; i++)
			{
				//cerr << "DEBUG " << mnpos << ' ' << i << endl;
				if ((k - len - 1 - sz[i] >= 0 && dp[i + 1][k - len - 1 - sz[i]]) && st.find(hashVal[i]) == st.end())
					pool[now ^ 1][TAIL++] = mp(i, 0);
				st.insert(hashVal[i]);
			}

		tail = TAIL;
		now ^= 1;
		ans[len] = c;
	}

	cout << ans << endl;
}

#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = int(n) - 1; (i) >= 0; -- (i))
#define REP3R(i, m, n) for (int i = int(n) - 1; (i) >= (int)(m); -- (i))
#define ALL(x) begin(x), end(x)
using namespace std;
template <typename X, typename T> auto vectors(X x, T a) { return vector<T>(x, a); }
template <typename X, typename Y, typename Z, typename... Zs> auto vectors(X x, Y y, Z z, Zs... zs) { auto cont = vectors(y, z, zs...); return vector<decltype(cont)>(x, cont); }
template <typename T> ostream & operator << (ostream & out, vector<T> const & xs) { REP (i, int(xs.size()) - 1) out << xs[i] << ' '; if (not xs.empty()) out << xs.back(); return out; }

string solve(int n, int k, vector<string> const & s) {
    auto required = vectors(n + 1, k + 1, false);
    required[n][k] = true;
    REP_R (i, n) {
        int len = s[i].length();
        REP (j, k + 1) if (required[i + 1][j]) {
            required[i][j] = true;
            if (j - len >= 0) {
                required[i][j - len] = true;
            }
        }
    }

    string t;
    vector<int> cur(k + 1, -1), prv;
    cur[0] = 0;
    REP (i, n) {
        int len = s[i].length();
        cur.swap(prv);
        cur.assign(k + 1, -1);

        int modified = INT_MAX;
        int clear = INT_MAX;
        REP_R (j, k + 1) if (required[i + 1][j]) {
            if (j - len >= 0 and prv[j - len] != -1) {
                int l = j - len, r = t.length();

                if (len <= r - l and t.compare(l, len, s[i]) == 0) {  // if s[i] is a prefix of t[l, r)
                    cur[j] = j;

                } else if (r - l < len and t.compare(l, r - l, s[i], 0, r - l) == 0) {  // if t[l, r) is a prefix of s[i]
                    t += s[i].substr(r - l);
                    cur[j] = j;

                } else if (s[i].compare(0, len, t, l, r - l) < 0) {  // if you should truly replace t[l, r) with s[i]
                    for (int j1 = j - len, j2 = 0; j1 < t.length() and j2 < len; ++ j1, ++ j2) {
                        if (t[j1] != s[i][j2]) {
                            modified = j1;
                            break;
                        }
                    }
                    clear = j;
                    cur[j] = j;
                    t.erase(t.begin() + j - len, t.end());
                    t += s[i];
                }

            }
            if (prv[j] != -1 and j <= modified) {
                cur[j] = j;
            }
        }
        REP (j, k + 1) {
            if (cur[j] > clear) {
                cur[j] = -1;
            }
        }
    }
    assert (t.length() == k);
    return t;
}

int main() {
    int n, k; cin >> n >> k;
    vector<string> s(n);
    REP (i, n) cin >> s[i];
    cout << solve(n, k, s) << endl;
    return 0;
}

