    for (int i = 1; i <= n; ++i) {
        cin >> s[i];
        len[i] = (int)s[i].size();
    }
    dp[n][m] = true;
    for (int i = n - 1; i >= 0; --i) {
        for (int j = 0; j <= m; ++j) {
            dp[i][j] = dp[i + 1][j];
            if (j + len[i + 1] <= m && dp[i + 1][j + len[i + 1]]) dp[i][j] = true;
        }
    }
    st[0] = true;
    s1 = "";
    for (int i = 1; i <= n; ++i) {
        string s2 = s[i] + "#" + s1;
        int nn = (int)s2.size();
        vector<int> z(nn, 0);
        for (int j = 1, l = 0, r = 0; j < nn; ++j) {
            if (j <= r) z[j] = min(r - j + 1, z[j - l]);
            while (j + z[j] < nn && s2[z[j]] == s2[j + z[j]]) ++z[j];
            if (j + z[j] - 1 > r) l = j, r = j + z[j] - 1;
        }
        for (int j = len[i]; j <= m; ++j) if (dp[i][j]) {
            int l1 = j - len[i];
            if (!st[l1]) continue;
            int l = len[i] + l1 + 1;
            bool c = false;
            if (l >= nn) c = true;
            else {
                int r = l + z[l];
