                    s2 += s1[k - 1];
                s2 += s[i];
                s1 = s2;
                for (int k = l1 + 1; k <= m; ++k)
                    st[k] = false;
                st[j] = true;
                break;
            }
        }
        for (int j = 0; j <= m; ++j)
            if (!dp[i][j]) st[j] = false;
        int pos = 0;
        s2 = "";
        for (int j = 0; j <= m; ++j)
            if (st[j]) pos = j;
        for (int j = 1; j <= pos; ++j)
            s2 += s1[j - 1];
        s1 = s2;
    }
    if ((int)s1.size() != m) assert(false);
    cout << s1 << '\n';
    return 0;
}

