  int len=min((int)s.size(),(int)strlen(t));
  REP(i,len) if(s[i]!=t[i]){
    return s[i]<t[i];
  }
  return false;
}
bool lower2(const string& s,char* t){
  int tlen=strlen(t);
  REP(i,s.size()){
    if(i>=tlen) return false;
    if(s[i]!=t[i]){
      return s[i]<t[i];
    }
  }
  return true;
}
int common(const string& s,char* t){
  int len=min((int)s.size(),(int)strlen(t));
  REP(i,len) if(s[i]!=t[i]) return i;
  return len;
}

