bool vs[2005][100005];
vector < string > dp2[2005];

bool cmp( int a, int b ){
	if ( s[a] == s[b] ) return a < b;
	return s[a] < s[b];
}

bool cmprank( int a, int b ){
	return ra[a] < ra[b];
}

int dfs( int pos, int sz ){
	if ( sz > k ) return false;
	if ( sz == k ) return true;
	if ( pos == n ) return false;
	int &ans = dp[pos][sz];
	if ( ans != -1 ) return ans;
	ans = dfs(pos+1,sz);
	if ( sz + s[pos].size() <= k ) ans = max( ans, dfs(pos+1, sz + s[pos].size()));
	return ans;
}

string getstr( int pos, int sz ){
	if ( pos >= n ) return "";
	if ( sz == k ) return  "";

	if ( vs[pos][sz] ) return dp2[pos][sz];
	vs[pos][sz] = true;
	int len = rmq[pos].size();
	string ans = "";
	int last = -1;

	vector < int > ID;
	for ( int j = 0; j < len; j++ ){
		int id = rmq[pos][j];
		if ( dfs(id+1, sz + s[id].size()) ) {
			if ( last != -1 ){
				if ( s[last].size() >= s[id].size() ) continue;
				int len = s[last].size()-1;
				if ( Hash[last][len] != Hash[id][len] ) continue;
				bool check = false;					
				for ( int i = len + 1; i < s[id].size() ; i++ ){
					if ( s[id][i] > ans[i] ) {
						check = true;
						break;
					}
				}
				if ( check ) continue;
			}
			last = id;
			ID.push_back(id);
		}
	}
	sort(ID.begin(),ID.end());
	ans = s[ID[0]] + getstr(ID[0] + 1, sz + s[ID[0]].size());
	return dp2[pos][sz] = ans;
}

int main(){

	po[0] = 1;
	for ( int i = 1; i <= 2000; i++ ) po[i] = po[i-1] * mo;

	memset(dp,-1,sizeof(dp));
	scanf("%d%d",&n,&k);
	for ( int i = 0; i < n; i++ ){
		scanf("%s",&inp);
		string t = inp;
		// string t = "";
		// for ( int j = 0; j < 500; j++ ) t += (char)((i%26)+'a');
		s.push_back(t);
		low.push_back(i);
		for ( int j = 0; j < t.size(); j++ ){
			if ( j )  Hash[i][j] = Hash[i][j-1] + ( po[j] * t[j]) ;
			else Hash[i][j] = t[j];
		}
		for ( int j = 0; j <= k; j++ ) dp2[i].push_back("");
	}
	sort(low.begin(),low.end(),cmp);
	for ( int i = 0; i < n; i++ ) ra[low[i]] = i;

	for ( int i = 0; i < n; i++ ){
		for ( int j = i ; j < n; j++ ) rmq[i].push_back(j);
		sort(rmq[i].begin(),rmq[i].end(),cmprank);
	}

	string ans = getstr(0,0);
	cout << ans << endl;
	return 0;
}

