        if (sz(vals) && cmp(vals.back(),val) == -1) continue;
        vals.pb(val);
    }
    F0R(i,K+1) dp[i] = -1;
    trav(a,vals) dp[a.f+a.s*sz(zz)] = 0;
    cur = get(vals.back());
