bool prefix(const string &a, const string &b){
	int m = min(a.size(), b.size());
	return a.substr(0, m) == b.substr(0, m);
}

int main(){
	cin.tie(0); cin.sync_with_stdio(0);
	int n, len; cin >> n >> len; assert(len < 1000);
	vector<string> s(n);
	rep(i, n) cin >> s[i];

	vector<vector<bool>> go(n + 1, vector<bool>(len + 1));
	vector<vector<bool>> come(n + 1, vector<bool>(len + 1));
	go[n][len] = come[0][0] = 1;
	for(int i = n - 1; i >= 0; i--){
		go[i] = go[i + 1];
		for(int j = len; j >= s[i].size(); j--) if(go[i + 1][j]) go[i][j - s[i].size()] = 1;
	}

	string best = "";
	rep(i, n){
		come[i + 1] = come[i];
		string next = best;
		for(int j = 0; j + s[i].size() <= len; j++) if(come[i][j] && go[i + 1][j + s[i].size()]){

			string tmp = best.substr(0, j) + s[i];
			if(prefix(tmp, next) || prefix(next, tmp)){
				come[i + 1][j + s[i].size()] = 1;
				if(next.size() < tmp.size()) next = tmp;
				continue;
			}

			if(tmp > next) continue;
			if(tmp < next){
				int k = 0;
				for(; tmp[k] == next[k]; k++);
				for(int l = k; l <= len; l++) come[i + 1][l] = 0;
				next = tmp;
			}
			come[i + 1][j + s[i].size()] = 1;
		}
		best = next;
	}
	cout << best << endl;

	return 0;
}

