				}
				else if (used[y.fi]==len[i]) return 2;
				else return d[y.fi+used[y.fi]]<c[i][used[y.fi]];
		}
}
void Ins(int x,int y)
{
		if (!can[i+1][K-x-y*len[i]]) return;
		while (sz[now])
		{
				int gg=check(r[sz[now]],mk(x,y));
