					g[now][++sz[now]]=x+y*len[i];
					r[sz[now]]=mk(x,y);
					return;
				}
				else if (gg==1) return; 
				else --sz[now];
		}
		g[now][++sz[now]]=x+y*len[i];
		r[sz[now]]=mk(x,y); 
}
