int main(){
	int n, k; scanf("%d %d", &n, &k);
	for(int i = 0; i < n; i++) {
		scanf("%s", ss);
		s[i] = ss;
	}
	for(int i = 0; i < n; i++) len[i] = s[i].size();
	can[n][0] = 1;
	for(int i = n - 1; i >= 0; i--) can[i] = can[i + 1] | (can[i + 1] << len[i]);
	for(int i = 0; i < n; i++) if(k - len[i] >= 0 && can[i + 1][k - len[i]]) q[0][tp[0]++] = {i, 0};
	int cur = 0;
	string res;
	for(int i = 1; i <= k; i++){
		char best = 'z';
		tp[cur] = min(tp[cur], 1000);
		for(int j = 0; j < tp[cur]; j++) best = min(best, s[q[cur][j].first][q[cur][j].second]);
		res.push_back(best);
		int f = n;
		tp[cur ^ 1] = 0;
		for(int j = 0; j < tp[cur]; j++){
			int x = q[cur][j].first, y = q[cur][j].second;
			if(s[x][y] != best) continue;
			if(y + 1 == len[x]) f = min(f, x);
			else q[cur ^ 1][tp[cur ^ 1]++] = {x, y+1};
		}
		for(int j = f + 1; j < n; j++){
			if(k - i - len[j] >= 0 && can[j + 1][k - i - len[j]]){
				q[cur ^ 1][tp[cur ^ 1]++] = {j, 0};
			}
		}
		cur ^= 1;
	}
	printf("%s\n", res.c_str());
	return 0;
