inline void Min(string &a,string &b,string &c){
	for(int i=0;i<b.size();i++){
		if(a[i]<b[i]){
			return;
		}else if(a[i]>b[i]){
			a=b;a+=c;
			return;
		}
	}
	for(int i=0;i<c.size();i++){
		int add=(int)b.size()+i;
		if(a[add]<c[i]){
			return;
		}
		if(a[add]>c[i]){
			while(a.size()>b.size())a.pop_back();
			a+=c;
			return; 
		}
	}
}
