vector<int> zalgo(string s)
{
    int L = s.size();
    vector<int> z;
    z.resize(L + 1);
    int rgt = 0, lst = 0;
    for(int i = 1; i < L; i++)
    {
        if(rgt >= i)    z[i] = min(rgt - i + 1, z[i - lst + 1]);
        z[i]++;
        while(i + z[i] - 1 < L && s[ z[i] - 1 ] == s[i + z[i] - 1])
            z[i]++;
        z[i]--;
        if(i + z[i] - 1 > rgt)
        {
            rgt = z[i];
            lst = i;
        }
    }
    return z;
}

int main()
{
    #ifdef FILE_IO
