        cin >> s[i];

    dp[N + 1][0] = 1;
    for(int i = N; i >= 1; i--)
    {
        dp[i] = dp[i + 1];
        int l = s[i].size();
        dp[i] |= (dp[i + 1] << l);
    }

    spl[0] = 1;
    a = "";
    a.front();
    a.back();
    a.size();
    for(int i = 1; i <= N; i++)
    {
        int l = s[i].size();
        vector<int> z = zalgo(s[i] + a);

        int pos = a.size() + 1, st = -1;
        char newch = 0;

        for(int j = 0; j <= a.size() && j + l <= K; j++)
            if(spl[j] && dp[i + 1][K - j - l])
            {
                int cmn = z[j + l];
                if(cmn >= l || j + cmn >= a.size())    continue;

                if(a[j + cmn] > s[i][cmn])
                {
                    if(pos > j + cmn)
                    {
                        pos = j + cmn;
                        st = j;
                        newch = s[i][cmn];
                    }
                    else if(pos == j + cmn && s[i][cmn] < newch)
                    {
                        st = j;
                        newch = s[i][cmn];
                    }
                    else if(pos == j + cmn && s[i][cmn] == newch)
                    {
                        int zz = z[j - st];
                        if(j - st + zz >= l || s[i][zz] < s[i][j - st + zz])
                            st = j;
                    }
                }
            }

        if(pos < a.size())
        {
            int newsz = st;
            for(int i = newsz + 1; i < a.size(); i++)   spl[i] = 0;
            a.resize(newsz);
            a += s[i];
            spl[newsz + l] = 1;
        }
        else
        {
            for(int j = 0; j <= a.size() && j + l <= K; j++)
                if(spl[j] && dp[i + 1][K - j - l])
                {
                    int cmn = z[j + l];
                    if(j + cmn >= a.size())
                    {
                        if(st == -1)
                            st = j;
                        else
                        {
                            int zz = z[j - st];
                            if(j - st + zz >= l || s[i][zz] < s[i][j - st + zz])
                                st = j;
                        }
                    }
                }
            if(st != -1)
            {
                int newsz = st;
                a.resize(newsz);
                a += s[i];
                spl[newsz + l] = 1;
            }
        }

        z = zalgo(s[i] + a);
        for(int j = 0; j < a.size(); j++)
            if(spl[j] && dp[i + 1][K - j - l] && z[j + l] >= l)
                spl[j + l] = 1;
    }

    printf("%s\n", a.c_str());
    return 0;
}

