	scanf("%d %d",&n,&k);
	for(int i=1; i<=n; i++){
		scanf("%s", buf);
		s[i] = buf;
	}
	dp2[n+1][k] = 1;
	for(int i=n; i; i--){
		memcpy(dp2[i], dp2[i+1], sizeof(dp2[i]));
		for(int j=0; j+s[i].size()<=k; j++){
			dp2[i][j] |= dp2[i+1][j+s[i].size()];
		}
	}
	opt[0][0] = 1;
	for(int i=1; i<=n; i++){
		vector<int> vect(k + 1);
		for(int j=0; j<=k; j++){
			int transitable = 0;
			if(dp2[i+1][j] && opt[i-1][j]) transitable |= 1;
			if(dp2[i+1][j] && j >= s[i].size() && opt[i-1][j - s[i].size()]) transitable |= 2;
			if(transitable == 3){
				if(opts[i-1].substr(j - s[i].size(), s[i].size()) <= s[i]) transitable = 1;
				else transitable = 2;
			}
			vect[j] = transitable;
		}
		int lst = 0;
		for(int j=0; j<=k; j++){
			if(vect[j] == 1){
				opt[i][j] = 1;
				lst = j;
			}
