const int N=2005,M=100005;
int p[N],q[N],pa[N],n,K;
string s[N],best;
bitset<M> f[N];

int gp(int x){
	return pa[x]==x?x:pa[x]=gp(pa[x]);
}
string calc(){
	string ans;
	int now=0,r=0;
	rep(i,1,n+1) pa[i]=i;
	for(;now<K;){
		for(int x=gp(1);x<=n;){
			if(p[x]<=r){
				x=pa[x]=gp(x+1);
				continue;
			}
			if(rand()%4==0){
				x=gp(x+1);
				continue;
			}
			int nxt=now+s[p[x]].length();
			if(nxt<=K&&f[p[x]+1][K-nxt]){
				now=nxt,ans+=s[p[x]],r=p[x];
				break;
			}
			x=gp(x+1);
		}
	}
	return ans;
}

