// z[i] = len of lcp of s, s[i..]; lcp(longest common prefix)
int z[20007];
void z_fn(const string& s) {
    int n = s.size();
    for (int i = 1, l = 0, r = 0; i < n; i++) 
    {
        if (i <= r)
            z[i] = min(r-i+1, z[i-l]);
        while (i+z[i] < n && s[z[i]] == s[i+z[i]]) 
            z[i]++;
        if (i+z[i]-1 > r) 
        {
            l = i;
            r = i+z[i]-1;
        }
    }
}
bool cg[maxn][10007];
bool l[10007];
