void db()
{
    l[0]=1;
    for(int i=n;i>=1;i--)
    {
        for(int j=k;j>=0;j--)
        {
            cg[i][j]=l[j];
            if(j>=s[i].length())
                l[j]|=l[j-s[i].length()];
        }
    }
}
int dp[10007];
void solve()
{
    dp[0]=1;
    string pre;
    for(int i=0;i<k;i++) pre+='z'+1;
    for(int i=1;i<=n;i++)
    {
        string cur=s[i]+'$'+pre;
        int len=s[i].length();
        z_fn(cur);
        int pos=-1,curans=k;
        //cout<<i<<"!"<<s[i].length()<<endl;
        for(int j=k-s[i].length();j>=0;j--)
        {
            //cout<<i<<","<<k-len-j<<":"<<cg[i][k-len-j]<<endl;
            if(!dp[j]||!cg[i][k-len-j]) continue;
            int lcp=z[len+1+j];
            if(lcp>=len) continue;
            if(s[i][lcp]<pre[j+lcp]&&j+lcp<curans)
            {
                pos=j;
                curans=j+lcp;
            }
        }
        if(pos==-1) continue;
        for(int j=0;j<len;j++)
            pre[j+pos]=s[i][j];
        for(int j=pos+len;j<k;j++)
            pre[j]='z'+1;
        for (int j = pos+z[len+1+pos]+1;j<k;j++)
            dp[j] = false;
        dp[pos+len]=true;
    }
    cout<<pre<<endl;
}
