						int x = dat[s.size() + 1 + (j - s.size())];
						if (x < rr - j)
						{
							if (s[x] < now[j - s.size() + x])rr = j, ks.clear(), ks.push_back(j);
						}
						else
						{
							int y = dat[rr - j];
							if (y < s.size() - (rr - j))
							{
								if (s[rr - j + y] < s[y])rr = j, ks.clear(), ks.push_back(j);
							}
							else ks.push_back(j);
						}
					}
				}
			}
		}
		//printf("--%d\n", rr);
		for (int j = 0; j < ks.size(); j++)dp[i + 1][ks[j]] = true;
		string nn;
		if (frm[rr] == 0)
		{
			for (int j = 0; j < rr; j++)nn.push_back(now[j]);
			for (int j = rr; j < gen; j++)nn.push_back('z' + 1);
		}
		else
