int L[2050];
bitset<10001> tb[2050];
bool used[2050];
vector<int> pi[2050];
string ans;

int main() {
  scanf("%d%d", &N, &K);
  for(int i = 1; i <= N; i++) {
    scanf("%s", tmp); S[i] = tmp; L[i] = S[i].size(); 
    pi[i].resize(L[i]);
    int len = L[i]; string &P = S[i]; int i_ = i;
    for (int i = 1, k = 0; i < len; ++i) {
      while (k && P[k] != P[i]) k = pi[i_][k - 1];
      if (P[k] == P[i]) ++k;
      pi[i_][i] = k;
    }
  }

  tb[N+1][0] = 1;
  for(int i = N; i > 0; i--) {
    tb[i] = (tb[i+1] << L[i]) | tb[i+1];
  }

  int last_pos = 0;

  vector<pair<int, int>> cur;
  for(int i = 1; i <= N; i++) {
    if(tb[i+1][K - L[i]]) {
      cur.emplace_back(i, 0);
    }
  }

  for(int k = 1; k <= K; k++) {
    vector<pair<int, int>> nxt;

    char c = 'z'+1;
    for(auto it : cur) {
      int i = it.first, x = it.second;
      c = min(c, S[i][x]);
    }

    ans += c;

    int nxt_pos = N+1;
    for(auto it : cur) {
      int i = it.first, x = it.second;
      if(S[i][x] == c) {
        if(x+1 < L[i]) nxt.emplace_back(i, x+1);
        else nxt_pos = min(nxt_pos, i);
      }else {
        nxt.emplace_back(i, pi[i][x]);
      }
    }

    for(int i = nxt_pos+1; i <= N; i++) {
      int z = K - L[i] - k;
      if(!used[i] && z >= 0 && tb[i+1][z]) {
        used[i] = true;
        nxt.emplace_back(i, 0);
      }
    }

    cur = nxt;
  }

  puts(ans.c_str());
  return 0;
}

#include<bits/stdc++.h>
#define maxn 2005
#define maxl 10005
#define p 75679
#define q 937527359ll
#define Val(x) ((((long long)x) % q + q) % q)
using namespace std;
int n,k;
string s[maxn];
int len[maxn];
vector<int> h[maxn];
int fac[maxn];
inline int get_hash(int idx,int l,int r) {
	if(l==0)
		return h[idx][r];
	return Val(h[idx][r] - (long long)h[idx][l-1]*fac[r-l+1]);
}
struct state {
	int len,hash,idx;
};
struct node {
	node *lch,*rch;
	state data;
	state Merge(state lch,state rch) {
		if(rch.len == -1)	return lch;
		return state{lch.len+rch.len,Val(lch.hash*fac[rch.len]+rch.hash),-1};
	}
	void modify(int l,int r,int pos,node* pre,state now) {
		if(l==r) {
			this->data = now;
		}
		else {
			int mid = (l+r)>>1;
			if(pos <= mid) {
				this->lch = new node();
				this->rch = (pre != nullptr ? pre->rch : nullptr);
				this->lch->modify(l,mid,pos,(pre != nullptr ? pre->lch : nullptr),now);
			}
			else {
				this->lch = (pre != nullptr ? pre->lch : nullptr);
				this->rch = new node();
				this->rch->modify(mid+1,r,pos,(pre != nullptr ? pre->rch : nullptr),now);
			}
			this->data = Merge(this->lch->data,this->rch==nullptr ? state{-1,-1,-1} : this->rch->data);
		}
	}
	int find_ql(int l,int r,int need) {
		if(l==r)
			return l;
		else {
			int mid = (l+r)>>1;
			if(this->rch == nullptr || this->rch->data.len < need)
				return this->lch->find_ql(l,mid,need-(this->rch != nullptr ? this->rch->data.len : 0));
			else
				return this->rch->find_ql(mid+1,r,need);
		}
	}
	int cal(int l,int r,int num) {
		if(l==r) {
			return get_hash(this->data.idx,0,num-1);
		}
		else {
			int mid = (l+r)>>1;
			if(this->rch==nullptr || this->lch->data.len >= num)
				return this->lch->cal(l,mid,num);
			else
				return Val(this->lch->cal(l,mid,num)*fac[num-this->lch->data.len]+this->rch->cal(mid+1,r,num-this->lch->data.len));
		}
	}
	int get(int l,int r,int num) {
		if(l==r) {
			return s[this->data.idx][num-1];
		}
		else {
			int mid = (l+r)>>1;
			if(this->rch==nullptr || this->lch->data.len >= num)
				return this->lch->get(l,mid,num);
			else
				return this->rch->get(mid+1,r,num-this->lch->data.len);
		}
	}
	int cmp(int l,int r,int ql,int qr,int idx,int &st) {
		int mid = (l+r)>>1;
		if(l==r) {
			int sz = len[idx] - st;
			int a = this->data.idx;
			int l = 0 , r = sz - 1 , m;
			while(true) {
				if(r - l < 3) {
					for(m=l;m<=r && get_hash(a,0,m) == get_hash(idx,st,st+m);m++);
					m--;
					break;
				}
				m = (l+r)>>1;
				if(get_hash(a,0,m) == get_hash(idx,st,st+m))
					l = m;
				else
					r = m - 1;
			}
			if(m == sz-1)
				return 0;
			else {
				if(s[idx][st+m+1] < s[a][m+1])
					return 1;
				else
					return -1;
			}
		}
		else if(l==ql && r==qr) {
			if(this->lch->data.hash != get_hash(idx,st,st+this->lch->data.len-1))
				return this->lch->cmp(l,mid,ql,mid,idx,st);
			else {
				st += this->lch->data.len;
				return this->rch->cmp(mid+1,r,mid+1,qr,idx,st);
			}
		}
		else {
			if(qr<=mid)
				return this->lch->cmp(l,mid,ql,qr,idx,st);
			else if(ql>mid)
				return this->rch->cmp(mid+1,r,ql,qr,idx,st);
			else {
				int l_result = this->lch->cmp(l,mid,ql,mid,idx,st);
				if(l_result == 1)	return 1;
				if(l_result == 0 && st < len[idx])
					return this->rch->cmp(mid+1,r,mid+1,qr,idx,st);
				return -1;
			}
		}
	}
	void dfs(int l,int r) {
		if(l==r)
			cout << s[this->data.idx];
		else {
			int mid = (l+r)>>1;
			if(this->lch!=nullptr)	this->lch->dfs(l,mid);
			if(this->rch!=nullptr)	this->rch->dfs(mid+1,r);
		}
	}
};
int cmp_prefix(node *a,node *b,int len) {
	int l = 0 , r = len - 1 , m;
	while(true) {
		if(r-l<3) {
			for(m=l;m<=r && a->cal(1,n,m)==b->cal(1,n,m);m++);
			m--;
			break;
		}
		m = (l+r)>>1;
		if(a->cal(1,n,m) == b->cal(1,n,m))
			l = m;
		else
			r = m - 1;
	}
	if(m == len-1)
		return 0;
	if(a->get(1,n,m+1) < b->get(1,n,m+1))
		return 1;
	else
		return -1;
}
int SZ[maxn][maxl],tag[maxn][maxl];
node* dp[maxn][maxl];
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	fac[0] = 1;
	for(int i=1;i<maxn;i++)
		fac[i] = Val(fac[i-1]*p);
	cin >> n >> k;
	for(int i=1;i<=n;i++) {
		cin >> s[i];
		len[i] = (int)s[i].size();
		int hash = 0;
		for(int j=0;j<len[i];j++)
			h[i].emplace_back(hash = Val(hash*p+s[i][j]));
	}
	for(int i=0;i<=k;i++)
		dp[0][i] = nullptr;
	for(int i=1;i<=n;i++) {
		for(int j=0;j<=k;j++) {
			dp[i][j] = dp[i-1][j];
			SZ[i][j] = SZ[i-1][j];
			tag[i][j] = tag[i-1][j];
		}
		int st;
		if(dp[i-1][len[i]] == nullptr || dp[i-1][len[i]]->cmp(1,n,dp[i-1][len[i]]->find_ql(1,n,len[i]),SZ[i-1][len[i]],i,st=0) == 1) {
			dp[i][len[i]] = new node();
			dp[i][len[i]]->modify(1,n,1,nullptr,state{len[i],h[i][len[i]-1],i});
			SZ[i][len[i]] = 1;
			tag[i][len[i]] = i;
		}
		for(int j=len[i]+1;j<=k;j++)
			if(dp[i-1][j-len[i]] != nullptr) {
				int pre_rst;
				if(dp[i-1][j] == nullptr || tag[i-1][j-len[i]] > tag[i-1][j] || (pre_rst = cmp_prefix(dp[i-1][j-len[i]],dp[i-1][j],j-len[i])) == 1 ||
												(pre_rst == 0 && dp[i-1][j]->cmp(1,n,dp[i-1][j]->find_ql(1,n,len[i]),SZ[i-1][j],i,st=0) == 1)) {
					dp[i][j] = new node();
					dp[i][j]->modify(1,n,SZ[i-1][j-len[i]]+1,dp[i-1][j-len[i]],state{len[i],h[i][len[i]-1],i});
					SZ[i][j] = SZ[i-1][j-len[i]] + 1;
					tag[i][j] = i;
				}
			}
	} 
	dp[n][k]->dfs(1,n);
	cout << '\n';
	return 0;
}

