int P[2*MAXK];
void exkmp(int L)
{
	P[1]=0;
	for(int i=2,R=0,pos=0;i<=L;i++)
	{
		if(i<=R)P[i]=min(P[i-pos+1],R-i+1);
		while(i+P[i]<=L&&T[i+P[i]]==T[P[i]+1])++P[i];
		if(P[i]>R)R=P[i],pos=i;
	}
}
int cmp(node n1,node n2)//< -1 = 0 > 1
{
	if(!n1.y&&!n2.y)return 0;
	if(!n2.y)return -cmp(n2,n1);
	if(!n1.y)
	{
		if(n1.x<=n2.x)return 0;int L=P[n2.x+1+len[n2.y]];
		if(n2.x+L>=n1.x)return 0;
		return T[L+1]-'a'<T[n2.x+L+1+len[n2.y]]-'a'?1:-1;
	}
	if(n1.x>n2.x)return -cmp(n2,n1);
	int L=P[n1.x+1+len[n1.y]];
	if(n1.x+L<n2.x)return T[L+1]-'a'<T[n1.x+L+1+len[n1.y]]-'a'?-1:1;
	L=P[n2.x-n1.x+1];
	if(n2.x+L==n1.x+len[n1.y]-1)return 0;
	return T[L+1]-'a'<T[n2.x-n1.x+L+1]-'a'?1:-1;
}
