string get_answer(int idx, int size, int pick = 0)
{
    string ans = pick ? xs[idx] : "";

    while ((pick = next_st[idx][size]) != -1)
    {
        if (pick)
        {
            ans += xs[idx];
            size -= xs[idx].size();
        }

        ++idx;
    }

    return ans;
}

int dp(int idx, int size, int N, int K)
{
//cout << "--> dp(" << idx << ", " << size << ")" << endl;
    if (size < 0)
        return 0;

    if (size == 0)
        return 1;

    if (idx == N)
        return 0;

    if (st[idx][size] != -1)
        return st[idx][size];

//cout << "### dp(" << idx << ", " << size << "). Picking... ";
    int a = dp(idx + 1, size - xs[idx].size(), N, K);
//cout << "res = " << res << endl;
    int b = dp(idx + 1, size, N, K);
    int res;

    if (not b)
    {
        res = a;
        next_st[idx][size] = 1;
    } else if (not a)
    {
        res = b;
        next_st[idx][size] = 0;
    } else
    {
        auto x = get_answer(idx, size, 1);
        auto y = get_answer(idx, size, 0);

        if (x < y)
        {
            res = a;
            next_st[idx][size] = 1;
        } else
        {
            res = b;
            next_st[idx][size] = 0;
        }
    }

    st[idx][size] = res;
    return res; 
}

