int dfs( int pos, int sz ){
	if ( sz > k ) return false;
	if ( sz == k ) return true;
	if ( pos == n ) return false;
	int &ans = dp[pos][sz];
	if ( ans != -1 ) return ans;
	ans = dfs(pos+1,sz);
	if ( sz + s[pos].size() <= k ) ans = max( ans, dfs(pos+1, sz + s[pos].size()));
	return ans;
}

string getstr( int pos, int sz ){
	if ( pos >= n ) return "";
	if ( sz == k ) return  "";

	if ( vs[pos][sz] ) return dp2[pos][sz];
	vs[pos][sz] = true;
	int len = rmq[pos].size();
	string ans = "";
	int last = -1;
	for ( int j = 0; j < len; j++ ){
		int id = rmq[pos][j];
		if ( dfs(id+1, sz + s[id].size()) ) {
			if ( last != -1 ){
				if ( s[last].size() >= s[id].size() ) continue;
				int len = s[last].size()-1;
				if ( Hash[last][len] != Hash[id][len] ) continue;
				bool check = false;					
				for ( int i = len + 1; i < s[id].size() ; i++ ){
					if ( s[id][i] > ans[i] ) {
						check = true;
						break;
					}
				}
				if ( check ) continue;
			}
