				int l = getlen(a[i],1,dp[i - 1],j + 1);
				if(l == a[i].len) continue;
				if(j + l < dp[i - 1].len) {
					if(dp[i - 1].s[j + l + 1] > a[i].s[l + 1]) app = j;
				}
				else if(s != -1){
					int t = getlen(a[i],l + 1,a[i],s);
					if(a[i].s[s + t] > a[i].s[l + 1 + t]) {app = j;s = l + 1;}
				}
				else {
					s = l + 1;app = j;
				}
			}
		}
		if(app != -1) {
			for(int j = 0 ; j <= app ; ++j) {
				dp[i].s[j] = dp[i - 1].s[j];
				if(ed[i - 1][j] && c[i + 1][j]) ed[i][j] = 1;
			}
			dp[i].len = app + a[i].len;
			for(int j = app + 1 ; j <= app + a[i].len ; ++j) dp[i].s[j] = a[i].s[j - app];
			dp[i].calc();
			for(int j = 0 ; j <= app ; ++j) {
				if(ed[i - 1][j]) {
					int l = getlen(a[i],1,dp[i],j + 1);
					if(l == a[i].len) ed[i][j + a[i].len] = 1;
				}
			}
		}
		else {
			for(int j = 0 ; j <= dp[i - 1].len ; ++j) {
				dp[i].s[j] = dp[i - 1].s[j];
				if(ed[i - 1][j] && c[i + 1][j]) ed[i][j] = 1;
			}
			dp[i].len = dp[i - 1].len;
			while(!ed[i][dp[i].len]) --dp[i].len;
			dp[i].calc();
		}
	}
	for(int i = 1 ; i <= dp[N].len ; ++i) {
		putchar(dp[N].s[i]);
	}
	enter;
	return 0;
}

