        if (dp[i+sz(zz)] == -1 || cmp(mp(i,1),mp(i+sz(s[ind]),0)) == -1) 
        	dp[i+sz(zz)] = 1;

    F0R(i,K+1) if (!ok[ind+1][i]) dp[i] = -1;
    vpi vals;
    F0R(i,K+1) if (dp[i] != -1) {
        pi val = {i-sz(zz)*dp[i],dp[i]};
        while (sz(vals) && cmp(vals.back(),val) == 1) vals.pop_back();
        if (sz(vals) && cmp(vals.back(),val) == -1) continue;
