string solve(int K, vector<string>s, vector<pair<string,int>> memo, vector<string>minlist) {

	if (memo[K].first.size() == K || memo[K].second == 1)return memo[K].first;

	string answer = minlist[K];
	for (int i = 1; i <= K - 1; i++) {
		string s1 = solve(i, s, memo, minlist);
		string s2 = solve(K - i, s, memo, minlist);
		if (s1.size() == i && s2.size() == K - i) {
			string candidate = s1 + s2;
			if (answer.size() != K)answer = candidate;
			else answer = min(answer, candidate);
		}
	}

	memo[K].first = answer;
	memo[K].second = 1;
	return answer;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K;
	cin >> N >> K;
	vector<string>s(N);
	rep(i, N)cin >> s[i];
	sort(ALL(s));

	vector<string>minlist(K + 1,"");
	rep(i, N) {
		int index = s[i].size();
		if (minlist[index].size() == index)minlist[index] = min(minlist[index], s[i]);
		else minlist[index] = s[i];
	}

	vector<pair<string, int>>memo(K + 1, make_pair("", 0));

	string ans = solve(K, s, memo,minlist);
	cout << ans << endl;
}

