struct node{ int x,y; }b[M];
int sig(node u,node v){
	if (!u.y && !v.y) return 0;
	if (!u.y) return -sig(v,u);
	if (!v.y){
		if (v.x<=u.x) return 0;
		int t=f[u.x+u.y+1];
		if (u.x+t>=v.x) return 0; else
		return s0[t+1]<s0[u.x+u.y+t+1]?-1:1;
	}
	if (u.x==v.x) return 0;
	if (u.x>v.x) return -sig(v,u);
	int t=f[u.x+u.y+1];
	if (u.x+t>=v.x){
		t=v.x-u.x;
		if (f[t+1]>=u.y-t) return 0;
		else return s0[f[t+1]+t+1]<s0[f[t+1]+1]?-1:1;
	} else return s0[t+1]<s0[u.x+u.y+t+1]?-1:1;
}
bool operator <(node u,node v){ return sig(u,v)<0; }
bool operator ==(node u,node v){ return !sig(u,v); }
void work(char *s,int n){
	int i,k; f[1]=0;
	for (i=2,k=1; i<=n; i++){
		f[i]=min(k+f[k]-i,f[i-k+1]);
		if (f[i]<0) f[i]=0;
		for (; s[f[i]+1]==s[i+f[i]] && i+f[i]<=n; f[i]++);
		if (i+f[i]>k+f[k]) k=i;
	}
}
