			pool.popb();
		}
		delQ.clear();

		int MIN = mod;
		for (int i = 0; i < pool.size(); i++)
		{
			pool[i].ss++;
			if (pool[i].ss == s[pool[i].ff].size())
			{
				MIN = min(MIN, i);
				delQ.pb(i);
				//cerr << "ENDED " << pool[i].ff << ' ' << pool[i].ss << endl;
			}
		}
		for (int pos : delQ)
		{
			if (pos == MIN)
			{
				for (int i = pool[pos].ff + 1; i < n; i++)
					if (dp[i][k - len - 1])
					{
						mark[i] = true;
						//pool.pb(mp(i, 0));
					}
			}
			swap(pool[pos], pool[pool.size() - 1]);
			pool.popb();
			/*cerr << "_____________ UPDATE POOL _______________" << endl;
			for (auto i : pool)
				cerr << i.ff << ' ' << i.ss << endl;*/
		}
		delQ.clear();

		for (int i = 0; i < n; i++)
			if (mark[i])
			{
				pool.pb(mp(i, 0));
				mark[i] = false;
			}

		ans += c;
	}
	cout << ans << endl;
}

