    for(int j = K; S[i].size() <= j; --j) reach[i][j] = reach[i][j] | reach[i][j - S[i].size()];
  }

  vector<string> CS(N + 1);
  vector<vector<bool>> dp(N + 1, vector<bool>(K + 1));
  dp[0][0] = true;
  for(int i = 0; i < N; ++i) {
    CS[i + 1] = CS[i] + "~";
    int p = CS[i].size() + S[i].size();
    for(int j = 0; j <= K - S[i].size(); ++j) if(dp[i][j]) if(reach[i + 1][K - j - S[i].size()]) {
      auto s = CS[i].substr(0, j) + S[i] + "~";
      if(CS[i + 1] < s) continue;
      CS[i + 1] = s;
      p = j;
    }
    CS[i + 1].pop_back();
    for(int j = 0; j <= K; ++j) if(dp[i][j]) {
      if(j <= p) if(reach[i + 1][K - j]) dp[i + 1][j] = true;
      if(K - S[i].size() < j) continue;
      if(CS[i].substr(0, j) + S[i] == CS[i + 1].substr(0, j + S[i].size())) if(reach[i + 1][K - j - S[i].size()]) dp[i + 1][j + S[i].size()] = true;
    }
  }

  cout << CS[N].substr(0, CS[N].size()) << endl;
}

