        cin >> strs[i];
    }

    vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        order[i] = i;
    }
    sort(order.begin(), order.end(), [&](int a, int b) {
        string A = strs[a] + strs[b];
        string B = strs[b] + strs[a];
        if (A == B)
            return a < b;
        return A < B;
    });
    vector<int> pos(n);
    for (int i = 0; i < n; ++i)
        pos[order[i]] = i;

    vector<vector<int>> dp(n + 1, vector<int>(k + 1, -2));
    dp[n][0] = -1;

    for (int i = n - 1; i >= 0; --i) {
        dp[i] = dp[i + 1];
        for (int j = 0; j + strs[i].size() <= k; ++j) {
            if (dp[i][j] == -2) continue;
            int nj = j + strs[i].size();
            if (dp[i][nj] == -2 || dp[i][nj] > pos[i])
                dp[i][nj] = pos[i];
        }
    }

    assert(dp[0][k] != -2);
    for (int at = dp[0][k]; at != -1; at = dp[order[at] + 1][k]) {
        // cerr << "AT: " << order[at] << endl;
        cout << strs[order[at]];
        k -= strs[order[at]].size();
    }
    cout << endl;

    return 0;
}

