		sz[i] = SZ(all);
		all += s[i];
	}
	sz[n + 1] = SZ(all);
	rep (i, 0, SZ(all) - 1) {
		tree[all[i] - 'a' + 32].set(i);
	}
	per (i, 31, 1) {
		tree[i] = tree[i << 1] | tree[i << 1 | 1];
	}
	state.set(0, 1);
	rep (i, 0, m - 1) {
		rep (j, 1, n) {
			if (state.test(sz[j])) state.set(sz[j + 1]);
		}
		rep (j, 1, n) {
			if (m - i - SZ(s[j]) < 0 || !can[j + 1][m - i - SZ(s[j])]) state.reset(sz[j]);
		}
		static char ch;
		ans += ch = query();
		(state &= tree[ch - 'a' + 32]) <<= 1;
	}
	cout << ans << endl;
	return 0;
}

