	for (int i = n - 1; i >= 0; i--)
	{
		for (int j = 0; j <= k; j++)
		{
			filler[i][j] |= filler[i + 1][j];
			if (j + s[i].size() <= k)
			{
				dp[i][j + s[i].size()] |= filler[i + 1][j];
				filler[i][j + s[i].size()] |= filler[i + 1][j];
			}
		}
	}

	for (int i = 0; i < n; i++)
		if (dp[i][k])
		{
			pool.pb(mp(i, 0));
			//cerr << "BASE " << i << endl;
