				can[i][j]=1;
		}
	siz=k;
	while(t<=n&&ans.length()<k)
	{
		b=0;
		for(int i=n;i>=t;i--)
			if(siz-len[i]>=0&&can[i+1][siz-len[i]]==1&&(b==0||a[i]<=p))
				p=a[i],b=1,loc=i;
		t=loc+1,ans+=p,siz-=len[loc];
	}
	cout<<ans;
	return 0;	
}

