vector<int> z_algo(string s) {
  vector<int> z(20020, 0);
  for (int i = 1, l = 0, r = 1; i < len(s); i++) {
    if (i >= r) {
      l = r = i;
      while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]]) z[i]++, r++;
    } else if (r - i > z[i - l]) {
      z[i] = z[i - l];
    } else {
      z[i] = r - i;
      l = i;
      while (i + z[i] < len(s) && s[z[i]] == s[i + z[i]]) z[i]++, r++;
    }
  }
  return z;
}

void solve() {
  cin >> n >> k;
  rep(i, 1, n) { cin >> s[i]; }

  can[n + 1][0] = true;
  per(i, n, 1) {
    rep(j, 0, k) {
      if (!can[i + 1][j]) continue;
      can[i][j] = true;
      if (j + len(s[i]) > k) continue;
      can[i][j + len(s[i])] = true;
    }
  }

  ok[0][0] = true;
  ans = "";
  rep(i, 1, n) {
    int ans_prefix_len = -1;
    vector<int> z = z_algo(s[i] + ans);
    rep(j, 0, k) {
      if (!ok[i - 1][j]) continue;
      ok[i][j] = true;

      int new_len = j + len(s[i]);
      if (new_len > k) continue;
      if (!can[i + 1][k - new_len]) continue;

      // new_str = ans.substr(0, j) + s[i]
      // 1. new_str is prefix of ans - OK
      // 2. ans is prefix of new_str - OK, UPDATE ans
      // 3. new_str is higher than ans - SKIP
      // 4. new_str is lower than ans - RESET

      if (z[len(s[i]) + j] >= len(s[i])) {
        ok[i][new_len] = true;
      } else if (z[len(s[i]) + j] <= len(s[i]) &&
                 j + z[len(s[i]) + j] == len(ans)) {
        ok[i][new_len] = true;
        ans_prefix_len = j;
      } else if (s[i][z[len(s[i]) + j]] > ans[j + z[len(s[i]) + j]]) {
        continue;
      } else {
        int prefix_len = j + z[len(s[i]) + j];
        rep(l, prefix_len + 1, k) { ok[i][l] = false; }
        ok[i][new_len] = true;
        ans_prefix_len = j;
        break;
      }
    }

    if (ans_prefix_len != -1) {
      ans = ans.substr(0, ans_prefix_len) + s[i];
