int main(){
	ios::sync_with_stdio(false);
	cin>>n>>k;
	Pow[0]=1;
	for (int i=1;i<10002;++i) Pow[i]=Pow[i-1]*H%MOD;
	for (int i=1;i<=n;++i) cin>>s[i];
	for (int i=1;i<=n;++i) len[i]=s[i].size();
	for (int i=1;i<=n;++i) s[i]='.'+s[i];
	dp[0][0]=0;
	for (int i=1;i<=n;++i){
		if (i==1&&len[i]<=k){
			dp[i][len[i]]=++tot;
			for (int j=1;j<=len[i];++j) Hash[tot][j]=(Hash[tot][j-1]+s[i][j])*H%MOD;
			path[i][len[i]]=1;
			continue;
		}
		else if (i==1||len[i]>k) continue;
		for (int j=1;j<=len[i];++j) Hashs[i][j]=(Hashs[i][j-1]+s[i][j])*H%MOD;
		for (int l=0;l<len[i];++l) dp[i][l]=dp[i-1][l],path[i][l]=-1;
		for (int l=0;l+len[i]<=k;++l){
			int cur=dp[i-1][l],old=dp[i-1][l+len[i]];
			if (cur==0&&l>0) continue;
			if (old==0){
				dp[i][l+len[i]]=(cur==0? cur=++tot:cur);
				for (int j=1;j<=len[i];++j) Hash[cur][l+j]=(Hash[cur][l+j-1]+s[i][j])*H%MOD;
				path[i][l+len[i]]=1;
				continue;
			}
			// check different
			int L=0,R=l+len[i];//L:must same  R:must diff
			if (Hash[old][R]==(Hash[cur][l]*Pow[len[i]]+Hashs[i][len[i]])%MOD) continue;// already same
			while(L<R-1){
				int M=L+R>>1;
				bool same;
				if (M<=l) same=(Hash[old][M]==Hash[cur][M]);
				else same=(Hash[old][M]==(Hash[cur][l]*Pow[M-l]+Hashs[i][M-l])%MOD);
				if (same) L=M;
				else R=M;
			}
			ll orgH=Hash[old][L],oldH=Hash[old][R],curH=(R<=l? Hash[cur][R]:(Hash[cur][l]*Pow[R-l]+Hashs[i][R-l])%MOD);
			int oldch,curch;
			for (int ch='a';ch<='z';++ch) if ((orgH+ch)*H%MOD==oldH) oldch=ch;
			for (int ch='a';ch<='z';++ch) if ((orgH+ch)*H%MOD==curH) curch=ch;
			if (curch<oldch){
				dp[i][l+len[i]]=(cur==0? cur=++tot:cur);
				for (int j=1;j<=len[i];++j) Hash[cur][l+j]=(Hash[cur][l+j-1]+s[i][j])*H%MOD;
				path[i][l+len[i]]=1;
			}
			else{
				dp[i][l+len[i]]=old;
				path[i][l+len[i]]=-1;
			}
		}
	}
	//for (int i=1;i<=n;++i) for (int j=1;j<=k;++j) cout<<"i="<<i<<" j="<<j<<" path="<<path[i][j]<<" dp="<<dp[i][j]<<endl;
	print(n,k);
	cout<<endl;
	return 0; 
}

