const int L = (int)1e6 + 100;
const int LOG = 20;
const int S = N * K;

struct Node
{
	int id, nxt;

	Node() : id(-1), nxt(-1) {}
	Node(int _id) : id(_id), nxt(-1) {}
	Node(int _id, int _nxt) : id(_id), nxt(_nxt) {}
};
Node A[S];
int sz = 0;
int dp[K];
int len[N], stPos[N];
char s[L];
int SA[L], nSA[L], col[L], ncol[L];
int C[L];
int revSA[L];
int lcp[L];
int sparse[LOG][L];
int p2[L];
int n, k;

void buildSA(int LEN)
{
	s[LEN] = (char)0;
	LEN++;
	for (int i = 0; i < LEN; i++)
		C[s[i] + 1]++;
	for (int i = 1; i < 300; i++)
		C[i] += C[i - 1];
	for (int i = 0; i < LEN; i++)
		SA[C[s[i]]++] = i;
	col[SA[0]] = 0;
	for (int i = 1; i < LEN; i++)
	{
		col[SA[i]] = col[SA[i - 1]];
		if (s[SA[i]] != s[SA[i - 1]])
			col[SA[i]]++;
	}
	for (int curLen = 1; col[SA[LEN - 1]] != LEN - 1; curLen *= 2)
	{
		for (int i = 0; i <= col[SA[LEN - 1]] + 1; i++)
			C[i] = 0;
		for (int i = 0; i < LEN; i++)
			C[col[i] + 1]++;
		for (int i = 0; i <= col[SA[LEN - 1]]; i++)
			C[i + 1] += C[i];
		for (int i = 0; i < LEN; i++)
		{
			int pos = SA[i] - curLen;
			if (pos < 0) pos += LEN;
			nSA[C[col[pos]]++] = pos;
		}
		ncol[nSA[0]] = 0;
		for (int i = 1; i < LEN; i++)
		{
			ncol[nSA[i]] = ncol[nSA[i - 1]];
			if (make_pair(col[nSA[i]], col[(nSA[i] + curLen) % LEN]) != make_pair(col[nSA[i - 1]], col[(nSA[i - 1] + curLen) % LEN]))
				ncol[nSA[i]]++;
		}
		for (int i = 0; i < LEN; i++)
		{
			col[i] = ncol[i];
			SA[i] = nSA[i];
		}
	}
	int curLCP = 0;
	for (int i = 0; i < LEN; i++)
		revSA[SA[i]] = i;
	for (int i = 0; i < LEN; i++)
	{
		int p = revSA[i];
		if (p == LEN - 1)
		{
			lcp[p] = curLCP = 0;
			continue;
		}
		int q = SA[p + 1];
		curLCP = max(0, curLCP - 1);
		while(i + curLCP < LEN && q + curLCP < LEN && s[i + curLCP] == s[q + curLCP])
			curLCP++;
		lcp[p] = curLCP;
	}
	LEN--;
	for (int i = 0; i < LEN; i++)
		sparse[0][i] = lcp[i];
	for (int k = 1; k < LOG; k++)
		for (int i = 0; i + (1 << k) <= LEN; i++)
			sparse[k][i] = min(sparse[k - 1][i], sparse[k - 1][i + (1 << (k - 1))]);
	p2[0] = p2[1] = 0;
	for (int i = 2; i < L; i++)
		p2[i] = p2[i / 2] + 1;
	return;
}

int getMin(int l, int r)
{
	int k = p2[r - l];
	return min(sparse[k][l], sparse[k][r - (1 << k)]);
}
int getLCP(int x, int y)
{
	if (x == y) return L;
	x = revSA[x], y = revSA[y];
	if (x > y) swap(x, y);
	return getMin(x, y);
}

void read()
{
	scanf("%d%d", &n, &k);
	stPos[0] = 0;
	for (int i = 0; i < n; i++)
	{
		scanf(" %s ", s + stPos[i]);
		len[i] = strlen(s + stPos[i]);
		stPos[i + 1] = stPos[i] + len[i];
	}
	buildSA(stPos[n]);
	return;
}

void printString(int id)
{
	for (int i = 0; i < len[id]; i++)
		printf("%c", s[stPos[id] + i]);
	return;
}
void print(int q)
{
	for (; q != -1; q = A[q].nxt)
	{
		int id = A[q].id;
		printString(id);
	}
	printf("\n");
	return;
}

bool cmpLists(int q1, int pos1, int q2, int pos2)
{
	while(true)
	{
		if (q1 == q2 && pos1 == pos2) return false;
		int maxLen = min(len[A[q1].id] - pos1, len[A[q2].id] - pos2);
		int curLCP = getLCP(stPos[A[q1].id] + pos1, stPos[A[q2].id] + pos2);
		if (curLCP >= maxLen)
		{
			pos1 += maxLen;
			if (pos1 == len[A[q1].id])
			{
				q1 = A[q1].nxt;
				pos1 = 0;
			}
			pos2 += maxLen;
			if (pos2 == len[A[q2].id])
			{
				q2 = A[q2].nxt;
				pos2 = 0;
			}
			continue;
		}
		pos1 += stPos[A[q1].id] + curLCP;
		pos2 += stPos[A[q2].id] + curLCP;
		return s[pos1] < s[pos2];
	}
}

void solve(int id)
{
	for (int curLen = k - len[id]; curLen >= 0; curLen--)
	{
		if (dp[curLen] == -2) continue;
		int newLen = curLen + len[id];
		int q = sz;
		A[sz++] = Node(id, dp[curLen]);
		if (dp[newLen] == -2)
		{
			dp[newLen] = q;
			continue;
		}
		if (cmpLists(q, 0, dp[newLen], 0))
			dp[newLen] = q;
	}
	return;
}

int main()
{
//	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);

	read();
	dp[0] = -1;
	for (int i = 1; i <= k; i++)
		dp[i] = -2;
	for (int i = n - 1; i >= 0; i--)
		solve(i);
	if (dp[k] == -2) throw;
	print(dp[k]);

	return 0;
}

