		dbg(z[0]);
		rep(j, len + 1) if(come[i][j] && j + s[i].size() <= len && go[i + 1][j + s[i].size()]){

			/*
			string tmp = best.substr(0, j) + s[i];
			if(prefix(next, tmp) && next.size() < tmp.size()) next = tmp;
			else if(tmp < next) next = tmp;
			*/
			int k = compare(best, s[i], j, next_l, z);
