int val[2010];
int main(){
	SF("%d%d",&n,&k);
	for(int i=1;i<=n;i++){
		SF("%s",s[i]);
		val[i]=strlen(s[i]);
	}
	dp[n+1][0]=1;
	for(int i=n;i>0;i--)
		for(int j=0;j<=k;j++)
			if(dp[i+1][j]==1){
				dp[i][j]=1;
				if(j+val[i]<=k)
					dp[i][j+val[i]]=1;
			}
	int now=0,cnt=0;
	for(int i=1;i<=n;i++)
		if(dp[i+1][k-val[i]]==1)
			qr[now][++cnt]=make_pair(i,0);
	while(k--){
		char minc='z';
		int cntn=0,minid=n+1;

		for(int i=1;i<=cnt;i++){
			int id=qr[now][i].first;
			int num=qr[now][i].second;
			minc=min(minc,s[id][num]);
		}
		PF("%c",minc);
		for(int i=1;i<=cnt;i++){
			int id=qr[now][i].first;
			int num=qr[now][i].second;
			if(s[id][num]!=minc)
				continue;
			if(num+1==val[id])
				minid=min(minid,id);
			else
				qr[now^1][++cntn]=make_pair(id,num+1);
		}
		for(int i=minid+1;i<=n;i++)
			if(val[i]<=k&&dp[i+1][k-val[i]]==1)
				qr[now^1][++cntn]=make_pair(i,0);
		now^=1;
		cnt=cntn;
	}
}

