  dp[0][0] = 1;

  string ans;
  for (int i = 1; i <= n; ++i) {
    dp[i] = dp[i - 1];

    vector<int> d = Zalgorithm(s[i] + ans);
    for (int j = 0; j <= ans.size() && j + s[i].size() <= k; ++j) {
      int t = d[s[i].size() + j];

      if (dp[i - 1][j] && reach[i][j + s[i].size()] && (j == ans.size() || (t < s[i].size()) && (ans[j + t] > s[i][t]))) {
        ans = ans.substr(0, j) + s[i];
        for (int l = j + 1; l <= k; ++l) dp[i][l] = 0;
        dp[i][j + s[i].size()] = 1;
        break;
      }
    }
  }

  cout << ans << endl;
}

