typedef pair< pair<int,int> , int > tup;

const int N = (int)2e3;
const int K = (int)1e4;
const int M = (int)2e6;
const int DEP = 22;

int TWO[DEP];

char s[M+5];
int sidx[N+5];
int slen[N+5];

int dp[N+5][K+5];
int sa[DEP][M+5];
int compare(int ai, int bi, int j, int n) {
    // return 1 if (bi,j) is lexicographically smaller
    int lena = slen[ai];
    int lenb = slen[bi];
    int posa = sidx[ai];
    int posb = sidx[bi];

    while (ai <= n && bi <= n) {
        int res = 0;
        for (int i=DEP-1; i>=0; i--) {
            if (res + TWO[i] <= min(lena,lenb)) {
                if (sa[i][posa] == sa[i][posb]) {
                    posa += TWO[i];
                    posb += TWO[i];
                    res += TWO[i];
                }
            }
        }

        if (res == lena && res == lenb) {
            ai = dp[ai+1][j-lena];
            lena = slen[ai];
            posa = sidx[ai];
            bi = dp[bi+1][j];
            lena = slen[bi];
            posa = sidx[bi];
        } else if (res == lena) {
            ai = dp[ai+1][j-lena];
            lena = slen[ai];
            posa = sidx[ai];
            lenb -= res;
        } else if (res == lenb) {
            bi = dp[bi+1][j];
            lena = slen[bi];
            posa = sidx[bi];
            lena -= res;
        } else {
            return sa[0][posa+1] > sa[0][posb+1];
        }
    }
    return 0;
}


vector<tup> sortlist;
vector<tup> bucket[M+5];
int buildSA(int n){
    TWO[0] = 1;
    for (int i=1; i<DEP; i++) {
        TWO[i] = 2 * TWO[i-1];
    }

    for (int i=0; i<=n; i++) {
        sa[0][i] = (int)s[i];
    }

    for (int dep=1; dep<DEP; dep++) {
        sortlist.clear();
        for (int i=0; i<=n; i++){
            pair<int,int> temp = make_pair(sa[dep-1][i], 0);
            if (i+TWO[i] <= n) {
                temp.second = sa[dep-1][i+TWO[i]];
            }

            sortlist.push_back( make_pair(temp,i) );
        }

        for (int i=0; i<M+3; i++) {
            bucket[i].clear();
        }
        for (tup x: sortlist){
            bucket[x.first.second].push_back(x);
        }
        sortlist.clear();
        for (int i=0; i<M+3; i++) {
            for (tup x: bucket[i]) {
                sortlist.push_back(x);
            }
        }

        for (int i=0; i<M+3; i++) {
            bucket[i].clear();
        }
        for (tup x: sortlist){
            bucket[x.first.first].push_back(x);
        }
        sortlist.clear();
        for (int i=0; i<M+3; i++) {
            for (tup x: bucket[i]) {
                sortlist.push_back(x);
            }
        }

        for (int i=0; i<=n; i++){
            if (i == 0) {
                sa[dep][sortlist[i].second] = 0;
            } else if (sortlist[i-1].first == sortlist[i].first) {
                sa[dep][sortlist[i].second] = sa[dep][sortlist[i-1].second];
            } else {
                sa[dep][sortlist[i].second] = sa[dep][sortlist[i-1].second];
            }
        }
    }

    return 0;
}

