vector< vector<bool> > m1, m2;
bool can_make(int idx, int rest) {
    if (rest == 0) return true;
    if (rest < 0) return false;
    if (idx >= s.size()) return false;
    if (m1[idx][rest]) return m2[idx][rest];
    bool res = false;
    FOR(i, idx, s.size()) {
        if ( can_make(i+1, rest-s[i].size()) ) {
            res = true;
            break;
        }
    }
    return m1[idx][rest] = true, m2[idx][rest] = res;
}

