                    if(j+L>=LL||S[L+1]<S[len[i]+j+L+1]) mn=j;
                }
                continue;
            }
            if(Small(mn,j,len[i])>=0) mn=j;
        }
        if(mn==-1) continue;
        memset(f+mn+len[i]+1,0,sizeof(bool)*(K-mn-len[i]+3));
        for(int j=min(LL,mn+len[i]);~j;--j) if(f[j]&&b[i+1][j]) f[j]=1;
        for(int j=0;j<=mn;++j) if(f[j]&&b[i+1][j+len[i]]&&(j==mn||Small(j,mn,len[i])==0)) f[j+len[i]]=1;
        ans=ans.substr(0,mn)+st[i];
