string s[2020];
int ind[2020];
char bs[MAXN];

inline int cmp(int a, int b)
{
    return rev[ind[a]] < rev[ind[b]];
}

string solveans()
{
    int rem = K;
    string str = "";
    int pi = 1;
    while(rem)
    {
        int i = ansind[pi][rem];
        str += s[i];     
        rem -= s[i].length();
        pi = i+1;
    }
    return str;
}

void fillind()
{
    for(int j=0; j<=K; ++j)
    {
        ansind[N+1][j] = N+1;
        for(int i=N; i>=1; --i)
        {
            ansind[i][j] = ansind[i+1][j];
            if(!dp[i][j]) continue;
            if(ansind[i][j] == N+1) ansind[i][j] = i;
            if(cmp(i, ansind[i][j]))
                ansind[i][j] = i;
        }
    }
    return;
}

bool rep[10001];
void filldp()
{
    rep[0] = true;
    dp[N+1][0] = true;
    for(int i=N; i>=1; --i)
    {
        for(int j=0; j<=K-s[i].length(); ++j)
            if(rep[j])
                dp[i][j+s[i].length()] = true;

        for(int j=0; j<=K; ++j) rep[j] |= dp[i][j];
    }
    return;
}

int main()
{
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N >> K; for(int i=1; i<=N; ++i) cin >> s[i];


    int tp = 0;
    for(int i=1; i<=N; ++i)
    {
        ind[i] = tp;
        for(int j=0; j<s[i].length(); ++j)
            bs[tp++] = s[i][j];
        bs[tp++] = ' ';
    }
    solve(tp, bs, sfx, rev, lcp);
    filldp();
    fillind();

    cout << solveans() << endl;
    return 0;
}


int ord[MAXN], nord[MAXN], cnt[MAXN], aux[MAXN];
void solve(int n, char *str, int *sfx, int *rev, int *lcp){
	int p = 1;
	memset(ord, 0, sizeof(ord));
	for(int i=0; i<n; i++){
		sfx[i] = i;
		ord[i] = str[i];
	}
	int pnt = 1;
	while(1){
		memset(cnt, 0, sizeof(cnt));
		for(int i=0; i<n; i++) cnt[ord[min(i+p, n)]]++;
		for(int i=1; i<=n || i<=255; i++) cnt[i] += cnt[i-1];
		for(int i=n-1; i>=0; i--) 
			aux[--cnt[ord[min(i+p, n)]]] = i;
		memset(cnt, 0, sizeof(cnt));
		for(int i=0; i<n; i++) cnt[ord[i]]++;
		for(int i=1; i<=n || i<=255; i++) cnt[i] += cnt[i-1];
		for(int i=n-1; i>=0; i--) 
			sfx[--cnt[ord[aux[i]]]] = aux[i];
		if(pnt == n) break;
		pnt = 1;
		nord[sfx[0]] = 1;
		for(int i=1; i<n; i++){
			if(ord[sfx[i-1]] != ord[sfx[i]] || ord[sfx[i-1] + p] != ord[sfx[i] + p]){
				pnt++;
			}
			nord[sfx[i]] = pnt;
		}
		memcpy(ord, nord, sizeof(int) * n);
		p *= 2;
	}
	for(int i=0; i<n; i++) rev[sfx[i]] = i;
	int h = 0;
	for(int i=0; i<n; i++){
		if(rev[i]){
			int prv = sfx[rev[i] - 1];
			while(str[prv + h] == str[i + h]) h++;
			lcp[rev[i]] = h;
		}
		h = max(h-1, 0);
	}
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 2020, maxk = 10100, maxs = 1000100;
using bs = bitset<maxk>;
using ii = pair<int,int>;
bs can[maxn];
string s[maxn];
char ss[maxk];
int len[maxn];
ii q[2][maxs];
int tp[2];
int main(){
	int n, k; scanf("%d %d", &n, &k);
	for(int i = 0; i < n; i++) {
		scanf("%s", ss);
		s[i] = ss;
	}
	for(int i = 0; i < n; i++) len[i] = s[i].size();
	can[n][0] = 1;
	for(int i = n - 1; i >= 0; i--) can[i] = can[i + 1] | (can[i + 1] << len[i]);
	for(int i = 0; i < n; i++) if(k - len[i] >= 0 && can[i + 1][k - len[i]]) q[0][tp[0]++] = {i, 0};
	int cur = 0;
	string res;
	for(int i = 1; i <= k; i++){
		char best = 'z';
		for(int j = 0; j < tp[cur]; j++) best = min(best, s[q[cur][j].first][q[cur][j].second]);
		res.push_back(best);
		int f = n;
		tp[cur ^ 1] = 0;
		for(int j = 0; j < tp[cur]; j++){
			int x = q[cur][j].first, y = q[cur][j].second;
			if(s[x][y] != best) continue;
			if(y + 1 == len[x]) f = min(f, x);
			else q[cur ^ 1][tp[cur ^ 1]++] = {x, y+1};
		}
		for(int j = f + 1; j < n; j++){
			if(k - i - len[j] >= 0 && can[j + 1][k - i - len[j]]){
				q[cur ^ 1][tp[cur ^ 1]++] = {j, 0};
			}
		}
		cur ^= 1;
	}
	printf("%s\n", res.c_str());
	return 0;
}

