void z_algo (int ind) {
    int org = s[ind].size();
    s[ind] += '.'; s[ind] += curr;
    int l = 0, r = 0, len = s[ind].size();
    for (int i = 1; i < len; i++) {
        if (r < i) {
            l = r = i;
            while (r < len && s[ind][r - l] == s[ind][r]) r++;
            z[i] = r - l; r--;
        } else {
            int k = i - l;
            if (z[k] < r - i + 1) {
                z[i] = z[k];
            } else {
                l = i;
                while (r < len && s[ind][r - l] == s[ind][r]) r++;
                z[i] = r - l; r--;
            }
        }
    }
    for (int i=0; i<k; i++) {
        z[i] = z[i + org + 1];
    }
}

