int cmptest(pi a, pi b) {
    if (a == b) return 0;
    if (a.s == 0) {
        if (b.s == 0 || a.f <= b.f) return 0;
        int com = min(z[sz(zz)+b.f],a.f-b.f);
        if (com == a.f-b.f) return 0;
        return cmp(cur[b.f+com],zz[com]);
    } else {
        if (b.s == 0) return -cmptest(b,a);
        int com = min(z[sz(zz)+a.f],min(b.f-a.f,sz(zz)));
        if (com == sz(zz)) return 0;
        if (com < b.f-a.f) return cmp(zz[com],cur[a.f+com]);
        com = min(z[b.f-a.f],sz(zz)-(b.f-a.f));
        if (com == sz(zz)-(b.f-a.f)) return 0;
        return cmp(zz[b.f-a.f+com],zz[com]);
    }
}

