int z[N];
void Z(string s,int len){
   z[1] = len;
   int R,mx;
   R = mx = 0;
   for(int i = 2;i <= len; ++i){
      z[i] = (i < R)?min(z[i-mx+1],R-i):0;
      while(s[i+1] == s[i+z[i]])++z[i];
      if(i+z[i] > R)R = i+z[i],mx = i;
   }
}

int main(){
