         if(j >= (int)str[i].size())dp[i][j] |= dp[i+1][j-(int)str[i].size()];
         dp[i][j] |= dp[i+1][j];
      }
   }

   cut[0] = 1;
   int siz = str[1].size();
   minch = '0';
