void make()
{
	rt[0]=1;
	for(int i=1;i<MX;i++) rt[i]=rt[i-1]*B1%M1;
}
ll get_hash(vector <PP> &vec,int L,int len)//先頭L文字分
{
	L=len-L;//後ろ先求める
	int f=lower_bound(vec.begin(),vec.end(),PP(P(L+1,-1),-1))-vec.begin()-1;
	ll ret=0;
	if(f>0) ret=vec[f-1].first.second;
	int v=vec[f].second;
	int zan=L-vec[f].first.first;
	ret+=hash1[v][zan]*rt[L-zan]%M1;
	if(ret>=M1) ret-=M1;
	//ret:先頭L文字分
	ll sum=vec[vec.size()-1].first.second;
	sum-=ret;
	if(sum<0) sum+=M1;
	return sum;
}
char get_char(vector <PP> &vec,int L,int len)//先頭L文字目
{
	L=len-L;//後ろからL文字目に直す
	int f=lower_bound(vec.begin(),vec.end(),PP(P(L+1,-1),-1))-vec.begin()-1;
	int v=vec[f].second;
	int zan=L-vec[f].first.first;
	//printf("* %d %d : %d %d\n",str[v].size(),zan,vec[f].first.first,f);
	return str[v][str[v].size()-zan];
}
