	for(int i=n-1;i>=0;i--)
	{
		for(int j=K;j>=str[i].size();j--)
		{
			int to=j-str[i].size();
			if(to>0&&dp[to].empty()) continue;
			now=dp[to];
			ll sum=to==0?0:dp[to][dp[to].size()-1].first.second;
