			if(dp[j].empty()) dp[j]=now;
			else//compare
			{
				int l=0,r=j+1;//はじめて異なる場所
				while(r-l>1)
				{
					int m=(l+r)/2;
					if(get_hash(dp[j],m,j)==get_hash(now,m,j)) l=m;
					else r=m;
				}/*
