	for (i=n; i; i--){
		for (j=m; j>=0; j--){
			bo[i][j]=bo[i+1][j];
			if (j>=a[i]) bo[i][j]|=bo[i+1][j-a[i]];
		}
	}
	ok[0]=1; len=0;
	for (i=1; i<=n; i++){
		if (!len){
			if (bo[i+1][m-a[i]]){
				len=a[i];
				for (j=1; j<=len; j++) ch[j]=s[i][j];
			}
			ok[len]=1; continue;
		}
		for (j=1; j<=a[i]; j++) s0[j]=s[i][j];
		for (j=1,cnt=a[i]; j<=len; j++) s0[++cnt]=ch[j];
		work(s0,cnt);
		memset(vis,0,sizeof(vis));
		for (j=0; j<=m; j++) if (bo[i+1][m-j]){
			if (ok[j]){
				vis[j]=1; b[j]=(node){j,0};
			}
			if (j>=a[i] && ok[j-a[i]])
				if (vis[j]) b[j]=min(b[j],(node){j-a[i],a[i]}); else{
					vis[j]=1;
					b[j]=(node){j-a[i],a[i]};
				}
		}
		q[1]=0;
		for (j=k=1; j<=m; j++) if (vis[j]){
			while (k>1 && b[j]<b[q[k]]) k--;
			if (b[j]==b[q[k]]) q[++k]=j;
