            while(R<n&&str[R-L]==str[R]) R++;
            ret[i] = R-L; R--;
        }
        else{
            int k = i-L;
            if(ret[k] <= R-i+1) ret[i] = ret[k];
            else{
                L = i;
                while(R<n&&str[R-L]==str[R]) R++;
                ret[i] = R-L; R--;
            }
        }
    }
    return ret;
}

const int NMAX = 2222;
const int KMAX = 11111;
bool ok[NMAX][KMAX];
string ans;
string in[NMAX];
bool dp[2][KMAX];

int main(){
    cin.sync_with_stdio(0);
    cout.sync_with_stdio(0);

    int N, K; cin>>N>>K;
    for(int i=1;i<=N;i++) cin>>in[i];

    ok[N][K] = true;
    for(int i=N;i>1;i--) for(int j=0;j<=K;j++) if(ok[i][j]){
        ok[i-1][j] = true;
        if(j>=in[i].size()) ok[i-1][j-in[i].size()] = true;
    }

    ans = "";
    dp[0][0] = true;
    for(int i=1;i<=N;i++){
        for(int j=0;j<=K;j++) dp[i%2][j] = false;
        vector<int> z = Z(in[i]+'$'+ans);
        int S = in[i].size();

        // find first proper index
        int f = -1;
        for(int j=0;j<ans.size();j++) if(j+S<=K && dp[(i+1)%2][j] && ok[i][j+S]){
            if(z[S+1+j] < min(S, (int)ans.size() - j)){
                if(ans[j+z[S+1+j]] > in[i][z[S+1+j]]){
                    f = j;
                    break;
                }
            }
        }

        if(f>=0){
            // slice
            string str = ans.substr(0,f) + in[i];
            vector<int> z2 = Z(in[i]+'$'+str);
            for(int j=0;j<=str.size()-S;j++) if(dp[(i+1)%2][j]){
                if(ok[i][j]) dp[i%2][j] = true;
                if(z2[S+1+j] == S) if(ok[i][j+S]) dp[i%2][j+S] = true;
            }
            ans = str;
            continue;
        }

        // check tail case
        vector<int> z2 = Z(in[i]);
        int offset = 0;
        while(offset<S &&
                (ans.size()+S-offset > K
                 || !dp[(i+1)%2][ans.size()-offset]
                 || !ok[i][ans.size()-offset+S]))
            offset++;
        if(offset>=S){
            int len = 0;
            for(int j=0;j<=ans.size();j++)
                if(dp[(i+1)%2][j] && ok[i][j]) dp[i%2][j] = true, len = j;
            ans = ans.substr(0,len);
            continue;
        }

        for(int j=offset+1;j<S;j++) if(ans.size()>=j && dp[(i+1)%2][ans.size()-j]){
            if(!ok[i][ans.size()+S-j]) continue;
            int t = z2[j-offset];
            if(t+j-offset < S){
                if(in[i][t+j-offset] < in[i][t]) offset=j;
            }
        }

        string str = ans.substr(0,ans.size()-offset) + in[i];
        vector<int> z3 = Z(in[i]+'$'+str);
        for(int j=0;j<=str.size()-S;j++) if(dp[(i+1)%2][j]){
            if(ok[i][j]) dp[i%2][j] = true;
            if(z3[S+1+j] == S) if(ok[i][j+S]) dp[i%2][j+S] = true;
        }
        ans = str;
    }

    cout<<ans;
}

#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = int(n) - 1; (i) >= 0; -- (i))
using namespace std;
template <typename X, typename T> auto vectors(X x, T a) { return vector<T>(x, a); }
template <typename X, typename Y, typename Z, typename... Zs> auto vectors(X x, Y y, Z z, Zs... zs) { auto cont = vectors(y, z, zs...); return vector<decltype(cont)>(x, cont); }

string solve(int n, int k, vector<string> const & s) {
    auto required = vectors(n + 1, k + 1, false);
    required[n][k] = true;
    REP_R (i, n) {
        int len = s[i].length();
        REP (j, k + 1) if (required[i + 1][j]) {
            required[i][j] = true;
            if (j - len >= 0) {
                required[i][j - len] = true;
            }
        }
    }

    string t;
    vector<int> cur(k + 1, -1), prv;
    cur[0] = 0;
    REP (i, n) {
        int len = s[i].length();
        cur.swap(prv);
        cur.assign(k + 1, -1);

        int modified = INT_MAX;
        int clear = INT_MAX;
        REP_R (j, k + 1) if (required[i + 1][j]) {
            if (j - len >= 0 and prv[j - len] != -1) {
                int l = j - len, r = t.length();

                if (len <= r - l and t.compare(l, len, s[i]) == 0) {  // if s[i] is a prefix of t[l, r)
                    cur[j] = j;

                } else if (r - l < len and t.compare(l, r - l, s[i], 0, r - l) == 0) {  // if t[l, r) is a prefix of s[i]
                    t += s[i].substr(r - l);
                    cur[j] = j;

                } else if (s[i].compare(0, len, t, l, r - l) < 0) {  // if you should truly replace t[l, r) with s[i]
                    for (int j1 = j - len, j2 = 0; j1 < t.length() and j2 < len; ++ j1, ++ j2) {
                        if (t[j1] != s[i][j2]) {
                            modified = j1;
                            break;
                        }
                    }
                    clear = j;
                    cur[j] = j;
                    t.erase(t.begin() + j - len, t.end());
                    t += s[i];
                }

            }
            if (prv[j] != -1 and j <= modified) {
                cur[j] = j;
            }
        }

        // execute clearing
        REP (j, k + 1) {
            if (cur[j] > clear) {
                cur[j] = -1;
            }
        }
    }
    assert (t.length() == k);
    return t;
}

int main() {
    int n, k; cin >> n >> k;
    vector<string> s(n);
    REP (i, n) cin >> s[i];
    cout << solve(n, k, s) << endl;
    return 0;
}

