{
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;i++)
	{
		scanf("%s",str+1);
		len[i]=strlen(str+1);
		p[i]=sz+1;q[i]=sz+len[i]+1;
		for (int j=1;j<=len[i];j++)
		{
			ha[p[i]+j]=ha[p[i]+j-1]*27+str[j]-'a'+1;
			a[p[i]+j]=str[j]-'a';
		}
		sz=q[i];
	}
	for (int i=1;i<=n;i++) f[i]=i;
	sort(f+1,f+n+1,cmp);
	bit[0]=1;
	for (int i=n;i>=1;i--) arr[i]=bit<<len[i],bit|=bit<<len[i];
	solve(1,m);
	return 0;
}

