   }
   fill(f,0); f[n+1][k] = 1;
   nfr(i,n,1,1){
      nfr(j,k,0,1){
         f[i][j] |= f[i+1][j];
         if(j+SZ(str[i]) <= k)f[i][j] |= f[i+1][j+SZ(str[i])];
      }
   }

   cut[0] = 1;
   int curp;
   fr(i,1,n,1){
      q1.clear();
      string qry = " "+str[i]+" "+curs;
      int cz = SZ(curs);
      int sz = SZ(str[i]);
      z_algo(str[i].size()+1,qry);
