      nfr(j,k,0,1){
         if(j+sz > k || !cut[j] || !f[i+1][j+SZ(str[i])])continue ;
         if(curp == -1){
            if(exk[j+1] == sz)q1.pb(j+sz);
            else if(exk[j+1] == cz-j)q1.pb(j+sz),curp = j;
            else {
               if(str[i][exk[j+1]] < curs[j+exk[j+1]]){
                  curp = j; flag = true;
               }
            }
         } else {
            if(exk[j+1] == curp-j){
               if(z[curp-j+1] == (sz-curp+j))q1.pb(j+sz);
               else {
                  if(str[i][curp-j+z[curp-j+1]] < str[i][z[curp-j+1]]){
                     q1.clear(); curp = j; flag = true;
                  }
               }
