string s[2005];
unordered_map<int,unordered_map<int,string> >dp;
struct Double_Ended_Queue
{
	int Q[2005],h=1,l=0;
	inline bool empty()
		{
			return h>l;
		}
	inline int front()
		{
			return Q[h];
		}
	inline int back()
		{
			return Q[l];
		}
	inline void pop_back()
		{
			--l;
		}
	inline void push_back(int x)
		{
			Q[++l]=x;
		}
}q[10005];
int main()
{
