            Slen[i] = S[i].length() ;
        }
        DP = new int[N*10000] ; // N<1000, K<10000
        DPString = new <String> ArrayList();
        zz[0] ='z'+1 ;
        zzz = new String(zz) ;

        System.out.println(Solve(0, K)) ;
    }

    static String Solve(int pos, int len) {
        String tmp1 = zzz ;
        String tmp2 = zzz ;
        if (pos >= N) {
            return "" ;
        }
        if (len < 0) {
            return "" ;
        }
        if (DP[pos*10000+len-1]!=0) return DPString.get(DP[pos*10000+len-1]) ;
        for (int i=pos; i < N ; i++) {
            if (Slen[i]<len) {
                tmp2=S[i]+Solve(i+1, len - Slen[i]) ;
                if (tmp2.length() != len) tmp2=zzz ;
            } else if (Slen[i] == len) {
                tmp2=S[i] ;
            } 
            if (tmp1.compareTo(tmp2)>0) tmp1=tmp2 ;
        }
            if (tmp1.equals(zzz)) tmp1="" ;
            DPString.add(tmp1) ;
            DP[pos*10000+len-1] = DPString.size()-1 ;
        return tmp1 ;
    }

    static String getOneLine() {
        BufferedReader br = new BufferedReader( new InputStreamReader(System.in)) ;
        String line  ;
        while(true) {
            try {
                line = br.readLine();
            } catch (IOException ex) {
                line = "" ;
            }
            if (line.equals(""))  ; // continue ;
            else break ;
        }
        return line.trim() ;        
    }    

}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    static ArrayList<String> arr = new ArrayList<>();
    static String[][] dpTable;
    static boolean[][] used;
    static void dp(int i, int k){
        String entry_in_table;
        if(i == arr.size() && k == 0)
            entry_in_table = "";
        else if(k == 0){
            entry_in_table = "";
        }
        else if(i == arr.size())
            entry_in_table = null;
        else {
            String s = arr.get(i);

            if(used[i][k]){
                return;
            }

            if(s.length() > k){
                dp(i+1, k);
                entry_in_table = dpTable[i+1][k];
            } else {
                dp(i + 1, k);
                dp(i + 1, k-s.length());
                String s1 = dpTable[i+1][k];
                String s2 = dpTable[i+1][k-s.length()];

                if (s1 == null && s2 == null){
                    entry_in_table =  null;
                }else if(s1 == null)
                    entry_in_table = s + s2;
                else if(s2 == null)
                    entry_in_table = s1;
                else if(s1.compareTo(s + s2) < 0){
                    entry_in_table = s1;
                } else{
                    entry_in_table = s + s2;
                }
            }
        }
        dpTable[i][k] = entry_in_table;
        used[i][k] = true;

    }

    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        int n = kb.nextInt();
        int k = kb.nextInt();
        used = new boolean[n+1][k+1];
        dpTable = new String[n+1][k+1];
        for(int i=0; i<n; i++){
            for(int j=0; j<k+1; j++){
                dpTable[i][j] = null;
            }
        }
        for(int i =0; i< n; i++){
            arr.add(kb.next());
        }
        dp(0, k);
        System.out.println(dpTable[0][k]);
    }
}

