            return ""; 
        }

        String answer = null;

        if(current.length() < K){
            if(dp[index][current.length()] == null){
                dp[index][current.length()] = recurse(index+1,current);
            }

            if(dp[index][current.length()] != ""){
                answer = dp[index][current.length()];
            }

        }

        String toAdd = strings[index];


        if(current.length() + toAdd.length() <= K){
