                if(answer == null || dp[index][current.length()] == null || (dp[index][current.length()+toAdd.length()].compareTo(dp[index][current.length()]) < 0)){
                    answer = dp[index][current.length()+toAdd.length()];
                }
            }

        }

        return (answer!=null)?answer:"";

    }


