using System;
using System.Linq;
using System.Collections.Generic;
using Debug = System.Diagnostics.Debug;
using StringBuilder = System.Text.StringBuilder;
using System.Numerics;
using Point = System.Numerics.Complex;
using Number = System.Int32;
namespace Program
{
    public class Solver
    {
        public void Solve()
        {

            var n = sc.Integer();
            var k = sc.Integer();
            var back = new int[k + 1];
            for (int i = 0; i < k; i++)
                back[i] = -1;
            back[k] = n;
            var s = sc.Scan(n);
            for (int i = n - 1; i >= 0; i--)
            {
                for (int j = 0; j <= k; j++)
                    if (back[j] != -1 && j - s[i].Length >= 0) back[j - s[i].Length] = Math.Max(back[j - s[i].Length], i);
            }
            SuffixArray sa;
            {
                var sb = new StringBuilder();
                for (int i = 0; i < n; i++)
                {
                    sb.Append(s[i]);
                    sb.Append((char)('z' + 1));
                }
                sa = new SuffixArray(sb.ToString());
                sa.Init();
                sa.BuildLCP();
            }
            var dp = new bool[k + 1];
            dp[0] = true;
            var best = Enumerate(k, x => '|');

            var sum = 0;
            for (int i = 0; i < n; i++)
            {
                Debug.WriteLine(best.AsString());
                var len = s[i].Length;
                var zs = StringEx.ZAlgorithm(string.Concat(s[i], "$", new string(best)));
                var npos = -1;
                var next = Enumerate(k + 1, x => -100);
                for (int j = k - 1; j >= 0; j--)
                {
                    if (j + len > k) continue;
                    if (!dp[j]) continue;
                    if (back[j + len] <= i) continue;
                    var lcp = zs[len + 1 + j];
                    if (j + lcp != k && lcp != s[i].Length && best[j + lcp] > s[i][lcp])
                    {
                        npos = j;
                        next[j + len] = npos;
                        continue;
                    }
                    if (j + lcp != k && lcp != s[i].Length && best[j + lcp] < s[i][lcp]) continue;
                    if (npos != -1)
                    {
                        if (j + len <= npos)
                        {
                            npos = j;
                            next[j + len] = npos;
                        }
                        else
                        {
                            var lcp2 = sa.GetLCP(sum, sum + npos - j);
                            if (npos - j + lcp2 == len) continue;
                            else if (s[i][lcp2] > s[i][npos - j + lcp2])
                            {
                                npos = j;
                                next[j + len] = npos;
                            }
                        }
                    }
                }
                if (npos != -1)
                {
                    for (int j = 0; j < len; j++)
                        best[npos + j] = s[i][j];
                    for (int j = npos + 1; j < k; j++)
                        dp[j] = false;
                    for (int j = 0; j <= k; j++)
                        if (next[j] == npos) dp[j] |= true;
                }
                sum += len + 1;
            }
            IO.Printer.Out.WriteLine(best);
        }
        public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());
        static T[] Enumerate<T>(int n, Func<int, T> f) { var a = new T[n]; for (int i = 0; i < n; ++i) a[i] = f(i); return a; }
        static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
    }
}

