var ok []bool
var ans []rune
func main() {
  fmt.Scan(&n,&k)
  s = make([][]rune,n)
  for i:=0;i<n;i++ {
    var tmp string
    fmt.Scan(&tmp)
    s[i] = []rune(tmp)
  }
  preprocess()
  process()
  fmt.Println(string(ans))
}
func preprocess() {
  dp = make([][]bool,n+1)
  for i:=0;i<n+1;i++ { dp[i] = make([]bool,k+1) }
  dp[n][0] = true
  for i:=n-1;i>=0;i-- {
    l := len(s[i])
    for j:=0;j<=k;j++ {
      dp[i][j] = dp[i+1][j]
      if j >= l { dp[i][j] = dp[i][j] || dp[i+1][j-l] }
    }
  }
}
func process() {
  ans = make([]rune,k)
  for i:=0;i<k;i++ { ans[i] = '{' }
  ok = make([]bool,k+1)
  ok[0] = true
  for i:=0;i<n;i++ {
    l := len(s[i])
    x,d := -1,-1
    z := z_algorithm(string(s[i])+"."+string(ans))
    z = z[l+1:]
    for j:=0;j<=k-l;j++ {
      if !(ok[j] && dp[i+1][k-l-j]) { continue }
      if z[j] < l && j+z[j] < k && s[i][z[j]] < ans[j+z[j]] {
        x = j
        break
      }
    }
    if x < 0 { continue }
    y := x+l
    for j:=0;j<l;j++ {
      if d < 0 && ans[x+j] != s[i][j] { d = x+j }
      ans[x+j] = s[i][j]
    }
    for j:=y;j<k;j++ { ans[i] = '{' }
    for j:=d+1;j<=k;j++ { ok[j] = false }
    ok[y] = true
  }
}
func z_algorithm(s string) []int {
  n := len(s)
  z := make([]int,n)
  z[0] = n
  for i,j:=1,0;i<n; {
    for i+j < n && s[j:j+1] == s[i+j:i+j+1] { j++ }
    z[i] = j
    if j == 0 { i++;continue }
    k := 1
    for ;i+k<n&&k+z[k]<j;k++ { z[i+k] = z[k] }
    i,j = i+k,j-k
  }
  return z
}

