                        ++b;
                        bi = 0;
                    }
                    if (S[ns[a]][ai] < S[dp[j + len][b]][bi]) {
                        upd = true;
                        break;
                    } else if (S[ns[a]][ai] > S[dp[j + len][b]][bi]) {
                        break;
                    }
                }
                if (upd) {
