import sys

sys.setrecursionlimit(2020)


def make_best(s, best, path):
    candidate = ''.join([s[i] for i in path])
    if best is None or candidate < best:
        return candidate
    return best


def dfs(n, k, s, l, dp, i, path, t, best):

    path.append(i)
    t += l[i]
    if t == k:
        best = make_best(s, best, path)
        path.pop()
        return best
    elif k < t:
        path.pop()
        return best
    lk = k - t
    for j in range(i + 1, n):
        if dp[j][lk]:
            best = dfs(n, k, s, l, dp, j, path, t, best)
    path.pop()
    return best


def solve(n, k, s):

    l = [len(si) for si in s]

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[n][0] = 1
    for i in range(n - 1, -1, -1):
        li = l[i]
        lk = k - li
        for j in range(k + 1):
            if dp[i + 1][j]:
                dp[i][j] = 1
                if j <= lk:
                    dp[i][j + li] = 1

    order = [i for i in range(n)]
    order.sort(key = lambda i: s[i])

    order2 = []
    i = 0
    while i < n:
        j = order[i]
        a = [j]
        order2.append(a)
        sj = s[j]
        lj = l[j]
        ni = i + 1
        while ni < n:
            nj = order[ni]
            if lj <= l[nj]:
                snj = s[nj]
                if snj[:lj] == sj:
                    a.append(nj)
                    ni += 1
                else:
                    break
            else:
                break
        a.sort(reverse = True)
        i = ni

    best = None
    for a in order2:
        for i in a:
            if dp[i][k]:
                path = []
                best = dfs(n, k, s, l, dp, i, path, 0, best)
        if best is not None:
            break

    return best


def main():
    n, k = input().split()
    n = int(n)
    k = int(k)
    s = []
    for _ in range(n):
        si = input()
        s.append(si)

    print(solve(n, k, s))


if __name__ == '__main__':
    main()

