/*
 * Z algorithm. Calculates an array a[i] = |lcp(s, s[i...|s|])|,
 * where s is the given string.
 * If n = s.length(), the returned array has length n + 1.
 * E.g. z_algorithm("ababa") = {5, 0, 3, 0, 1, 0}
 * Reference: http://snuke.hatenablog.com/entry/2014/12/03/214243
 * Verified by: AtCoder ARC055-C (http://arc055.contest.atcoder.jp/submissions/1061771)
 */
fn z_algorithm<T: PartialEq>(s: &[T]) -> Vec<usize> {
    let n = s.len();
    let mut ret = vec![0; n + 1];
    ret[0] = n;
    let mut i = 1; let mut j = 0;
    while i < n {
        while i + j < n && s[j] == s[i + j] { j += 1; }
        ret[i] = j;
        if j == 0 { i += 1; continue; }
        let mut k = 1;
        while i + k < n && k + ret[k] < j {
            ret[i + k] = ret[k];
            k += 1;
        }
        i += k; j -= k;
    }
    ret
}

fn calc_poss(s: &[Vec<char>], k: usize) -> Vec<Vec<bool>> {
    let n = s.len();
    let mut poss = vec![vec![false; k + 1]; n + 1];
    poss[n][0] = true;
    for i in (0 .. n).rev() {
        let len = s[i].len();
        for j in 0 .. k - len + 1 {
            poss[i][j + len] |= poss[i + 1][j];
        }
        for j in 0 .. k + 1 {
            poss[i][j] |= poss[i + 1][j];
        }
    }
    poss
}

fn solve() {
    use std::cmp::Ordering::*;
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        k: usize,
        s: [chars; n],
    }
    let poss = calc_poss(&s, k);
    let mut cs = vec![Vec::new(); n + 1];
    let mut dp = vec![vec![false; k + 1]; n + 1];
    dp[0][0] = true;
    for i in 0 .. n {
        let len = s[i].len();
        // Compares cs[i][..j] + s[i] and the current cs[i + 1].
        let cmps = |cs: &[Vec<char>], j| {
            // TODO optimize
            assert!(j <= cs[i].len());
            let mut x = cs[i][..j].to_vec();
            let mut t = s[i].clone();
            x.append(&mut t);
            let minlen = min(x.len(), cs[i + 1].len());
            let result = x[..minlen].cmp(&cs[i + 1][..minlen]);
            if (result, minlen < x.len()) == (Equal, true) {
                Less // needs updating
            } else {
                result
            }
        };
        // Compares cs[i][..j] and the current cs[i + 1].
        let cmp = |cs: &[Vec<char>], j| {
            // TODO optimize
            assert!(j <= cs[i].len());
            let minlen = min(j, cs[i + 1].len());
            let result = cs[i][..minlen].cmp(&cs[i + 1][..minlen]);
            if (result, minlen < j) == (Equal, true) {
                Less
            } else {
                result
            }
        };
        // get min
        for j in 0 .. k + 1 {
            if !poss[i + 1][k - j] || !dp[i][j] { continue; }
            if cmp(&cs, j) == Less {
                cs[i + 1] = cs[i].clone();
            }
        }
        for j in 0 .. k - len + 1 {
            if !poss[i + 1][k - j - len] || !dp[i][j] { continue; }
            if cmps(&cs, j) == Less {
                cs[i + 1] = cs[i][..j].to_vec();
                let mut t = s[i].clone();
                cs[i + 1].append(&mut t);
            }
        }
        // update dp
        for j in 0 .. k + 1 {
            if !poss[i + 1][k - j] || !dp[i][j] { continue; }
            dp[i + 1][j] = cmp(&cs, j) != Greater;
        }
        for j in 0 .. k - len + 1 {
            if !poss[i + 1][k - j - len] || !dp[i][j] { continue; }
            dp[i + 1][j + len] = cmps(&cs, j) != Greater;
        }
    }
    /*
    eprintln!("dp = {:?}", dp);
    for v in cs.iter() {
        eprintln!("{}", v.clone().into_iter().collect::<String>());
    }
     */
    puts!("{}\n", cs[n][..k].iter().cloned().collect::<String>());
}

