fn compare(z: &Vec<usize>, last: &Vec<u8>, next: &Vec<u8>, a: usize, b: usize) -> i32 {
    if a == INF {
        // last vs last[0,b] + next
        let idx = next.len() + b;
        if idx == z.len() {
            return 0;
        }
        if b + z[idx] >= last.len() {
            return 0;
        }
        if z[idx] >= next.len() {
            return -1;
        }
        return if next[z[idx]] < last[b+z[idx]] { 1 } else { -1 };
    }

    if a == b {
        return 0;
    }
    let n = z.len();
    let diff = b-a;
    if z[n-diff] == diff {
        if a + next.len() <= b {
            return 0;
        }
        let l = a + next.len() - b;
        if z[next.len()-l] >= l {
            return 0;
        }
        let zn = z[next.len()-l];
        return if next[zn] < next[next.len()-l+zn] { 1 } else { -1 } ;
    } else {
        let zn = z[n-diff];
        return if last[a+zn] < next[zn] { 1 } else { -1 };
    }
}

