const INF: usize = 1000000;

fn main() {
    let (n, k): (usize, usize) = read();
    let s: Vec<String> = readn(n);
    let s: Vec<Vec<u8>> = s.into_iter().map(|s| s.into_bytes()).collect();

    for ref si in &s {
        println!("{:?}", z(&si));
    }

    let mut can_make = vec![vec![0; k+1]; n+1];
    can_make[n][k] = 1;

    for i in (0..n).rev() {
        let f = s[i].len();
        for j in 0..k+1 {
            if can_make[i+1][j] == 1 {
                if j >= f {
                    can_make[i][j-f] = 1;
                }
                can_make[i][j] = 1;
            }
        }
    }
    can_make[0][0] = 2;
    for i in 0..n {
        let f = s[i].len();
        for j in 0..k+1 {
            if can_make[i][j] == 2 {
                if can_make[i+1][j] == 1 {
                    can_make[i+1][j] = 2;
                }
                if j+f <= k && can_make[i+1][j+f] == 1 {
                    can_make[i+1][j+f] = 2;
                }
            }
        }
    }

    let mut last: Vec<u8> = vec![];
    for i in 1..n+1 {
        // println!("===");
        // println!("{:?}", can_make[i-1]);
        // println!("{:?}", can_make[i]);

        let f = s[i-1].len();
        let mut cmp = s[i-1].clone();
        cmp.append(&mut last.clone());
        let z = z(&cmp);

        let mut best_size = INF;
        // let mut best_size = if can_make[i][f] == 2 { 0 } else { INF };
        for j in 0..k+1 {
            if can_make[i][j] != 2 {
                continue
            }
            if j >= f && can_make[i-1][j-f] == 2 {
                let rst = compare(&z, &last, &s[i-1], best_size, j-f);
                // println!("{} {} {} {}", i, best_size, j-f, rst);
                if rst >= 0 {
                    best_size = j-f;
                }
                if rst == -1 {
                    // println!("{} {}", i, j);
                    can_make[i][j] = 1;
                }
            } else if j >= f {
                // println!("{} {}", i, j);
                can_make[i][j] = 1;
            }
        }

        if best_size < INF {
            let mut next = vec![];
            for i in 0..best_size {
                next.push(last[i]);
            }
            for &c in &s[i-1] {
                next.push(c);
            }
            last = next;
        }
        // println!("{} {:?}", i, last);
    }

    for i in 0..k {
        print!("{}", last[i] as char);
    }
    println!("");
}

// z := next + last
fn compare(z: &Vec<usize>, last: &Vec<u8>, next: &Vec<u8>, a: usize, b: usize) -> i32 {
    if a == INF {
        // last vs last[0,b] + next
        let idx = next.len() + b;
        if idx == z.len() {
            return 0;
        }
        if b + z[idx] >= last.len() {
            return 0;
        }
        if z[idx] >= next.len() {
            return -1;
        }
        return if next[z[idx]] < last[b+z[idx]] { 1 } else { -1 };
    }

    if a == b {
        return 0;
    }
    let n = z.len();
    let diff = b-a;
    if z[n-diff] == diff {
        if a + next.len() <= b {
            return 0;
        }
        let l = a + next.len() - b;
        if z[next.len()-l] >= l {
            return 0;
        }
        let zn = z[next.len()-l];
        return if next[zn] < next[next.len()-l+zn] { 1 } else { -1 } ;
    } else {
        let zn = z[n-diff];
        return if last[a+zn] < next[zn] { 1 } else { -1 };
    }
}

// (z[idx] := longest common prefix of ([idx,n), [0,n))
fn z(a: &Vec<u8>) -> Vec<usize> {
    let n = a.len();
    let mut z = vec![0; n];
    if n == 0 {
        return z;
    }
    z[0] = n;
    let mut l = 0;
    let mut r = 0;
    for i in 1..n {
        if i > r {
            l = i;
            r = i;
            while r < n && a[r-l] == a[r] {
                r += 1;
            }
            z[i] = r - l;
            r -= 1;
        } else {
            let k = i-l;
            if z[k] < r-i+1 {
                z[i] = z[k];
            } else {
                let l = i;
                while r < n && a[r-l] == a[r] {
                    r += 1;
                }
                z[i] = r-l;
                r -= 1;
            }
        }
    }
    z
}

