fn is_larger(s: &Vec<u8>, t: &Vec<u8>, j: usize) -> bool {
    let mut ti = 0;
    for i in j-t.len()..j {
        if ti == t.len() {
            break
        }
        if i >= s.len() {
            return true
        }

        if s[i] != t[ti] {
            return t[ti] < s[i];
        }
        ti += 1;
    }
    false
}

