const INF: usize = 1000000;

fn main() {
    let (n, k): (usize, usize) = read();
    let s: Vec<String> = readn(n);
    let s: Vec<Vec<u8>> = s.into_iter().map(|s| s.into_bytes()).collect();

    let mut can_make = vec![vec![false; k+1]; n+1];
    can_make[n][k] = true;

    for i in (0..n).rev() {
        let f = s[i].len();
        for j in 0..k+1 {
            if can_make[i+1][j] {
                if j >= f {
                    can_make[i][j-f] = true;
                }
                can_make[i][j] = true;
            }
        }
    }


    let mut last: Vec<u8> = vec![];
    for i in 1..n+1 {
        // println!("===");
        // println!("{:?}", can_make[i-1]);
        // println!("{:?}", can_make[i]);

        let f = s[i-1].len();
        let mut cmp = s[i-1].clone();
        cmp.append(&mut last.clone());
        let z = z(&cmp);

        let mut best_size = INF;
        // let mut best_size = if can_make[i][f] == 2 { 0 } else { INF };
        for j in f..k+1 {
            if can_make[i][j] && can_make[i-1][j-f] {
                let rst = compare(&z, &last, &s[i-1], best_size, j-f);
                if rst >= 0 {
                    best_size = j-f;
                }
            }
        }

        if best_size < INF {
            let mut next = vec![];
            for i in 0..best_size {
                next.push(last[i]);
            }
            for &c in &s[i-1] {
                next.push(c);
            }

            let nl = next.len();
            for j in 0..k+1 {
                if !can_make[i][j] {
                    continue;
                }
                if j > nl {
                    can_make[i][j] = false;
                } else if j < nl {
                    let lastn = last.len();
                    let mut z = vec![b'~'];
                    if can_make[i-1][j] {
                        z = last[0..min(lastn, j)].iter().cloned().collect();
                    }
                    if j >= f && can_make[i-1][j-f] {
                        let mut zz: Vec<u8> = last[0..min(lastn, j-f)].iter().cloned().collect();
                        let mut f = s[i-1].clone();
                        zz.append(&mut f);
                        if zz < z {
                            z = zz;
                        }
                    }
                    if next < z {
                        can_make[i][j] = false;
                    }
                }
            }
            last = next;
        } else {
            for j in 0..k+1 {
                can_make[i][j] &= can_make[i-1][j];
            }
        }
        // println!("{} {:?}", i, last);
    }

    for i in 0..k {
        print!("{}", last[i] as char);
    }
    println!("");
}

// z := next + last
fn compare(z: &Vec<usize>, last: &Vec<u8>, next: &Vec<u8>, a: usize, b: usize) -> i32 {
    if b > last.len() {
        return -1;
    }

    if a == INF {
        // last vs last[0,b] + next
        let idx = next.len() + b;
        if idx >= z.len() {
            return 0;
        }
        if b + z[idx] >= last.len() {
            return 0;
        }
        if z[idx] >= next.len() {
            return -1;
        }
        return if next[z[idx]] < last[b+z[idx]] { 1 } else { -1 };
    }

    if a == b {
        return 0;
    }
    let n = z.len();
    let nl = next.len();
    let diff = b-a;
    if z[nl+a] >= diff {
        if a + next.len() <= b {
            return 0;
        }
        let l = a + next.len() - b;
        if z[next.len()-l] >= l {
            return 0;
        }
        let zn = z[next.len()-l];
        return if next[zn] < next[next.len()-l+zn] { 1 } else { -1 } ;
    } else if z[nl+a] == nl {
        return 0;
    } else {
        let zn = z[nl+a];
        return if last[a+zn] < next[zn] { 1 } else { -1 };
    }
}

// (z[idx] := longest common prefix of ([idx,n), [0,n))
fn z(a: &Vec<u8>) -> Vec<usize> {
    let n = a.len();
    let mut z = vec![0; n];
    if n == 0 {
        return z;
    }
    z[0] = n;
    let mut l = 0;
    let mut r = 0;
    for i in 1..n {
        if i > r {
            l = i;
            r = i;
            while r < n && a[r-l] == a[r] {
                r += 1;
            }
            z[i] = r - l;
            r -= 1;
        } else {
            let k = i-l;
            if z[k] < r-i+1 {
                z[i] = z[k];
            } else {
                let l = i;
                while r < n && a[r-l] == a[r] {
                    r += 1;
                }
                z[i] = r-l;
                r -= 1;
            }
        }
    }
    z
}

