/*
 * Z algorithm. Calculates an array a[i] = |lcp(s, s[i...|s|])|,
 * where s is the given string.
 * If n = s.length(), the returned array has length n + 1.
 * E.g. z_algorithm("ababa") = {5, 0, 3, 0, 1, 0}
 * Reference: http://snuke.hatenablog.com/entry/2014/12/03/214243
 * Verified by: AtCoder ARC055-C (http://arc055.contest.atcoder.jp/submissions/1061771)
 */
fn z_algorithm<T: PartialEq>(s: &[T]) -> Vec<usize> {
    let n = s.len();
    let mut ret = vec![0; n + 1];
    ret[0] = n;
    let mut i = 1; let mut j = 0;
    while i < n {
        while i + j < n && s[j] == s[i + j] { j += 1; }
        ret[i] = j;
        if j == 0 { i += 1; continue; }
        let mut k = 1;
        while i + k < n && k + ret[k] < j {
            ret[i + k] = ret[k];
            k += 1;
        }
        i += k; j -= k;
    }
    ret
}

fn calc_poss(s: &[Vec<char>], k: usize) -> Vec<Vec<bool>> {
    let n = s.len();
    let mut poss = vec![vec![false; k + 1]; n + 1];
    poss[n][0] = true;
    for i in (0 .. n).rev() {
        let len = s[i].len();
        for j in 0 .. k - len + 1 {
            poss[i][j + len] |= poss[i + 1][j];
        }
        for j in 0 .. k + 1 {
            poss[i][j] |= poss[i + 1][j];
        }
    }
    poss
}

fn solve() {
    use std::cmp::Ordering::*;
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    macro_rules! debug {
        ($($format:tt)*) => ();//(eprintln!($($format)*));
    }
    input! {
        n: usize,
        k: usize,
        s: [chars; n],
    }
    let poss = calc_poss(&s, k);
    let mut cs = vec![Vec::new(); n + 1];
    let mut dp = vec![vec![false; k + 1]; n + 1];
    dp[0][0] = true;
    for i in 0 .. n {
        let len = s[i].len();
        let mut css = s[i].clone();
        css.extend_from_slice(&cs[i]);
        let zarr = z_algorithm(&css);
        // cs[i + 1] is implicitly represented by
        // cs[i][..cs_len] + if s_appended { s[i] } else { "" }.
        let mut s_appended = false;
        let mut cs_len: usize = 0;
        // compares css[a .. a + blen] and css[b .. b + blen].
        // If one is a prefix of the other, the longer one is smaller.
        // Either a or b must be 0.
        debug!("css = {:?}", css);
        let cmp_slice = |a: usize, alen: usize, b: usize, blen: usize| {
            let minlen = min(alen, blen);
            if a == 0 {
                let common_len = zarr[b];
                debug!("com = {}", common_len);
                debug!("{} {} {} {}", a, alen, b, blen);
                return if minlen <= common_len {
                    (blen.cmp(&alen), true) // longer is smaller
                } else {
                    (css[a + common_len].cmp(&css[b + common_len]), false)
                }
            }
            if b == 0 {
                let common_len = zarr[a];
                return if minlen <= common_len {
                    (blen.cmp(&alen), true) // longer is smaller
                } else {
                    (css[a + common_len].cmp(&css[b + common_len]), false)
                }
            }
            unreachable!()
        };
        // Compares cs[i][..j] + s[i] and the current cs[i + 1].
        // If one is a prefix of the other, the longer one wins (is smaller).
        let cmps = |cs_len: usize, s_appended: bool, j: usize| {
            if s_appended {
                if j > cs_len + len {
                    return cmp_slice(len + cs_len, j - cs_len, 0, len)
                }
                if cs_len > j + len {
                    return cmp_slice(0, len, len + j, cs_len - j)
                }
                if j == cs_len { return (Equal, true) }
                if j > cs_len {
                    let res = cmp_slice(len + cs_len, j - cs_len, 0, j - cs_len);
                    if res.0 != Equal { return res }
                    return cmp_slice(0, len, j - cs_len, len - (j - cs_len))
                }
                let res = cmp_slice(0, cs_len - j, len + j, cs_len - j);
                if res.0 != Equal { return res }
                return cmp_slice(cs_len - j, len - (cs_len - j), 0, len)
            }
            if cs_len <= j {
                return (Less, true)
            }
            cmp_slice(0, len, len + j, cs_len - j)
        };
        // Compares cs[i][..j] and the current cs[i + 1].
        let cmp = |cs_len: usize, s_appended: bool, j| {
            if !s_appended {
                return (cs_len.cmp(&j), true)
            }
            if j <= cs_len {
                return (Greater, true)
            }
            cmp_slice(len + cs_len, j - cs_len, 0, len)
        };
        // get min
        for j in 0 .. k + 1 {
            if !poss[i + 1][k - j] || !dp[i][j] { continue; }
            if cmp(cs_len, s_appended, j).0 == Less {
                debug!("{} {} plus chmin: {:?} {} -> {:?} {}", i, j,
                       &cs[i][..cs_len], s_appended,
                       &cs[i][..j], false);
                cs_len = j;
                s_appended = false;
            }
        }
        for j in 0 .. k - len + 1 {
            if !poss[i + 1][k - j - len] || !dp[i][j] { continue; }
            let res = cmps(cs_len, s_appended, j);
            debug!("cmp {:?} + {:?} cmp {:?} + {} = {:?}",
                   &cs[i][..j], &s[i], &cs[i][..cs_len], s_appended, res);
            if cmps(cs_len, s_appended, j).0 == Less {
                debug!("{} {} plus chmin: {:?} {} -> {:?} {}", i, j,
                       &cs[i][..cs_len], s_appended,
                       &cs[i][..j], true);
                cs_len = j;
                s_appended = true;
            }
        }
        // update dp
        for j in 0 .. k + 1 {
            if !poss[i + 1][k - j] || !dp[i][j] { continue; }
            dp[i + 1][j] |= cmp(cs_len, s_appended, j).1;
        }
        for j in 0 .. k - len + 1 {
            if !poss[i + 1][k - j - len] || !dp[i][j] { continue; }
            dp[i + 1][j + len] |= cmps(cs_len, s_appended, j).1;
        }
        cs[i + 1] = cs[i][..cs_len].to_vec();
        if s_appended {
            cs[i + 1].extend_from_slice(&s[i]);
        }
    }

    debug!("dp = {:?}", dp);
    for v in cs.iter() {
        debug!("{}", v.clone().into_iter().collect::<String>());
    }
    // */
    puts!("{}\n", cs[n][..k].iter().cloned().collect::<String>());
}

