    available[0][0] = 1;
    for i in 0..n {
        let l = s[i].len();
        for j in 0..k+1 {
            if available[i][j] == 0 {
                continue;
            }
            available[i+1][j] = 1;
            if j + l <= k {
                available[i+1][j+l] = 1;
            }
        }
    }

    available[n][k] = 2;
    for i in (0..n).rev() {
        let l = s[i].len();
        for j in 0..k+1 {
            if available[i][j] == 1 {
                if available[i+1][j] == 2 || (j + l <= k && available[i+1][j+l] == 2) {
                    available[i][j] = 2;
                }
            }
        }
    }

    let mut prev: Vec<u8> = vec![];
    prev.push('~' as u8);

    let mut cut: Vec<bool> = vec![false; k+1];
    cut[0] = true;

    for i in 0..n {
        let l = s[i].len();
        let mut largest = prev.len() + 1;
        for j in 0..k+1 {
            if available[i+1][j] != 2 {
                continue
            }

            let left = j >= l && available[i][j-l] == 2 && cut[j-l];
            if left {
                if is_larger(&prev, &s[i], largest, j-l) {
                    largest = j-l;
                }
            }
        }

        if largest <= prev.len() {
            let mut next: Vec<u8> = vec![];
            let mut next_cut: Vec<bool> = vec![false; k+1];
            for i in 0..largest {
                next.push(prev[i]);
                next_cut[i] = cut[i];
            }
            next_cut[largest] = true;
            for &c in &s[i] {
                next.push(c);
            }
            next_cut[next.len()] = true;

            prev = next;
            cut = next_cut;
        }

//        println!("{}", i);
