// compare
//   A = s[0..j) and
//   B = s[0..j-t.len()) + t
// returns true if B < A.
fn is_larger(s: &Vec<u8>, t: &Vec<u8>, t1: usize, t2: usize) -> bool {
    let mut wo2: Vec<u8> = vec![];
    for i in 0..t2 {
        wo2.push(s[i]);
    }
    for &c in t {
        wo2.push(c);
    }

    let mut wo: Vec<u8> = vec![];

    if t1 == s.len() + 1 {
        for &c in s {
            wo.push(c);
        }
    } else {
        for i in 0..t1 {
            wo.push(s[i]);
        }
        for &c in t {
            wo.push(c);
        }
    }

    for i in 0..min(wo.len(), wo2.len()) {
        if wo[i] != wo2[i] {
            return wo2[i] < wo[i];
        }
    }
    return true;
}

