            k += 1;
        }
        i += k; j -= k;
    }
    ret
}

fn calc_poss(s: &[Vec<char>], k: usize) -> Vec<Vec<bool>> {
    let n = s.len();
    let mut poss = vec![vec![false; k + 1]; n + 1];
    poss[n][0] = true;
    for i in (0 .. n).rev() {
        let len = s[i].len();
        for j in 0 .. k - len + 1 {
            poss[i][j + len] |= poss[i + 1][j];
        }
        for j in 0 .. k + 1 {
            poss[i][j] |= poss[i + 1][j];
        }
    }
    poss
}

fn solve() {
    use std::cmp::Ordering::*;
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        k: usize,
        s: [chars; n],
    }
    let poss = calc_poss(&s, k);
    let mut cs = vec![Vec::new(); n + 1];
    let mut dp = vec![vec![false; k + 1]; n + 1];
    dp[0][0] = true;
    for i in 0 .. n {
        let len = s[i].len();
        // Compares cs[i][..j] + s[i] and the current cs[i + 1].
        let cmps = |cs: &[Vec<char>], j| {
            // TODO optimize
            assert!(j <= cs[i].len());
            let mut x = cs[i][..j].to_vec();
            x.extend_from_slice(&s[i]);
            let minlen = min(x.len(), cs[i + 1].len());
            let result = x[..minlen].cmp(&cs[i + 1][..minlen]);
            if (result, minlen < x.len()) == (Equal, true) {
                Less // needs updating
            } else {
                result
            }
        };
        // Compares cs[i][..j] and the current cs[i + 1].
        let cmp = |cs: &[Vec<char>], j| {
            // TODO optimize
            assert!(j <= cs[i].len());
            let minlen = min(j, cs[i + 1].len());
            let result = cs[i][..minlen].cmp(&cs[i + 1][..minlen]);
            if (result, minlen < j) == (Equal, true) {
                Less
            } else {
                result
            }
        };
        // get min
        for j in 0 .. k + 1 {
            if !poss[i + 1][k - j] || !dp[i][j] { continue; }
            if cmp(&cs, j) == Less {
                cs[i + 1] = cs[i].clone();
            }
        }
        for j in 0 .. k - len + 1 {
            if !poss[i + 1][k - j - len] || !dp[i][j] { continue; }
            if cmps(&cs, j) == Less {
                cs[i + 1] = cs[i][..j].to_vec();
                cs[i + 1].extend_from_slice(&s[i]);
            }
        }
        // update dp
        for j in 0 .. k + 1 {
            if !poss[i + 1][k - j] || !dp[i][j] { continue; }
            dp[i + 1][j] |= cmp(&cs, j) != Greater;
        }
        for j in 0 .. k - len + 1 {
            if !poss[i + 1][k - j - len] || !dp[i][j] { continue; }
            dp[i + 1][j + len] |= cmps(&cs, j) != Greater;
        }
    }
    /*
    eprintln!("dp = {:?}", dp);
    for v in cs.iter() {
        eprintln!("{}", v.clone().into_iter().collect::<String>());
    }
    // */
    puts!("{}\n", cs[n][..k].iter().cloned().collect::<String>());
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

use std::io::BufRead;

fn main() {
    let stdin = std::io::stdin();
    let (n, k): (usize, usize) = stdin.lock().gets().split(' ').values();
    let strings = stdin.lock().lines().take(n)
        .map(|x| x.unwrap().into_bytes()).collect::<Vec<_>>();

    let mut best = vec![None; k + 1];
    best[0] = Some(Vec::new());
    for s in strings.iter().rev() {
        for len in (0..(k + 1 - s.len())).rev() {
            let newlen = s.len() + len;
            assert!(newlen <= k);
            let (best1, mut best2) = best.split_at_mut(newlen);
            if let Some(ref best1str) = best1[len] {
                if let Some(ref best2str) = best2[0] {
                    if !concat_lt(s, best1str, best2str) {
                        continue;
                    }
                }
                let mut newstr = s.clone();
                newstr.extend_from_slice(best1str);
                best2[0] = Some(newstr);
            }
        }
    }
    println!("{}", String::from_utf8_lossy(best[k].as_ref().unwrap()));
}

// Check if a1 + a2 is less than b.
// The lengths of a1 + a2 and b must be equal.
fn concat_lt(a1: &[u8], a2: &[u8], b: &[u8]) -> bool {
    use std::cmp::Ordering::*;
    match a1.cmp(&b[..a1.len()]) {
        Less => true,
        Equal => a2 < &b[a1.len()..],
        Greater => false,
    }
}

trait Gets { fn gets(&mut self) -> String; }
impl<T: std::io::BufRead> Gets for T {
    fn gets(&mut self) -> String { self.lines().next().unwrap().unwrap() } }

trait Values<T> { fn values(&mut self) -> T; }
impl<'a, I, T1, T2> Values<(T1, T2)> for I
    where I: Iterator<Item=&'a str>,
          T1: std::str::FromStr, T1::Err: std::fmt::Debug,
          T2: std::str::FromStr, T2::Err: std::fmt::Debug {
    fn values(&mut self) -> (T1, T2) {
        (self.next().unwrap().parse().unwrap(),
         self.next().unwrap().parse().unwrap())
    }
}

#![allow(unused_imports, unused_variables, dead_code)]
use std::io::*;
use std::fmt::*;
use std::str::*;
use std::cmp::*;
use std::collections::*;

trait InputValue {
    fn parse(s: &str) -> Self;
}

fn read<T: InputValue>() -> T {
    let mut buf = String::new();
    let _ = stdin().read_line(&mut buf);
    T::parse(&buf.trim())
}

fn readnc<T: InputValue>() -> Vec<T> {
    let mut vec = vec![];
    let line: String = read();
    for token in line.split_whitespace() {
        vec.push(T::parse(token));
    }
    vec
}

fn readn<T: InputValue>(n: usize) -> Vec<T> {
    let mut vec = vec![];
    for _ in 0..n {
        vec.push(read());
    }
    vec
}

macro_rules! parse_single_value {
    ($($t:ty),*) => {
        $(
            impl InputValue for $t {
                fn parse(s: &str) -> $t { s.parse().unwrap() }
            }
        )*
	}
}
parse_single_value!(i32, i64, f32, f64, usize, String);

macro_rules! parse_tuple {
	($($t:ident),*) => {
		impl<$($t),*> InputValue for ($($t),*) where $($t: InputValue),* {
			fn parse(s: &str) -> ($($t),*) {
				let mut tokens = s.split_whitespace();
				let t = ($($t::parse(tokens.next().unwrap())),*);
				t
			}
		}
	}
}
parse_tuple!(A, B);
parse_tuple!(A, B, C);

